/* «Tal día como hoy»: una curiosidad para cada día del año (366, con el 29 de febrero).
   La usan la caja de la portada (assets/tal-dia.md), la página efemerides.qmd y la newsletter.
   Formato de la clave: "MM-DD". Campos: anno (año o «calendario romano» / «por estas fechas»),
   titulo, texto (resumen corto para la portada), mas (texto completo) y fuente (siempre).
   Solo fechas bien documentadas; si una fecha es tradicional o discutida, el texto lo dice.
   Las fechas romanas anteriores a la reforma de César (45 a. n. e.) son las del calendario de entonces. */
window.ECOS_EFEMERIDES = {
  "01-01": {"anno": "153 y 45 a. n. e.", "titulo": "El 1 de enero es un invento romano", "texto": "Desde el 153 a. n. e. los cónsules toman posesión el 1 de enero, y en el 45 a. n. e. entra en vigor el calendario de César.", "mas": "Durante siglos los cónsules empezaban su mandato en marzo o en otras fechas. En el 153 a. n. e., con la guerra de Hispania urgiendo, se adelantó la toma de posesión a las calendas de enero para que los nuevos magistrados llegaran a tiempo a la campaña. Un siglo después, el 1 de enero del 45 a. n. e., empezó a regir el calendario juliano, que con el retoque gregoriano de 1582 es el que seguimos usando.", "fuente": "Livio, Periochae 47; Macrobio, Saturnales 1, 14"},
  "01-02": {"anno": "1872", "titulo": "Nietzsche publica El nacimiento de la tragedia", "texto": "Un joven catedrático de filología griega en Basilea publica un libro sobre lo apolíneo y lo dionisíaco que escandaliza a sus colegas.", "mas": "Friedrich Nietzsche tenía 27 años y era profesor de filología clásica en Basilea. En el libro explica la tragedia ática como el encuentro de dos impulsos, el orden luminoso de Apolo y la embriaguez de Dioniso. El filólogo Ulrich von Wilamowitz le respondió con un panfleto demoledor, «¡Filología del futuro!», y la carrera académica de Nietzsche no se recuperó. El libro, en cambio, sigue leyéndose.", "fuente": "F. Nietzsche, Die Geburt der Tragödie aus dem Geiste der Musik, Leipzig, 1872"},
  "01-03": {"anno": "106 a. n. e.", "titulo": "Nace Cicerón en Arpino", "texto": "El orador, abogado, cónsul y filósofo que mejor conocemos de toda la Antigüedad, gracias a sus discursos y a cientos de cartas.", "mas": "Marco Tulio Cicerón nació en una familia ecuestre de Arpino, sin antepasados en el Senado: un homo novus. Él mismo menciona su cumpleaños en sus cartas a Ático. Llegó a cónsul en el 63 a. n. e., el año de la conjuración de Catilina, y dejó la mayor colección de textos de un solo autor romano: discursos, tratados de retórica y filosofía y unas novecientas cartas que nos dejan asomarnos a la vida política del final de la República.", "fuente": "Cicerón, Cartas a Ático 7, 5, 3 y 13, 42; Plutarco, Cicerón 2, 1"},
  "01-04": {"anno": "46 a. n. e.", "titulo": "Ruspina, en el año más largo de la historia", "texto": "César se ve rodeado en África y salva a su ejército a duras penas. Era el año 46 a. n. e., que duró 445 días.", "mas": "El calendario romano se había desajustado tanto que las fechas oficiales iban meses por delante de las estaciones. En la batalla de Ruspina, en el actual Túnez, Labieno estuvo a punto de destruir a las tropas recién desembarcadas de César. Ese mismo año, César, como pontífice máximo, añadió meses extra para devolver el calendario a su sitio: el 46 a. n. e. tuvo 445 días y los romanos lo llamaron «el año de la confusión».", "fuente": "Guerra de África 6-18; Macrobio, Saturnales 1, 14, 3; Censorino, Sobre el día natal 20, 8"},
  "01-05": {"anno": "Heródoto, s. V a. n. e.", "titulo": "Los magos eran una tribu de los medos", "texto": "En la víspera de Reyes, una curiosidad: la palabra «mago» llega de Persia a través del griego, y Heródoto la usa para una tribu de sacerdotes.", "mas": "Heródoto cuenta que los medos se dividían en seis tribus y una de ellas eran los magos (mágoi), encargados de los sacrificios y de interpretar sueños. Por eso, cuando el Evangelio de Mateo habla de unos mágoi venidos de Oriente, un lector griego pensaba en sabios persas que leían las estrellas, no en reyes. La corona llegó mucho después, en la tradición medieval.", "fuente": "Heródoto 1, 101 y 1, 107; Evangelio de Mateo 2, 1-12"},
  "01-06": {"anno": "1822", "titulo": "Nace Heinrich Schliemann", "texto": "El comerciante alemán que se empeñó en encontrar Troya y acabó excavando en Hisarlik, Micenas y Tirinto.", "mas": "Schliemann hizo fortuna con el comercio y decidió dedicarla a demostrar que la guerra de Troya había existido. Desde 1871 excavó la colina de Hisarlik, en Turquía, siguiendo los pasos de Frank Calvert. Sus métodos destruyeron capas enteras y él adornó a menudo sus propios relatos, pero puso Troya y Micenas en el mapa de la arqueología. La Troya de Homero se busca hoy en los niveles VI y VII, no en el que él creyó.", "fuente": "D. Traill, Schliemann of Troy: Treasure and Deceit, Londres, 1995"},
  "01-07": {"anno": "1610", "titulo": "Galileo ve las lunas de Júpiter", "texto": "Con su anteojo, Galileo observa tres «estrellas» junto a Júpiter. Pronto serán cuatro lunas con nombres de amantes de Zeus.", "mas": "Galileo anotó la observación en enero de 1610 y la publicó ese mismo año en el Sidereus nuncius. Las llamó «astros mediceos» para halagar a los Medici, pero triunfaron los nombres que propuso Simon Marius en 1614: Ío, Europa, Ganímedes y Calisto, cuatro amores de Júpiter según la mitología. Siglos después, los astrónomos siguen bautizando las lunas de Júpiter con nombres de la misma familia mitológica.", "fuente": "G. Galilei, Sidereus nuncius, Venecia, 1610; S. Marius, Mundus Iovialis, 1614"},
  "01-08": {"anno": "calendario romano", "titulo": "Por qué el año empieza por Jano", "texto": "Enero es el mes de Jano, el dios de las puertas y de los comienzos, que mira a la vez hacia atrás y hacia delante.", "mas": "Según la tradición, el rey Numa añadió enero y febrero a un calendario que antes empezaba en marzo. Ovidio pregunta al propio Jano por qué tiene dos caras y el dios responde que guarda las puertas del cielo y vigila a la vez la entrada y la salida. Su templo en el Foro se cerraba solo en tiempo de paz, cosa que ocurrió poquísimas veces: Augusto presume en sus Res gestae de haberlo cerrado tres.", "fuente": "Ovidio, Fastos 1, 63-144; Macrobio, Saturnales 1, 13, 3; Augusto, Res gestae 13"},
  "01-09": {"anno": "calendario romano", "titulo": "Agonalia, la fiesta de Jano", "texto": "El rex sacrorum sacrificaba un carnero a Jano. Ni los propios romanos sabían ya de dónde venía el nombre de la fiesta.", "mas": "Ovidio dedica varios versos a repasar las explicaciones del nombre Agonalia: ¿venía de la pregunta «agone?» («¿lo hago?») que hacía el sacerdote antes de herir a la víctima?, ¿de agonia, un nombre antiguo de las víctimas?, ¿de los juegos (agones) griegos? Es un buen ejemplo de cómo los romanos de época de Augusto investigaban, como nosotros, el sentido de unos ritos que ya no entendían del todo.", "fuente": "Ovidio, Fastos 1, 317-336; Varrón, Sobre la lengua latina 6, 12"},
  "01-10": {"anno": "49 a. n. e.", "titulo": "César cruza el Rubicón", "texto": "Con una legión, César pasa el riachuelo que separaba su provincia de Italia. Es el comienzo de la guerra civil.", "mas": "Cruzar en armas el límite de la provincia era declararse enemigo del Senado. Suetonio cuenta que César dudó en la orilla y que, al decidirse, dijo «iacta alea est», «la suerte está echada»; Plutarco dice que lo pronunció en griego, citando a Menandro. La fecha del 10 de enero se deduce de las cartas de Cicerón y corresponde al calendario romano de entonces, que iba desajustado respecto a las estaciones.", "fuente": "Suetonio, César 31-33; Plutarco, César 32; Plutarco, Pompeyo 60"},
  "01-11": {"anno": "calendario romano", "titulo": "Carmentalia, la fiesta de las profetisas", "texto": "Los días 11 y 15 de enero se honraba a Carmenta, la ninfa que cantaba el futuro y que, según la leyenda, adaptó las letras al latín.", "mas": "Carmenta era la madre de Evandro, el rey arcadio que se instaló en el Palatino antes de la fundación de Roma. Su nombre se relaciona con carmen, «canto» y también «fórmula profética». Higino le atribuye haber adaptado al latín quince letras del alfabeto griego. Sus devotas evitaban entrar en su santuario con prendas de cuero, porque nada muerto podía tocar a la diosa.", "fuente": "Ovidio, Fastos 1, 461-636; Higino, Fábulas 277"},
  "01-12": {"anno": "1628", "titulo": "Nace Charles Perrault y, con él, una pelea", "texto": "El autor de los cuentos encendió en Francia la «querella de los antiguos y los modernos»: ¿quién escribe mejor, Homero o los contemporáneos?", "mas": "En 1687 Perrault leyó en la Academia francesa un poema que ponía el siglo de Luis XIV por encima del de Augusto. Boileau y Racine defendieron a los antiguos y la discusión se extendió a toda Europa durante décadas: en Inglaterra se convirtió en la «batalla de los libros» de Swift. En el fondo, la pregunta sigue viva: ¿por qué seguir leyendo a los clásicos si ya no vivimos como ellos?", "fuente": "Ch. Perrault, Le siècle de Louis le Grand, 1687; J. Swift, The Battle of the Books, 1704"},
  "01-13": {"anno": "27 a. n. e.", "titulo": "Octaviano «devuelve» la república", "texto": "En los idus de enero entrega las provincias al Senado y al pueblo. Él mismo lo contará como el gesto que fundó su poder.", "mas": "Tras la victoria sobre Antonio y Cleopatra, Octaviano lo controlaba todo. Su jugada maestra fue renunciar a los poderes extraordinarios ante el Senado, que respondió rogándole que conservara buena parte de las provincias y los ejércitos. En sus Res gestae lo presenta como un acto de restauración. Los historiadores modernos lo leen como el nacimiento del principado: una monarquía con apariencia de república.", "fuente": "Augusto, Res gestae 34; Dion Casio 53, 2-12; Ovidio, Fastos 1, 589-590"},
  "01-14": {"anno": "1506", "titulo": "Aparece el Laocoonte en una viña de Roma", "texto": "Un vecino que cavaba en su viña del Esquilino encuentra el grupo escultórico que Plinio había descrito como la mejor obra de arte.", "mas": "Plinio el Viejo había escrito que el Laocoonte, obra de tres escultores de Rodas, estaba en la casa de Tito y era preferible a cualquier pintura o bronce. Cuando apareció, el papa Julio II envió a Giuliano da Sangallo y este se llevó a Miguel Ángel; reconocieron la obra al instante por la descripción de Plinio. Desde entonces el sacerdote troyano y sus hijos atrapados por las serpientes se convirtieron en modelo del dolor en el arte.", "fuente": "Plinio el Viejo, Historia natural 36, 37; carta de Francesco da Sangallo, 1567"},
  "01-15": {"anno": "69 n. e.", "titulo": "Asesinan a Galba en el Foro", "texto": "El anciano emperador muere a manos de los pretorianos que había ofendido. Otón ocupa su lugar: es el año de los cuatro emperadores.", "mas": "Galba había llegado al poder tras la caída de Nerón, pero se negó a pagar a los pretorianos lo prometido: decía que él elegía soldados, no los compraba. Otón, que esperaba ser adoptado, se los ganó. Tácito resume a Galba con una frase célebre: todos lo habrían considerado capaz de gobernar si no hubiera gobernado. Ese mismo día era también la segunda fiesta de Carmenta.", "fuente": "Tácito, Historias 1, 27-49; Suetonio, Galba 19-20; Plutarco, Galba 24-28"},
  "01-16": {"anno": "27 a. n. e.", "titulo": "Octaviano recibe el nombre de Augusto", "texto": "Tres días después de «devolver» la república, el Senado le da el título de Augustus, «venerable», con el que pasará a la historia.", "mas": "Se discutió llamarlo Rómulo, como segundo fundador de Roma, pero el nombre olía a rey y a fratricidio. Augustus, en cambio, era una palabra del lenguaje religioso, emparentada con augur y augere («aumentar»): situaba a su portador por encima de los hombres sin decir exactamente qué era. El mes Sextilis acabaría llamándose agosto en su honor.", "fuente": "Suetonio, Augusto 7, 2; Dion Casio 53, 16; Fastos de Preneste; Augusto, Res gestae 34"},
  "01-17": {"anno": "395 n. e.", "titulo": "Muere Teodosio, el último emperador de todo el Imperio", "texto": "Nacido en Hispania, muere en Milán. Tras él, el Imperio queda dividido entre sus hijos y nunca volverá a tener un solo señor.", "mas": "Teodosio era hispano, probablemente de Cauca (Coca, Segovia). Convirtió el cristianismo niceno en religión oficial y prohibió los sacrificios paganos. A su muerte, Arcadio se quedó con Oriente y Honorio, un niño, con Occidente. Ambrosio de Milán pronunció su elogio fúnebre cuarenta días después. La división en dos partes no se pensó como definitiva, pero lo fue.", "fuente": "Ambrosio, Sobre la muerte de Teodosio; Zósimo 4, 59; Consularia Constantinopolitana, año 395"},
  "01-18": {"anno": "52 a. n. e.", "titulo": "Muere Clodio en la vía Apia", "texto": "Las bandas de Clodio y de Milón se cruzan cerca de Bovillas. Clodio acaba muerto y Cicerón tendrá que defender a Milón.", "mas": "Clodio y Milón llevaban años enfrentándose en Roma con bandas armadas. El encuentro en la vía Apia fue casual, pero la pelea acabó con Clodio rematado en una posada. Sus partidarios quemaron el cadáver en la curia, que ardió con él. Cicerón defendió a Milón, pero, intimidado por los soldados que rodeaban el foro, habló mal y perdió. El discurso que leemos, el Pro Milone, es la versión pulida que escribió después.", "fuente": "Asconio, Comentario al Pro Milone 31-35; Cicerón, Pro Milone; Dion Casio 40, 48-54"},
  "01-19": {"anno": "calendario romano", "titulo": "Contar los días hacia atrás", "texto": "Hoy, para un romano, no era el 19 de enero sino «el día 14 antes de las calendas de febrero». Contaban la cuenta atrás hasta la fecha siguiente.", "mas": "Los romanos fijaban tres días en cada mes: las calendas (el día 1), las nonas (el 5 o el 7) y los idus (el 13 o el 15). Los demás se nombraban por cuántos días faltaban para el siguiente, contando los dos extremos: ante diem XIV Kalendas Februarias. La caja de la portada calcula cada día este nombre a partir de la fecha de hoy.", "fuente": "Varrón, Sobre la lengua latina 6, 27-28; Macrobio, Saturnales 1, 15"},
  "01-20": {"anno": "250 n. e.", "titulo": "Decio ordena sacrificar a todos los habitantes del Imperio", "texto": "Muere el obispo de Roma, Fabián. Es el primer intento de imponer a todo el Imperio un mismo gesto religioso, con certificado incluido.", "mas": "Decio exigió que cada habitante sacrificara a los dioses ante una comisión y recibiera un justificante, el libellus. En Egipto se han conservado decenas de estos certificados en papiro. Para los cristianos, cumplir era apostatar y negarse podía costar la vida. El calendario cristiano de Roma del año 354 recuerda a Fabián en esta fecha.", "fuente": "Eusebio, Historia eclesiástica 6, 39-41; Cipriano, Sobre los apóstatas; papiros de los libelli (P. Mich. 157 y otros)"},
  "01-21": {"anno": "c. 304 n. e.", "titulo": "Inés de Roma en el calendario del año 354", "texto": "Uno de los calendarios más antiguos de la Iglesia de Roma marca este día la memoria de Inés, una adolescente mártir.", "mas": "El Cronógrafo del 354 es un códice de lujo hecho para un aristócrata romano: incluye el calendario de las fiestas paganas y, a la vez, la lista de mártires cristianos que se recordaban en la ciudad. Es el mejor testimonio de una Roma de transición, en la que las dos tradiciones convivían en el mismo libro. Inés aparece enterrada en la vía Nomentana.", "fuente": "Cronógrafo de 354, Depositio martyrum; Ambrosio, Sobre las vírgenes 1, 2"},
  "01-22": {"anno": "304 n. e.", "titulo": "Vicente, el mártir de Valentia", "texto": "El diácono de Caesaraugusta muere en Valentia durante la persecución de Diocleciano. Prudencio le dedicará un largo himno.", "mas": "Vicente era diácono del obispo Valero de Caesaraugusta (Zaragoza). Llevados ambos a Valentia, el gobernador Daciano lo hizo torturar hasta la muerte. El poeta hispano Prudencio, un siglo después, convirtió su pasión en uno de los himnos del Peristephanon, el libro de las coronas de los mártires. Es uno de los ejemplos de cómo la poesía latina cristiana de Hispania usa los recursos de Virgilio y Horacio.", "fuente": "Prudencio, Peristephanon 5; Agustín, Sermones 274-277"},
  "01-23": {"anno": "calendario romano", "titulo": "Cada ocho días, mercado", "texto": "Los romanos tenían una «semana» de ocho días: cada noveno día, contando a la manera inclusiva, era la nundina, el día de mercado.", "mas": "En los calendarios pintados se marcaban los días con las letras de la A a la H, y una de ellas señalaba las nundinae. Ese día los campesinos bajaban a la ciudad a vender y a enterarse de las leyes, que debían anunciarse durante tres nundinas seguidas antes de votarse. La semana de siete días, con los nombres de los planetas, se impuso más tarde, ya en época imperial.", "fuente": "Macrobio, Saturnales 1, 16, 32-36; Dion Casio 37, 18"},
  "01-24": {"anno": "41 n. e.", "titulo": "Asesinan a Calígula", "texto": "Los tribunos pretorianos lo apuñalan en un pasillo del Palatino durante los juegos palatinos. Tenía 28 años.", "mas": "Suetonio cuenta que el tribuno Casio Querea, al que Calígula humillaba dándole santos y señas obscenos, fue el primero en herirlo. También mataron a su mujer, Cesonia, y a su hija pequeña. Ese mismo día, curiosamente, era el cumpleaños de Adriano, que nació en el 76: un emperador de muy distinta fama.", "fuente": "Suetonio, Calígula 56-58; Flavio Josefo, Antigüedades judías 19, 1; Historia Augusta, Adriano 1, 3"},
  "01-25": {"anno": "41 n. e.", "titulo": "Claudio, emperador escondido tras una cortina", "texto": "Al día siguiente de la muerte de Calígula, un soldado encuentra a su tío Claudio temblando detrás de una cortina y lo aclama emperador.", "mas": "Claudio tenía cincuenta años, cojeaba y tartamudeaba, y su familia lo había mantenido lejos de la política. Mientras el Senado debatía si restaurar la república, los pretorianos lo llevaron a su campamento y lo proclamaron. Resultó ser un gobernante activo y un erudito: escribió una historia de los etruscos y propuso añadir tres letras nuevas al alfabeto latino.", "fuente": "Suetonio, Claudio 10 y 41-42; Flavio Josefo, Antigüedades judías 19, 212-273"},
  "01-26": {"anno": "calendario romano", "titulo": "Sementivae: la fiesta de la siembra", "texto": "A finales de enero, en fecha que fijaban los pontífices, el campo celebraba las sementeras con tortas y una cerda preñada para Ceres y la Tierra.", "mas": "Era una feria movible (feriae conceptivae): no tenía día fijo, sino que se anunciaba cada año. Ovidio la describe en enero y pide a los bueyes que descansen con guirnaldas y a los campesinos que ofrezcan espelta y tortas. Termina el pasaje con un elogio de la paz: el arado vuelve a la tierra y la espada al cobertizo.", "fuente": "Ovidio, Fastos 1, 657-704; Varrón, Sobre la lengua latina 6, 26"},
  "01-27": {"anno": "1756", "titulo": "Nace Mozart, que puso música a Tito y a Idomeneo", "texto": "Dos de sus óperas serias miran a la Antigüedad: Idomeneo, rey de Creta y La clemencia de Tito, sobre el emperador que perdona a quien quiso matarlo.", "mas": "La clemencia de Tito se estrenó en Praga en 1791 para la coronación de Leopoldo II, con libreto basado en Metastasio. El tema venía de Suetonio, que retrata a Tito como «amor y delicia del género humano». Idomeneo (1781) recoge un mito cercano a Jefté: el rey cretense que promete sacrificar al primero que vea al desembarcar y ve a su hijo.", "fuente": "W. A. Mozart, Idomeneo (1781) y La clemenza di Tito (1791); Suetonio, Tito 1 y 9"},
  "01-28": {"anno": "98 n. e.", "titulo": "Trajano, primer emperador nacido en Hispania", "texto": "Muere Nerva y su hijo adoptivo, Marco Ulpio Trajano, natural de Itálica, pasa a gobernar el Imperio. Ni siquiera estaba en Roma.", "mas": "Trajano estaba en Germania cuando le llegó la noticia y no entró en Roma hasta el año siguiente, a pie, saludando a la gente. Era el primer emperador nacido fuera de Italia. Con él el Imperio alcanzó su mayor extensión. El calendario militar de Dura Europos, en Siria, todavía celebraba en el siglo III el día de su llegada al poder.", "fuente": "Plinio el Joven, Panegírico 22-23; Feriale Duranum; Dion Casio 68, 4"},
  "01-29": {"anno": "calendario romano", "titulo": "Las calendas: el día de pagar", "texto": "La palabra «calendario» viene de calendae, el primer día del mes, cuando vencían los intereses de las deudas. El calendarium era el libro de cuentas.", "mas": "Según Varrón, el primer día del mes un pontífice «llamaba» (calare) al pueblo para anunciar cuándo caerían las nonas: de ahí calendae. Como en esa fecha se pagaban los intereses, el registro de préstamos se llamaba calendarium. Horacio se burla en un epodo del usurero Alfio, que reclama su dinero en los idus y vuelve a prestarlo en las calendas.", "fuente": "Varrón, Sobre la lengua latina 6, 27; Macrobio, Saturnales 1, 15, 9-12; Horacio, Epodos 2, 67-70"},
  "01-30": {"anno": "9 a. n. e.", "titulo": "Se consagra el Ara Pacis", "texto": "El altar de la Paz de Augusto se dedica en el Campo de Marte. La fecha coincidía con el cumpleaños de Livia.", "mas": "El Senado había decidido levantar el altar en el 13 a. n. e., a la vuelta de Augusto de Hispania y la Galia, y se consagró tres años y medio después. Sus relieves muestran a la familia imperial en procesión, con niños tirando de las togas de los mayores. Desenterrado por piezas desde el siglo XVI, se reconstruyó en 1938 junto al mausoleo de Augusto.", "fuente": "Augusto, Res gestae 12; Ovidio, Fastos 1, 709-722; Fastos de Preneste"},
  "01-31": {"anno": "calendario romano", "titulo": "Febrero, el mes de la purificación", "texto": "Mañana empieza febrero, cuyo nombre viene de februa, los objetos y ritos que limpiaban de impurezas. Era el último mes del año antiguo.", "mas": "Ovidio explica que los romanos llamaban februa a todo lo que purificaba: la lana, la sal tostada, las ramas de pino. Febrero, el mes de las expiaciones y de los muertos, cerraba el año cuando este comenzaba en marzo. Por eso, cuando hubo que añadir días o meses de ajuste, se colocaron siempre en febrero: allí siguen estando el día bisiesto y el mes de 28 días.", "fuente": "Ovidio, Fastos 2, 19-54; Varrón, Sobre la lengua latina 6, 13"},
  "02-01": {"anno": "194 a. n. e.", "titulo": "Juno Sospita, la diosa con piel de cabra", "texto": "En las calendas de febrero se celebraba el templo de Juno Sospita, la «Salvadora», que se representaba armada y cubierta con una piel de cabra.", "mas": "Su culto principal estaba en Lanuvio, cerca de Roma, y los cónsules acudían allí cada año a ofrecerle sacrificios. Las monedas la muestran con lanza, escudo, zapatos de punta curva y la cabeza de cabra como casco. Ovidio cuenta que en su tiempo el templo de Roma ya estaba en ruinas y que Augusto, gran restaurador de santuarios, se encargaría de él.", "fuente": "Ovidio, Fastos 2, 55-66; Livio 34, 53, 3; Cicerón, Sobre la naturaleza de los dioses 1, 82"},
  "02-02": {"anno": "1922", "titulo": "Joyce publica Ulises el día de su cumpleaños", "texto": "La novela que traslada la Odisea a un solo día de Dublín sale en París, en la librería Shakespeare and Company, el día en que Joyce cumplía 40 años.", "mas": "Cada capítulo de Ulises corresponde a un episodio del poema homérico: Leopold Bloom es Odiseo, Stephen Dedalus es Telémaco y Molly Bloom, una Penélope bastante menos fiel. Joyce quitó los títulos homéricos de los capítulos al publicarla, pero los dejó circular entre sus amigos. La acción sucede el 16 de junio de 1904, el día que hoy se celebra como Bloomsday.", "fuente": "J. Joyce, Ulysses, París, Shakespeare and Company, 1922"},
  "02-03": {"anno": "1909", "titulo": "Nace Simone Weil, lectora de la Ilíada", "texto": "La filósofa francesa escribió en plena Segunda Guerra Mundial un ensayo célebre: «La Ilíada o el poema de la fuerza».", "mas": "Para Weil, el verdadero protagonista de la Ilíada es la fuerza, que convierte en cosa a quien la sufre y también a quien la ejerce. Admiraba que Homero tratara con la misma compasión a griegos y troyanos, y que ningún personaje quedara a salvo. El ensayo se publicó en 1940-1941 y sigue siendo una de las lecturas modernas más influyentes del poema.", "fuente": "S. Weil, «L'Iliade ou le poème de la force», Cahiers du Sud, 1940-1941"},
  "02-04": {"anno": "1944", "titulo": "Antígona en el París ocupado", "texto": "Jean Anouilh estrena su Antígona con la ciudad bajo ocupación alemana. La censura la deja pasar; el público entiende otra cosa.", "mas": "Anouilh mantuvo el conflicto de Sófocles, la hija de Edipo que entierra a su hermano contra la orden de Creonte, pero le dio a Creonte argumentos razonables de gobernante pragmático. Unos vieron en la obra un elogio de la resistencia y otros una justificación del orden. Es un buen ejemplo de cómo una tragedia griega puede leerse en sentidos opuestos según el momento.", "fuente": "J. Anouilh, Antigone, estrenada en el Théâtre de l'Atelier, París, 1944; Sófocles, Antígona"},
  "02-05": {"anno": "62 n. e.", "titulo": "Un terremoto sacude Pompeya", "texto": "Diecisiete años antes del Vesubio, un fuerte seísmo daña Pompeya y Herculano. Muchos edificios seguían en obras en el 79.", "mas": "Séneca dedica al terremoto el libro sexto de sus Cuestiones naturales y da la fecha: las nonas de febrero. Cuenta que murió un rebaño de seiscientas ovejas, quizá por gases, y que hubo gente que perdió el juicio. Un relieve del lararium de la casa de Cecilio Jucundo, en Pompeya, parece representar el templo de Júpiter tambaleándose. Tácito lo sitúa en el 62; algunos estudiosos prefieren el 63. Ese mismo día, en el 2 a. n. e., Augusto había recibido el título de Padre de la Patria.", "fuente": "Séneca, Cuestiones naturales 6, 1, 1-3; Tácito, Anales 15, 22; Augusto, Res gestae 35"},
  "02-06": {"anno": "1515", "titulo": "Muere Aldo Manucio, el impresor de los griegos", "texto": "En Venecia, Aldo imprimió por primera vez a Aristóteles, Platón, Tucídides o Sófocles, e inventó el libro de bolsillo y la letra cursiva.", "mas": "Aldo Manucio fundó su imprenta hacia 1494 con un objetivo: poner los clásicos griegos en manos de los lectores, editados por eruditos, muchos de ellos griegos exiliados tras la caída de Constantinopla. Sus libros en octavo, pequeños y baratos, con texto en cursiva, se podían llevar encima. Su marca, un delfín enroscado en un ancla, ilustra el lema festina lente, «apresúrate despacio».", "fuente": "M. Lowry, The World of Aldus Manutius, Oxford, 1979"},
  "02-07": {"anno": "1478", "titulo": "Nace Tomás Moro, el inventor de Utopía", "texto": "El humanista inglés acuñó una palabra griega con trampa: Utopía puede leerse como «ningún lugar» o como «buen lugar».", "mas": "Moro escribió Utopía en latín en 1516, en diálogo con la República de Platón: una isla con propiedad común, magistrados elegidos y tolerancia religiosa. El nombre juega con el griego ou-tópos, «no lugar», que suena igual que eu-tópos, «lugar feliz», en la pronunciación inglesa. Moro tradujo además a Luciano junto a su amigo Erasmo.", "fuente": "T. More, Utopia, Lovaina, 1516; Platón, República"},
  "02-08": {"anno": "1828", "titulo": "Nace Julio Verne y su capitán «Nadie»", "texto": "El capitán del Nautilus se llama Nemo, que en latín significa «nadie»: el mismo nombre falso con el que Odiseo engaña al cíclope.", "mas": "En la Odisea, Odiseo le dice a Polifemo que se llama Outis, «Nadie». Cuando el cíclope, cegado, pide auxilio gritando que Nadie lo está matando, sus vecinos se marchan. Verne bautizó a su capitán con la traducción latina del nombre: un hombre que ha renunciado a su identidad y vive bajo el mar. Veinte mil leguas de viaje submarino se publicó entre 1869 y 1870.", "fuente": "Homero, Odisea 9, 364-414; J. Verne, Vingt mille lieues sous les mers, 1869-1870"},
  "02-09": {"anno": "por estas fechas", "titulo": "Las Leneas, el festival de comedia en invierno", "texto": "Por estas fechas, en el mes ateniense de Gamelión, Atenas celebraba las Leneas, un festival de Dioniso con concursos de comedia.", "mas": "Como era invierno y no se navegaba, apenas había extranjeros en la ciudad, y los cómicos podían hablar con más libertad de la política ateniense. En las Leneas del 425 a. n. e. Aristófanes ganó con Los acarnienses, una comedia en la que un campesino firma una paz privada con Esparta en plena guerra. Las fechas exactas no pueden traducirse a nuestro calendario, porque el ateniense era lunar.", "fuente": "Aristófanes, Acarnienses 502-508; Escolios a Aristófanes; Pickard-Cambridge, The Dramatic Festivals of Athens, 1968"},
  "02-10": {"anno": "por estas fechas", "titulo": "Antesterias: abrir el vino nuevo", "texto": "Por estas fechas, en el mes de Antesterión, los atenienses abrían las tinajas del vino del otoño y bebían en concurso, cada uno con su jarra y en silencio.", "mas": "La fiesta duraba tres días: Pithoigia («apertura de tinajas»), Choes («jarras») y Chytroi («ollas»). El segundo día se bebía en silencio, en recuerdo de Orestes, al que acogieron en Atenas sin hablarle porque estaba manchado de sangre. Era también una fiesta de los difuntos: se creía que las almas vagaban por la ciudad y se masticaba espino para protegerse.", "fuente": "Tucídides 2, 15, 4; Eurípides, Ifigenia entre los tauros 947-960; Aristófanes, Acarnienses 1000-1234"},
  "02-11": {"anno": "55 n. e.", "titulo": "Muere Británico la víspera de cumplir 14 años", "texto": "El hijo de Claudio cae fulminado en un banquete. Tácito culpa a Nerón y a la envenenadora Locusta.", "mas": "Británico había nacido a los veinte días del reinado de Claudio y estaba a punto de tomar la toga viril, lo que lo convertía en rival de Nerón. Tácito cuenta la escena con detalle: una bebida demasiado caliente, agua fría para templarla y, en ella, el veneno. Nerón dijo a los comensales que era un ataque de epilepsia. Lo enterraron esa misma noche, bajo una lluvia torrencial.", "fuente": "Tácito, Anales 13, 15-17; Suetonio, Nerón 33; Suetonio, Claudio 27"},
  "02-12": {"anno": "calendario romano", "titulo": "Fornacalia, la fiesta de los hornos", "texto": "Por estos días cada curia tostaba su espelta en honor de Fornax, la diosa del horno. El que se despistaba lo celebraba al final, en la «fiesta de los tontos».", "mas": "La Fornacalia era una fiesta movible: el curio maximus anunciaba en el Foro qué día le tocaba a cada una de las treinta curias. Ovidio explica que quien no sabía cuál era su curia lo celebraba el último día, el 17, coincidiendo con las Quirinalia, y por eso la llamaban stultorum feriae, la fiesta de los tontos.", "fuente": "Ovidio, Fastos 2, 513-532; Festo, s. v. Stultorum feriae"},
  "02-13": {"anno": "477 a. n. e.", "titulo": "Los trescientos seis Fabios del Crémera", "texto": "Según Ovidio, en los idus de febrero cayó entera la familia de los Fabios luchando contra Veyes. Solo quedó vivo un niño.", "mas": "Los Fabios se ofrecieron a llevar ellos solos la guerra contra la ciudad etrusca de Veyes y acabaron emboscados junto al río Crémera. La leyenda dice que el único superviviente, un niño que se había quedado en Roma, fue el antepasado de Fabio Máximo. Livio pone la derrota el 18 de julio, el mismo día que el desastre del Alia, y Ovidio en los idus de febrero: un recordatorio de que las fechas de la Roma primitiva son tradición, no historia segura. Hoy empezaban además las Parentalia, los días de los difuntos.", "fuente": "Ovidio, Fastos 2, 193-242; Livio 2, 48-50; Livio 6, 1, 11"},
  "02-14": {"anno": "mito moderno", "titulo": "San Valentín no viene de las Lupercales", "texto": "Se repite mucho que la Iglesia cristianizó las Lupercales con San Valentín. Ninguna fuente antigua lo dice.", "mas": "La relación entre San Valentín y el amor aparece por primera vez en la Inglaterra del siglo XIV, en un poema de Chaucer sobre las aves que eligen pareja en ese día. El papa Gelasio sí escribió contra quienes seguían celebrando las Lupercales a finales del siglo V, pero no las sustituyó por ninguna fiesta de Valentín. Lo que tenemos son dos mártires de ese nombre, muy mal documentados, y una leyenda moderna.", "fuente": "Gelasio I, Carta contra Andrómaco; G. Chaucer, Parlement of Foules, c. 1382; J. Oruch, Speculum 56 (1981)"},
  "02-15": {"anno": "44 a. n. e.", "titulo": "Lupercales: Antonio ofrece una corona a César", "texto": "Durante la fiesta, Marco Antonio le tiende una diadema real ante el pueblo y César la rechaza. Un mes después lo asesinan.", "mas": "En las Lupercales, unos jóvenes semidesnudos corrían alrededor del Palatino golpeando con tiras de piel de cabra a quienes encontraban, sobre todo a las mujeres, para darles fertilidad. Antonio, cónsul y luperco ese año, interrumpió la carrera para ofrecer la diadema a César, sentado en la tribuna. El público aplaudió cuando la rechazó. ¿Prueba o ensayo de una monarquía? Cicerón se lo echaría en cara a Antonio meses después.", "fuente": "Cicerón, Filípicas 2, 84-87; Plutarco, César 61; Ovidio, Fastos 2, 267-452"},
  "02-16": {"anno": "1497", "titulo": "Nace Melanchthon, el maestro de griego de Alemania", "texto": "Philipp Schwarzerd tradujo su apellido al griego, Melanchthon, «tierra negra», y llegó a ser llamado el «preceptor de Alemania».", "mas": "Con 21 años ya era catedrático de griego en Wittenberg, donde se hizo amigo y colaborador de Lutero. Escribió gramáticas griegas y latinas y reorganizó las escuelas protestantes alrededor del estudio de las lenguas clásicas. Helenizar o latinizar el apellido era una moda humanista: Erasmo, Agricola o Melanchthon son nombres de este tipo.", "fuente": "H. Scheible, Melanchthon. Eine Biographie, Múnich, 1997"},
  "02-17": {"anno": "calendario romano", "titulo": "Quirinalia, la fiesta de Rómulo divinizado", "texto": "Hoy se honraba a Quirino, el nombre que recibió Rómulo al subir al cielo. También era el día de los despistados de la Fornacalia.", "mas": "Según la leyenda, Rómulo desapareció en medio de una tormenta y luego se apareció a Próculo Julio para anunciar que se había convertido en el dios Quirino. Los romanos se llamaban a sí mismos Quirites en las asambleas. La fiesta coincidía con el último día de la Fornacalia, la stultorum feriae, para los que no sabían a qué curia pertenecían.", "fuente": "Ovidio, Fastos 2, 475-532; Livio 1, 16; Plutarco, Rómulo 28"},
  "02-18": {"anno": "1930", "titulo": "Descubren Plutón, un nombre propuesto por una niña", "texto": "Clyde Tombaugh encuentra el planeta en unas placas fotográficas. Una niña de once años de Oxford, Venetia Burney, propuso llamarlo como el dios de los muertos.", "mas": "Venetia Burney, aficionada a la mitología, pensó que un mundo tan lejano y oscuro merecía el nombre del señor del inframundo. Su abuelo transmitió la idea a un astrónomo y el observatorio Lowell la eligió, entre otras cosas porque las dos primeras letras eran las iniciales de Percival Lowell. Salvo la Tierra, todos los planetas llevan nombres de dioses romanos, menos Urano, que es el único griego.", "fuente": "Lowell Observatory Observation Circular, 13 de marzo de 1930"},
  "02-19": {"anno": "197 n. e.", "titulo": "Lugdunum: la batalla más grande entre romanos", "texto": "Septimio Severo derrota a Clodio Albino junto a Lyon. Dion Casio habla de 150.000 hombres por bando.", "mas": "Albino había sido nombrado César por Severo, pero acabó proclamándose emperador en Britania y pasó a la Galia. La batalla fue durísima: Severo cayó del caballo y estuvo a punto de perderla. Al final ganó, Albino se suicidó y Severo, cuenta la historia, pisoteó su cadáver con el caballo. Dion, que era senador entonces, dice que la cifra de combatientes fue de unos 150.000 por cada lado; seguramente exagera.", "fuente": "Dion Casio 76, 6-7; Herodiano 3, 7; Historia Augusta, Severo 11"},
  "02-20": {"anno": "calendario romano", "titulo": "Mercedonio, el mes que aparecía y desaparecía", "texto": "Antes de César, algunos años los pontífices metían un mes extra tras las fiestas de finales de febrero. A veces lo hacían por interés político.", "mas": "El calendario romano tenía 355 días y, para cuadrarlo con el sol, se intercalaba un mes de 27 o 28 días tras el 23 o el 24 de febrero. Los pontífices decidían cuándo, y lo usaban para alargar o acortar mandatos de amigos y enemigos. Cicerón, en Cilicia, rogaba en sus cartas que no se intercalara para no quedarse un mes más de gobernador. En el 46 a. n. e. el desajuste era de casi tres meses.", "fuente": "Censorino, Sobre el día natal 20; Macrobio, Saturnales 1, 13-14; Cicerón, Cartas a Ático 5, 13, 3"},
  "02-21": {"anno": "calendario romano", "titulo": "Feralia: comida para los muertos", "texto": "Se cerraban las Parentalia llevando a las tumbas pequeñas ofrendas: guirnaldas, sal, pan mojado en vino, violetas sueltas.", "mas": "Ovidio cuenta que una vez los romanos, absorbidos por la guerra, olvidaron la Feralia, y los muertos salieron de sus tumbas aullando por las calles. Ese día también se hacían ritos de magia para atar lenguas enemigas. Fue también un 21 de febrero, del 4 n. e., cuando murió en Licia Gayo César, nieto y heredero de Augusto.", "fuente": "Ovidio, Fastos 2, 533-616; Cenotafio de Pisa (CIL XI 1421)"},
  "02-22": {"anno": "calendario romano", "titulo": "Caristia, el día de hacer las paces en familia", "texto": "Tras los días de los muertos venía la comida de los vivos: los parientes se reunían y se reconciliaban. Los que estaban peleados, mejor no venir.", "mas": "Ovidio recomienda dejar fuera de la mesa a los hermanos malvados, a las madres crueles y a la suegra que odia a su nuera. Los asistentes ofrecían comida a los lares domésticos y brindaban por el emperador. La palabra viene de carus, «querido»: era, literalmente, la fiesta de los seres queridos.", "fuente": "Ovidio, Fastos 2, 617-638; Valerio Máximo 2, 1, 8"},
  "02-23": {"anno": "303 n. e.", "titulo": "Terminalia, el día que Diocleciano eligió para perseguir", "texto": "En la fiesta del dios de los límites, Diocleciano manda arrasar la iglesia de Nicomedia. Al día siguiente publica el edicto de la gran persecución.", "mas": "Término era el dios de los mojones, y en su fiesta los vecinos coronaban la piedra que separaba sus campos. Lactancio, testigo en Nicomedia, dice que el emperador escogió ese día a propósito para «poner término» al cristianismo. El edicto mandaba quemar las Escrituras y destruir las iglesias. Fue la persecución más dura y la última: diez años después, Constantino y Licinio darían libertad de culto.", "fuente": "Lactancio, Sobre la muerte de los perseguidores 12-13; Ovidio, Fastos 2, 639-684"},
  "02-24": {"anno": "calendario romano", "titulo": "Regifugium, la huida del rey", "texto": "Los romanos recordaban este día la expulsión de Tarquinio el Soberbio, el último rey, y el nacimiento de la república.", "mas": "Ovidio enlaza la fiesta con la historia de Lucrecia, violada por el hijo del rey, y con la rebelión de Bruto. Los anticuarios discutían si el nombre recordaba de verdad aquella huida o un rito en que el rex sacrorum huía tras sacrificar. Curiosamente, el día bisiesto romano se metía justo aquí: el 24 de febrero se repetía, y por eso se llamaba bis sextum, de donde viene «bisiesto».", "fuente": "Ovidio, Fastos 2, 685-852; Livio 1, 57-60; Macrobio, Saturnales 1, 14, 6"},
  "02-25": {"anno": "138 n. e.", "titulo": "Adriano adopta a Antonino", "texto": "Enfermo y sin hijos, Adriano adopta a Antonino con una condición: que este adopte a su vez a dos jóvenes, uno de ellos el futuro Marco Aurelio.", "mas": "Era una sucesión diseñada a dos generaciones vista. Antonino, un senador maduro y respetado, gobernaría veintitrés años de paz; después vendrían Marco Aurelio y Lucio Vero. Así se consolidó la costumbre de que el emperador eligiera a su sucesor por adopción, la que llevó al siglo de los Antoninos, que Gibbon consideró el más feliz de la humanidad.", "fuente": "Historia Augusta, Pío 4, 1-7; Dion Casio 69, 21; E. Gibbon, Decline and Fall, cap. 3"},
  "02-26": {"anno": "1564", "titulo": "Bautizan a Marlowe, el del rostro que lanzó mil naves", "texto": "El dramaturgo inglés escribió el verso más famoso sobre Helena: el del rostro que botó mil barcos y quemó las torres de Ilión.", "mas": "Christopher Marlowe fue bautizado en Canterbury el 26 de febrero de 1564, dos meses antes que Shakespeare. En Doctor Fausto, el sabio que vende su alma conjura el espíritu de Helena de Troya. Marlowe tradujo además los Amores de Ovidio y el primer libro de la Farsalia de Lucano, y escribió una Dido, reina de Cartago a partir de la Eneida.", "fuente": "Registro parroquial de St George the Martyr, Canterbury; C. Marlowe, Doctor Faustus, escena 13"},
  "02-27": {"anno": "380 n. e.", "titulo": "El edicto de Tesalónica", "texto": "Teodosio, Graciano y Valentiniano II ordenan que todos los pueblos del Imperio sigan la fe de Roma y Alejandría. Nace una religión de Estado.", "mas": "El edicto, conocido por sus primeras palabras, Cunctos populos, está fechado tres días antes de las calendas de marzo. Califica de «dementes e insensatos» a quienes no acepten el credo niceno. Se ha conservado en el Código Teodosiano, la gran recopilación de leyes imperiales del siglo V. Ese mismo día había nacido Constantino, hacia el 272, según el calendario de Roma del 354.", "fuente": "Código Teodosiano 16, 1, 2; Cronógrafo de 354"},
  "02-28": {"anno": "1533", "titulo": "Nace Montaigne, que aprendió latín antes que francés", "texto": "Su padre le puso un preceptor alemán que solo le hablaba en latín. A los seis años, Montaigne no sabía francés.", "mas": "Lo cuenta el propio Montaigne en sus Ensayos: en casa, hasta los criados aprendieron algunas palabras latinas para poder hablarle. El resultado fue un escritor que leía a Séneca y a Plutarco como a amigos de toda la vida y que llenó sus ensayos de citas clásicas. Plutarco, en la traducción francesa de Amyot, era su libro de cabecera.", "fuente": "M. de Montaigne, Essais 1, 26 («De l'institution des enfants»)"},
  "02-29": {"anno": "45 a. n. e.", "titulo": "El día bisiesto", "texto": "César añadió un día cada cuatro años, pero no al final de febrero: se repetía el día sexto antes de las calendas de marzo. De ahí «bisiesto».", "mas": "En latín, el 24 de febrero era ante diem sextum Kalendas Martias. En los años bisiestos ese día se contaba dos veces: bis sextum, «dos veces sexto». Al principio los pontífices se equivocaron y metieron el día cada tres años, contando de forma inclusiva, hasta que Augusto lo corrigió. La idea de añadir un día cada cuatro años ya la había propuesto en Egipto el decreto de Canopo en el 238 a. n. e., sin éxito.", "fuente": "Macrobio, Saturnales 1, 14, 6-15; Censorino, Sobre el día natal 20, 10; Decreto de Canopo (OGIS 56)"},
  "03-01": {"anno": "c. 40 n. e.", "titulo": "El cumpleaños de Marcial y el viejo año nuevo", "texto": "Marcial, el epigramista nacido en Bílbilis (Calatayud), celebraba su cumpleaños en las calendas de marzo, el antiguo comienzo del año romano.", "mas": "Marcial lo dice en sus epigramas: las calendas de marzo son su día. Era una fecha cargada: el primer día del año en el calendario más antiguo, el día en que se renovaba el fuego de Vesta y en que las mujeres casadas celebraban las Matronalia y recibían regalos. Marcial vivió treinta y cinco años en Roma y volvió a su Bílbilis natal, desde donde escribió con nostalgia de la ciudad que tanto había criticado.", "fuente": "Marcial, Epigramas 10, 24 y 12, 60; Ovidio, Fastos 3, 135-258"},
  "03-02": {"anno": "calendario romano", "titulo": "Los días negros de después", "texto": "El día siguiente a las calendas, nonas e idus era un dies ater, un día de mal agüero en el que no se emprendía nada importante.", "mas": "Aulo Gelio y Macrobio cuentan el origen: el Senado descubrió que varias derrotas, entre ellas la del Alia, habían ocurrido después de sacrificios hechos el día siguiente a una de esas fechas, y los pontífices declararon nefastos esos días. Así, hoy, 2 de marzo, ningún romano prudente habría empezado un viaje ni un negocio.", "fuente": "Aulo Gelio 5, 17; Macrobio, Saturnales 1, 16, 21-24; Livio 6, 1, 11-12"},
  "03-03": {"anno": "1585", "titulo": "Edipo inaugura el Teatro Olímpico de Vicenza", "texto": "El primer teatro cubierto de la Edad Moderna, diseñado por Palladio a partir de Vitruvio, se estrena con Edipo rey de Sófocles.", "mas": "La Academia Olímpica de Vicenza quería recuperar el teatro antiguo y eligió la tragedia que Aristóteles ponía como modelo en la Poética. Se representó en una traducción italiana de Orsatto Giustiniani, con coros con música de Andrea Gabrieli. El escenario fijo de Scamozzi, con calles en perspectiva de madera, se conserva todavía: el decorado de Tebas sigue allí.", "fuente": "Aristóteles, Poética 11 y 14; S. Mazzoni, «Edipo tiranno all'Olimpico di Vicenza (1585)», Dionysus ex machina 4 (2013)"},
  "03-04": {"anno": "1793", "titulo": "Nace Karl Lachmann, el que enseñó a reconstruir textos", "texto": "El filólogo alemán sistematizó cómo comparar manuscritos para reconstruir el texto original de un autor antiguo. Su edición de Lucrecio es célebre.", "mas": "Ningún texto clásico se conserva en el original: nos llegan copias de copias, con errores acumulados durante siglos. Lachmann y su escuela aprendieron a agrupar los manuscritos por sus errores comunes y a dibujar su árbol genealógico, el stemma. En su Lucrecio de 1850 llegó a deducir cómo era, página a página, el manuscrito perdido del que descendían todos los conservados.", "fuente": "K. Lachmann, T. Lucreti Cari De rerum natura libri sex, Berlín, 1850; S. Timpanaro, La genesi del metodo del Lachmann, 1963"},
  "03-05": {"anno": "363 n. e.", "titulo": "Juliano parte de Antioquía hacia Persia", "texto": "El emperador filósofo sale con un gran ejército para conquistar el Imperio persa. No volverá.", "mas": "Amiano Marcelino, que iba en la expedición como oficial, da la fecha: tres días antes de las nonas de marzo. Juliano llegó hasta las murallas de Ctesifonte, pero no logró tomarla, quemó su propia flota y emprendió una retirada penosa por el desierto. Allí, en junio, una lanza le hirió de muerte. Amiano escribió sobre él con admiración y sin ocultar sus errores.", "fuente": "Amiano Marcelino 23, 2, 6; Amiano Marcelino 24-25"},
  "03-06": {"anno": "1493", "titulo": "Nace en Valencia Juan Luis Vives", "texto": "El humanista valenciano, amigo de Erasmo y de Tomás Moro, escribió en latín sobre educación, sobre la mujer y sobre la ayuda a los pobres.", "mas": "Vives salió de Valencia muy joven y nunca volvió: su familia, de origen judío converso, sufrió la Inquisición. Enseñó en Lovaina y en Oxford y escribió una obra inmensa en latín. Su De subventione pauperum (1526) propone que las ciudades organicen la asistencia a los pobres, y sus Diálogos sirvieron durante siglos para aprender latín en las escuelas de Europa.", "fuente": "J. L. Vives, De subventione pauperum, Brujas, 1526; Exercitatio linguae latinae, 1539"},
  "03-07": {"anno": "321 n. e.", "titulo": "Constantino declara festivo el día del Sol", "texto": "Una ley de Constantino ordena que jueces, ciudadanos y artesanos descansen el «venerable día del Sol». Los campesinos, si hace falta, pueden trabajar.", "mas": "La ley, fechada en las nonas de marzo, no habla del domingo cristiano sino del dies Solis, el día que la semana planetaria dedicaba al Sol, y permite las labores del campo para no perder la ocasión de sembrar o vendimiar. Es la primera ley de descanso semanal del mundo romano. En inglés o en alemán el día sigue llamándose del Sol; en las lenguas románicas se impuso dominicus, «del Señor».", "fuente": "Código de Justiniano 3, 12, 2; Código Teodosiano 2, 8, 1"},
  "03-08": {"anno": "42 a. n. e.", "titulo": "Hortensia habla en el Foro por las mujeres", "texto": "En el Día Internacional de la Mujer, una oradora romana: Hortensia se plantó ante los triunviros para protestar por un impuesto a las mujeres ricas.", "mas": "Los triunviros querían que 1.400 mujeres pagaran la guerra. Hortensia, hija del gran orador Hortensio, defendió ante ellos que, si las mujeres no tenían voz en el gobierno ni en la guerra, no debían pagarla. El público la apoyó y al día siguiente el impuesto se redujo a 400 mujeres. Quintiliano dice que su discurso todavía se leía en su época, más de un siglo después, y no solo por ser de una mujer.", "fuente": "Apiano, Guerras civiles 4, 32-34; Valerio Máximo 8, 3, 3; Quintiliano 1, 1, 6"},
  "03-09": {"anno": "calendario romano", "titulo": "Los salios bailan por Roma", "texto": "En marzo, el mes de Marte, los sacerdotes salios recorrían la ciudad con sus escudos sagrados, saltando y cantando un himno que ya nadie entendía.", "mas": "Los salios eran doce jóvenes patricios. Llevaban túnica bordada, coraza y los ancilia, copias del escudo que según la leyenda cayó del cielo en tiempos de Numa. Su canto, el Carmen Saliare, estaba escrito en un latín tan antiguo que, según Quintiliano, ni los propios sacerdotes lo comprendían. Por la noche celebraban banquetes tan famosos que «cena saliar» pasó a significar un festín.", "fuente": "Ovidio, Fastos 3, 259-398; Livio 1, 20, 4; Quintiliano 1, 6, 40; Horacio, Odas 1, 37, 2"},
  "03-10": {"anno": "241 a. n. e.", "titulo": "Las islas Égates: Roma gana su primera guerra en el mar", "texto": "La flota del cónsul Lutacio Cátulo destroza a la cartaginesa frente a Sicilia. Termina la primera guerra púnica.", "mas": "Roma había empezado la guerra sin flota y aprendió a construir barcos copiando un navío cartaginés varado. Tras más de veinte años de lucha, la victoria de las Égates obligó a Cartago a pedir la paz y a ceder Sicilia, la primera provincia romana. Desde 2005 los arqueólogos submarinos han recuperado en la zona decenas de espolones de bronce de los barcos hundidos en la batalla.", "fuente": "Polibio 1, 59-63; Eutropio 2, 27; S. Tusa y J. Royal, Journal of Roman Archaeology 25 (2012)"},
  "03-11": {"anno": "1903", "titulo": "Nace Ronald Syme, el historiador de la revolución romana", "texto": "El neozelandés Syme publicó en 1939 La revolución romana, un retrato de Augusto como jefe de facción escrito con Mussolini y Hitler en el horizonte.", "mas": "Syme estudió cómo Augusto llegó al poder rodeado de una red de partidarios y cómo la vieja aristocracia fue sustituida por hombres nuevos. Su estilo, seco y lleno de ironía, imita a Tácito, su gran modelo, al que dedicó dos volúmenes. La revolución romana se publicó en septiembre de 1939, días después de empezar la Segunda Guerra Mundial.", "fuente": "R. Syme, The Roman Revolution, Oxford, 1939; Tacitus, Oxford, 1958"},
  "03-12": {"anno": "604 n. e.", "titulo": "Muere Gregorio Magno, un papa con mentalidad de cónsul", "texto": "Hijo de una familia senatorial y antiguo prefecto de Roma, Gregorio gobernó la ciudad cuando ya no había emperador en Occidente.", "mas": "Gregorio había sido praefectus urbi antes de hacerse monje. Como papa organizó el abastecimiento de Roma, negoció con los lombardos y envió misioneros a Britania. Sus cartas, más de ochocientas, muestran a un administrador a la romana en un mundo que ya era otro. Es una de las figuras que marcan el paso de la Antigüedad a la Edad Media.", "fuente": "Gregorio Magno, Registrum epistularum; Liber pontificalis 66"},
  "03-13": {"anno": "1781", "titulo": "Herschel descubre Urano, el único planeta con nombre griego", "texto": "Desde su jardín de Bath, William Herschel ve un astro que resulta ser un planeta nuevo. Acabará llamándose como el dios griego del cielo.", "mas": "Herschel quiso llamarlo «estrella de Jorge», en honor del rey Jorge III, y otros propusieron «Herschel». Se impuso la propuesta del astrónomo Johann Bode: si Saturno era padre de Júpiter, el nuevo planeta, más lejano, debía llevar el nombre del padre de Saturno, Urano. Es el único planeta con nombre de dios griego y no romano.", "fuente": "W. Herschel, Philosophical Transactions 71 (1781); J. E. Bode, Von dem neu entdeckten Planeten, 1784"},
  "03-14": {"anno": "190 a. n. e.", "titulo": "Un eclipse delata el desfase del calendario", "texto": "Livio anota un eclipse de sol el 11 de julio romano. Los astrónomos lo identifican con el del 14 de marzo: el calendario iba cuatro meses adelantado.", "mas": "Livio cuenta que, durante los Juegos Apolinares, en pleno día, la luz se oscureció. Calculando hacia atrás los eclipses, los astrónomos saben que el de ese año ocurrió en lo que para nosotros es el 14 de marzo. Es la prueba de lo desajustado que estaba el calendario republicano antes de la reforma de César. Hoy es además el Día de Pi, y fue Arquímedes quien primero acotó su valor entre 3 10/71 y 3 1/7.", "fuente": "Livio 37, 4, 4; Arquímedes, Medida del círculo, proposición 3"},
  "03-15": {"anno": "44 a. n. e.", "titulo": "Idus de marzo: asesinan a Julio César", "texto": "Lo apuñalan en la curia de Pompeyo, a los pies de la estatua de su viejo rival.", "mas": "Unos sesenta senadores participaron en la conjura, encabezada por Bruto y Casio. Suetonio cuenta que César recibió veintitrés puñaladas y que solo una, la segunda, fue mortal, según el médico Antistio: es la primera autopsia de la que tenemos noticia. La frase «¿Tú también, hijo?» la recoge Suetonio como algo que «algunos dicen», en griego, y la célebre «Et tu, Brute?» es de Shakespeare.", "fuente": "Suetonio, César 80-82; Plutarco, César 66; Nicolás de Damasco, Vida de Augusto 24"},
  "03-16": {"anno": "37 n. e.", "titulo": "Muere Tiberio en Miseno", "texto": "El emperador muere a los 77 años en la villa de Lúculo. Tácito y Suetonio insinúan que lo ayudaron a morir.", "mas": "Tiberio llevaba once años sin pisar Roma, gobernando desde Capri. Tácito cuenta que, cuando ya lo daban por muerto y Calígula recibía las felicitaciones, Tiberio recobró la voz y pidió de comer; el prefecto Macrón lo asfixió con unas mantas. Al conocerse la noticia, el pueblo gritó: «¡Tiberio al Tíber!».", "fuente": "Tácito, Anales 6, 50; Suetonio, Tiberio 73-75"},
  "03-17": {"anno": "45 a. n. e.", "titulo": "Munda: la última batalla de César, en Hispania", "texto": "Cerca de la actual Andalucía, César derrota a los hijos de Pompeyo. Dijo que esa vez había luchado no por la victoria sino por su vida.", "mas": "Fue el día de las Liberalia. La batalla estuvo tan igualada que César bajó del caballo y se puso en primera línea para frenar la huida de los suyos. Murieron unos 30.000 pompeyanos, entre ellos Labieno, el antiguo lugarteniente de César en la Galia. La localización exacta de Munda sigue discutida: Osuna, Montilla y La Lantejuela son las candidatas.", "fuente": "Guerra de Hispania 27-31; Plutarco, César 56; Apiano, Guerras civiles 2, 104"},
  "03-18": {"anno": "37 n. e.", "titulo": "El Senado aclama a Calígula", "texto": "Dos días después de la muerte de Tiberio, el Senado entrega todos los poderes a un joven de 24 años al que el pueblo adoraba.", "mas": "Calígula era hijo de Germánico, el héroe más querido de Roma, y había crecido en los campamentos del Rin, donde los soldados le pusieron el apodo por sus botitas militares, las caligae. Sus primeros meses fueron de alegría general: amnistías, juegos, rebaja de impuestos. Las actas de los hermanos arvales registran esta fecha como el comienzo de su reinado.", "fuente": "Suetonio, Calígula 9 y 13-14; Dion Casio 59, 1-3; Actas de los hermanos arvales"},
  "03-19": {"anno": "59 n. e.", "titulo": "Quinquatrias: Nerón prepara la muerte de su madre", "texto": "En la fiesta de Minerva, que duraba cinco días, Nerón invita a Agripina a Bayas. El barco que la lleva de vuelta está trucado para hundirse.", "mas": "Las Quinquatrias empezaban hoy y eran la fiesta de los artesanos, los médicos y los maestros, protegidos por Minerva. Tácito cuenta que el techo del camarote se desplomó, pero Agripina se salvó nadando hasta la orilla. Comprendió que su hijo quería matarla y fingió no saberlo; esa misma noche llegaron los asesinos. Según Tácito, pidió que la hirieran en el vientre que había llevado a Nerón.", "fuente": "Tácito, Anales 14, 1-10; Ovidio, Fastos 3, 809-848; Suetonio, Nerón 34"},
  "03-20": {"anno": "43 a. n. e.", "titulo": "Nace Ovidio en Sulmona", "texto": "El propio poeta cuenta que nació en las fiestas de Minerva, el primer día de combates, y en el año en que murieron los dos cónsules.", "mas": "Ovidio dejó en las Tristes una pequeña autobiografía, escrita desde el destierro en Tomis, a orillas del mar Negro. Allí explica que nació en el segundo día de las Quinquatrias y que fue el año en que los dos cónsules cayeron en la guerra de Módena. Es el autor de las Metamorfosis, el gran repertorio de mitos del que bebieron Shakespeare, Garcilaso, Bernini y casi todos los artistas europeos.", "fuente": "Ovidio, Tristes 4, 10, 6 y 13-14"},
  "03-21": {"anno": "s. VII a. n. e.", "titulo": "Día Mundial de la Poesía: Safo", "texto": "Platón (o alguien que firmaba como él) la llamó la décima musa. De sus nueve libros de poemas nos han llegado un poema completo y muchos fragmentos.", "mas": "Safo vivió en Mitilene, en la isla de Lesbos, hacia el 600 a. n. e. Los alejandrinos ordenaron su obra en nueve libros por metros; casi todo se perdió en la Edad Media. Lo que conservamos procede de citas de otros autores y de papiros egipcios: en 2004 y en 2014 se publicaron poemas suyos casi completos hallados en papiros. Cada hallazgo es una noticia mundial.", "fuente": "Antología Palatina 9, 506; P. Köln 21351; D. Obbink, ZPE 189 (2014)"},
  "03-22": {"anno": "c. 97 n. e.", "titulo": "Día Mundial del Agua: Frontino y los acueductos", "texto": "El senador Frontino, nombrado curator aquarum, escribió un tratado sobre los acueductos de Roma con cifras de caudal y denuncias de fraudes.", "mas": "Frontino contó nueve acueductos que llevaban a Roma un caudal enorme y presumía de que valían más que las inútiles pirámides o las obras célebres de los griegos. También detalla los trucos de quienes pinchaban las conducciones públicas para regar sus jardines y los fontaneros que se dejaban sobornar. Es uno de los pocos manuales técnicos de un alto funcionario romano que conservamos.", "fuente": "Frontino, Sobre los acueductos de la ciudad de Roma 1-2, 16 y 75-76"},
  "03-23": {"anno": "1900", "titulo": "Evans empieza a excavar en Cnosos", "texto": "Arthur Evans pone a trabajar a sus obreros en la colina de Kefala, en Creta. Saca a la luz el «palacio de Minos» y una civilización a la que llama minoica.", "mas": "El primer día ya aparecieron muros a pocos centímetros de la superficie y, a la semana, tablillas de arcilla escritas en un silabario desconocido. Evans reconstruyó parte del palacio con hormigón y pintura, algo hoy muy discutido. Ese día los romanos celebraban el Tubilustrium, la purificación de las trompetas de guerra.", "fuente": "A. Evans, The Palace of Minos at Knossos, Londres, 1921-1935; Ovidio, Fastos 3, 849-850"},
  "03-24": {"anno": "calendario romano", "titulo": "El día de la sangre", "texto": "En las fiestas de Cibeles, el 24 de marzo era el dies sanguinis: los sacerdotes galos se herían para llorar la muerte de Atis.", "mas": "El culto de la Gran Madre llegó a Roma desde Frigia en el 204 a. n. e. En época imperial se celebraba en marzo un ciclo de fiestas que recordaba la muerte de su joven amante Atis, castrado bajo un pino, y su vuelta a la vida. El Cronógrafo del 354 marca hoy el «día de la sangre» y mañana las Hilaria, la fiesta de la alegría.", "fuente": "Cronógrafo de 354; Macrobio, Saturnales 1, 21, 10; Catulo 63"},
  "03-25": {"anno": "1957", "titulo": "Los tratados de Roma se firman en el Capitolio", "texto": "Seis países firman en el Campidoglio el tratado de la Comunidad Económica Europea, en la sala de los Horacios y Curiacios.", "mas": "La sala del Palacio de los Conservadores está decorada con frescos de la historia legendaria de Roma: el combate de los tres Horacios contra los tres Curiacios, que según Livio decidió la guerra entre Roma y Alba Longa sin que lucharan los ejércitos. Elegir el Capitolio fue un gesto simbólico: Europa firmaba su unión en el corazón de la Roma antigua.", "fuente": "Tratado constitutivo de la CEE, Roma, 25 de marzo de 1957; Livio 1, 24-26"},
  "03-26": {"anno": "1913", "titulo": "Nace Jacqueline de Romilly", "texto": "La helenista francesa dedicó su vida a Tucídides y fue la primera mujer catedrática del Collège de France.", "mas": "Romilly tradujo y estudió a Tucídides durante décadas y escribió ensayos para el gran público sobre por qué Grecia sigue siendo necesaria. Defendió con pasión la enseñanza del griego en Francia. Fue también la segunda mujer elegida miembro de la Academia francesa, después de Marguerite Yourcenar.", "fuente": "J. de Romilly, Thucydide et l'impérialisme athénien, París, 1947; Pourquoi la Grèce?, 1992"},
  "03-27": {"anno": "196 a. n. e.", "titulo": "El decreto de la piedra de Rosetta", "texto": "Unos sacerdotes egipcios reunidos en Menfis aprueban un decreto en honor de Ptolomeo V. Se grabará en tres escrituras, una de ellas griega.", "mas": "La fecha del decreto se puede traducir a nuestro calendario porque el texto da el día en el calendario macedonio y en el egipcio. Se copió en jeroglíficos, en demótico y en griego. Siglos después, la parte griega, que los eruditos podían leer, permitió a Champollion descifrar los jeroglíficos. Hoy es también el Día Mundial del Teatro.", "fuente": "Piedra de Rosetta (British Museum EA 24), OGIS 90"},
  "03-28": {"anno": "193 n. e.", "titulo": "Matan a Pertinax y los pretorianos subastan el Imperio", "texto": "Tras solo 87 días de reinado, los pretorianos asesinan al emperador. Luego venden el trono al mejor postor desde las murallas de su campamento.", "mas": "Pertinax quiso poner orden en las finanzas y en la disciplina militar y lo pagó caro. Dion Casio, que era senador entonces, cuenta la escena siguiente: Sulpiciano dentro del campamento y Didio Juliano fuera, pujando a gritos por el Imperio. Ganó Juliano, con 25.000 sestercios por soldado. Duró dos meses.", "fuente": "Dion Casio 74, 10-11; Historia Augusta, Pértinax 11 y Didio Juliano 2-3"},
  "03-29": {"anno": "1922", "titulo": "Nace Francisco Rodríguez Adrados", "texto": "El gran helenista salmantino dirigió el Diccionario Griego-Español y tradujo a Heródoto, Esquilo y Aristófanes.", "mas": "Adrados estudió en Salamanca y fue catedrático en Madrid durante décadas. Impulsó el Diccionario Griego-Español del CSIC, el proyecto más ambicioso de la filología clásica española, y escribió sobre democracia ateniense, fábula griega y lenguas indoeuropeas. Fue académico de la Lengua y de la Historia y un defensor incansable de las humanidades en la escuela.", "fuente": "F. R. Adrados (dir.), Diccionario Griego-Español, CSIC, desde 1980"},
  "03-30": {"anno": "por estas fechas", "titulo": "Las Grandes Dionisias: nace el teatro", "texto": "Por estas fechas, en el mes de Elafebolión, Atenas celebraba las Dionisias urbanas, el gran concurso de tragedia y comedia.", "mas": "Durante varios días, los ciudadanos llenaban el teatro de Dioniso al pie de la Acrópolis. Tres autores trágicos presentaban cada uno tres tragedias y un drama satírico, y un jurado elegido a suertes decidía el ganador. Allí se estrenaron Edipo rey, Medea o la Orestíada. Antes de las obras se exhibía el tributo de los aliados y desfilaban los huérfanos de guerra criados por la ciudad.", "fuente": "Aristóteles, Constitución de los atenienses 56, 3-5; Isócrates, Sobre la paz 82; Pickard-Cambridge, The Dramatic Festivals of Athens"},
  "03-31": {"anno": "calendario romano", "titulo": "Marzo se despide con la Luna", "texto": "Ovidio cierra el libro de marzo de sus Fastos con un solo dístico: el último día del mes se honraba a la Luna en el Aventino.", "mas": "El templo de Luna en el Aventino era antiguo; Livio cuenta que en el 182 a. n. e. una tormenta arrancó una de sus puertas y la estampó contra el templo de Ceres. Ovidio despacha la fiesta en dos versos: «la Luna rige los meses; el final de este mes se cierra con el culto de la Luna en el Aventino».", "fuente": "Ovidio, Fastos 3, 883-884; Livio 40, 2, 2"},
  "04-01": {"anno": "calendario romano", "titulo": "Veneralia: las mujeres bañan a Venus", "texto": "En las calendas de abril, las mujeres lavaban la estatua de Venus, la adornaban con flores y se bañaban ellas mismas coronadas de mirto.", "mas": "Ovidio cuenta que se honraba a Venus Verticordia, «la que cambia los corazones», y a Fortuna Viril. Las mujeres de toda condición se bañaban en los baños públicos de los hombres y pedían a la diosa que ocultara a los ojos masculinos cualquier defecto de su cuerpo. Bebían además una mezcla de leche, miel y adormidera, como hizo Venus el día de su boda.", "fuente": "Ovidio, Fastos 4, 133-162; Plutarco, Numa 19; Macrobio, Saturnales 1, 12, 15"},
  "04-02": {"anno": "s. VI a. n. e.", "titulo": "Día del Libro Infantil: las fábulas de Esopo", "texto": "Heródoto dice que Esopo fue esclavo en Samos. Las fábulas que se le atribuyen llevan dos mil quinientos años enseñándose a niños.", "mas": "Del Esopo histórico casi no sabemos nada; pronto se convirtió en personaje de una novela popular, la Vida de Esopo, donde es feo, listo y deslenguado. Aristófanes ya lo cita en sus comedias como autor de cuentos de animales. Fedro las tradujo al latín en época de Tiberio, y de ahí pasaron a La Fontaine y a Samaniego.", "fuente": "Heródoto 2, 134; Aristófanes, Avispas 1446-1448; Fedro, Fábulas, prólogo"},
  "04-03": {"anno": "calendario romano", "titulo": "Por qué abril se llama abril", "texto": "Los romanos discutían si aprilis venía de aperire, «abrir», porque en primavera se abre la tierra, o de Afrodita, la Venus griega.", "mas": "Ovidio defiende con orgullo de poeta que abril es el mes de Venus, madre de Eneas y, por tanto, de los romanos. Otros autores, como Varrón, preferían la explicación agrícola: el mes en que todo brota. Los modernos siguen sin ponerse de acuerdo; la hipótesis de una forma etrusca de Afrodita tiene bastantes partidarios.", "fuente": "Ovidio, Fastos 4, 61-90; Varrón, Sobre la lengua latina 6, 33; Macrobio, Saturnales 1, 12, 8-15"},
  "04-04": {"anno": "636 n. e.", "titulo": "Muere Isidoro de Sevilla, el sabio de las etimologías", "texto": "Isidoro deja inacabadas las Etimologías, una enciclopedia de todo el saber antiguo que fue la obra más copiada de la Edad Media.", "mas": "Isidoro, obispo de Sevilla en la Hispania visigoda, reunió en veinte libros lo que sabía de gramática, medicina, derecho, geografía o animales, a menudo explicando cada cosa por el origen de su nombre. Muchas etimologías son fantasiosas, pero gracias a él llegaron a la Edad Media miles de noticias de autores perdidos. Otro 4 de abril, en el 397, había muerto Ambrosio de Milán.", "fuente": "Isidoro, Etimologías; Braulio de Zaragoza, Renotatio librorum Isidori; Paulino, Vida de Ambrosio 47"},
  "04-05": {"anno": "204 a. n. e.", "titulo": "Juegos Megalenses: la diosa que llegó de Asia", "texto": "Del 4 al 10 de abril Roma celebraba a la Gran Madre, cuya piedra negra trajeron desde Frigia en plena guerra contra Aníbal.", "mas": "Los libros sibilinos habían anunciado que Aníbal saldría de Italia si se traía a Roma a la Madre del Ida. La recibió Escipión Nasica, elegido como el mejor de los romanos, y la matrona Claudia Quinta, según la leyenda, sacó sola con su cinturón el barco encallado en el Tíber. En sus juegos se estrenaron comedias de Plauto y de Terencio.", "fuente": "Livio 29, 10-14; Ovidio, Fastos 4, 179-372; didascalias de Terencio, La Andriana"},
  "04-06": {"anno": "1896", "titulo": "Empiezan en Atenas los primeros Juegos Olímpicos modernos", "texto": "Catorce países y unos 240 atletas compiten en el estadio Panatenaico, reconstruido en mármol sobre el antiguo.", "mas": "La fecha se eligió con intención: en el calendario juliano, que Grecia seguía usando, era el 25 de marzo, día de la independencia griega. El estadio se rehízo gracias al mecenas Georgios Averof sobre el que Herodes Ático había construido en el siglo II. Otro 6 de abril, del 46 a. n. e., César había vencido en Tapso a los republicanos y Catón se suicidó poco después en Útica.", "fuente": "Comité Olímpico Internacional, Les Jeux Olympiques 1896, Atenas, 1897; Guerra de África 79-86"},
  "04-07": {"anno": "529 n. e.", "titulo": "Justiniano publica su Código", "texto": "Diez juristas trabajaron catorce meses para ordenar siglos de leyes imperiales. Es la base de nuestro derecho civil.", "mas": "La comisión, dirigida por Triboniano, recogió las constituciones imperiales vigentes desde Adriano y eliminó las contradicciones. Al Código siguieron el Digesto, con extractos de los juristas clásicos, y las Instituciones, un manual para estudiantes. Todo junto, redescubierto en Bolonia en el siglo XI, se llamó Corpus iuris civilis y está en la raíz del derecho de casi toda Europa y de América Latina.", "fuente": "Constitución Summa rei publicae; Código de Justiniano, prefacios"},
  "04-08": {"anno": "1820", "titulo": "Un campesino encuentra la Venus de Milo", "texto": "En la isla de Melos, Yorgos Kentrotas desentierra la estatua mientras saca piedras de unas ruinas. Hoy es una de las obras más visitadas del Louvre.", "mas": "Un oficial de la marina francesa, Olivier Voutier, que andaba por la isla buscando antigüedades, vio el hallazgo y avisó al cónsul. Francia la compró y se la regaló a Luis XVIII. Se cree que representa a Afrodita, aunque algunos proponen Anfitrite, diosa del mar venerada en Melos. Los brazos ya no estaban cuando la encontraron, y nadie sabe qué hacían.", "fuente": "Musée du Louvre, Ma 399; O. Voutier, relato de 1820"},
  "04-09": {"anno": "1626", "titulo": "Muere Francis Bacon, lector de mitos", "texto": "El filósofo de la ciencia experimental escribió también La sabiduría de los antiguos, donde explica los mitos griegos como alegorías.", "mas": "En De sapientia veterum (1609), Bacon interpreta treinta y un mitos: Prometeo es la inteligencia humana que roba el fuego de la naturaleza, Ícaro advierte de los excesos, Pan es el universo. Era una forma de defender que los antiguos habían guardado en relatos un saber filosófico. Murió, cuenta la tradición, de un enfriamiento tras rellenar un pollo de nieve para estudiar la conservación de la carne.", "fuente": "F. Bacon, De sapientia veterum, Londres, 1609; J. Aubrey, Brief Lives"},
  "04-10": {"anno": "1896", "titulo": "Spyridon Louis gana el primer maratón", "texto": "Un aguador griego gana la carrera de Maratón a Atenas. Ningún griego había ganado aún en aquellos Juegos.", "mas": "La prueba la propuso el filólogo francés Michel Bréal, inspirado en la leyenda del mensajero que corrió de Maratón a Atenas para anunciar la victoria y murió al llegar. Heródoto no cuenta esa historia: habla de Filípides, que corrió de Atenas a Esparta para pedir ayuda. La versión del mensajero de Maratón aparece siglos después, en Plutarco y en Luciano.", "fuente": "Heródoto 6, 105-106; Plutarco, Sobre la gloria de los atenienses 3; Luciano, Sobre un error en el saludo 3"},
  "04-11": {"anno": "145 o 146 n. e.", "titulo": "Nace Septimio Severo en Leptis Magna", "texto": "El primer emperador nacido en África hablaba latín con acento púnico. Fundó una dinastía y murió en Britania.", "mas": "Severo venía de una familia de la élite de Leptis Magna, en la actual Libia. La Historia Augusta cuenta que su hermana, de visita en Roma, apenas sabía latín y que él la mandó de vuelta a casa para no avergonzarse. Gobernó apoyándose en el ejército. Según Dion Casio, aconsejó a sus hijos: «Llevaos bien, enriqueced a los soldados y despreciad a todos los demás».", "fuente": "Historia Augusta, Severo 1, 3 y 15, 7; Dion Casio 77, 15, 2"},
  "04-12": {"anno": "calendario romano", "titulo": "Empiezan los juegos de Ceres", "texto": "Del 12 al 19 de abril, las Cerialias honraban a la diosa del trigo. Era la fiesta de la plebe, que tenía su templo junto al Circo Máximo.", "mas": "Ceres, Líber y Líbera compartían un templo en el Aventino que fue el centro religioso de la plebe: allí se guardaban los archivos de los tribunos y de los ediles plebeyos. Ovidio aprovecha la fiesta para contar el rapto de Prosérpina, hija de Ceres, por el dios de los muertos, y cómo la madre recorrió el mundo buscándola.", "fuente": "Ovidio, Fastos 4, 393-620; Livio 3, 55, 7"},
  "04-13": {"anno": "1204", "titulo": "Los cruzados saquean Constantinopla", "texto": "La cuarta cruzada, que debía ir a Tierra Santa, saquea la capital cristiana de Oriente. Los caballos de bronce del Hipódromo acaban en Venecia.", "mas": "Constantinopla guardaba siglos de arte antiguo. Nicetas Coniata, testigo del saqueo, describe cómo los cruzados fundieron estatuas de bronce para hacer monedas, entre ellas un Heracles de Lisipo. Los venecianos se llevaron la cuadriga de bronce dorado, que todavía corona San Marcos (el original está dentro, en el museo). Nadie sabe con certeza cuándo ni dónde se fundió.", "fuente": "Nicetas Coniata, Historia, «De signis»; Geoffroi de Villehardouin, La conquista de Constantinopla"},
  "04-14": {"anno": "43 a. n. e.", "titulo": "Foro de los Galos: muere un ejército de novatos", "texto": "Cerca de Módena, Antonio choca con las legiones del Senado. Uno de los oficiales lo cuenta en una carta a Cicerón escrita al día siguiente.", "mas": "La carta de Servio Sulpicio Galba se ha conservado entre la correspondencia de Cicerón y es uno de los raros partes de batalla escritos por un participante. Galba describe cómo la legión Marcia combatió en un pantano, cómo él mismo se vio rodeado y cómo, por la tarde, Hircio llegó con tropas frescas y derrotó a Antonio. Una semana después, otra batalla en Módena dejaría muertos a los dos cónsules.", "fuente": "Cicerón, Cartas a los familiares 10, 30"},
  "04-15": {"anno": "1863", "titulo": "Aparece la Victoria de Samotracia", "texto": "El cónsul francés Charles Champoiseau encuentra en Samotracia los fragmentos de una Victoria alada posada sobre la proa de un barco.", "mas": "La estatua estaba en el santuario de los Grandes Dioses, en lo alto de una ladera, como si la diosa acabara de posarse sobre una nave. Se cree que celebraba una victoria naval de inicios del siglo II a. n. e. Una mano se encontró en 1950. Ese mismo día, los romanos celebraban las Fordicidia, en las que se sacrificaban vacas preñadas a la Tierra.", "fuente": "Musée du Louvre, Ma 2369; Ovidio, Fastos 4, 629-672"},
  "04-16": {"anno": "65 n. e.", "titulo": "Una conjura contra Nerón en los juegos de Ceres", "texto": "Durante las Cerialias de ese año, un grupo de senadores y oficiales planeaba matar a Nerón en el circo. Un liberto los delató.", "mas": "La llamada conjura de Pisón reunió a senadores, caballeros y oficiales pretorianos. Tácito cuenta que el liberto Mílico, tras ver a su amo afilar un puñal la víspera, fue a denunciarlo. La represión fue enorme: entre las víctimas estuvieron Séneca, su sobrino el poeta Lucano y probablemente Petronio. Nerón dedicó el puñal en el Capitolio a Júpiter Vindicador.", "fuente": "Tácito, Anales 15, 48-74; Suetonio, Nerón 36"},
  "04-17": {"anno": "calendario romano", "titulo": "Zorros con antorchas en el circo", "texto": "El último día de las Cerialias se soltaban en el Circo Máximo zorros con antorchas atadas a la cola. Ni Ovidio sabía bien por qué.", "mas": "Ovidio cuenta una historia que le contó un viejo de su tierra: un niño cazó un zorro que robaba gallinas, lo envolvió en paja y le prendió fuego; el animal escapó y quemó las mieses. Desde entonces, dice, se castigaba a los zorros en la fiesta de Ceres. Los estudiosos piensan más bien en un rito antiguo para proteger el grano del tizón.", "fuente": "Ovidio, Fastos 4, 681-712"},
  "04-18": {"anno": "s. II a. n. e.", "titulo": "Día de los Monumentos: las siete maravillas", "texto": "La lista de las siete maravillas es un invento helenístico, un catálogo de lo que un viajero griego no debía perderse.", "mas": "Nuestra lista procede sobre todo de un epigrama de Antípatro de Sidón y de un tratado atribuido a Filón de Bizancio. En las listas antiguas hay variaciones: a veces aparecen las murallas de Babilonia en lugar del faro de Alejandría. La palabra griega no era «maravillas» sino theámata, «cosas dignas de verse». Solo queda en pie la pirámide de Guiza, la más antigua.", "fuente": "Antología Palatina 9, 58 (Antípatro de Sidón); Pseudo-Filón de Bizancio, Sobre las siete maravillas"},
  "04-19": {"anno": "1824", "titulo": "Muere Byron en Mesolongi", "texto": "El poeta inglés muere de fiebres en Grecia, adonde había ido a apoyar la guerra de independencia contra el Imperio otomano.", "mas": "Byron había puesto dinero propio para armar a los griegos y llegó a Mesolongi en enero de 1824. No llegó a combatir. Su muerte conmovió a Europa y dio un gran impulso a la causa griega. En Grecia muchas calles llevan su nombre. Años antes había grabado su firma en una columna del templo de Poseidón en Sunión, donde todavía puede verse.", "fuente": "L. A. Marchand, Byron: A Biography, Nueva York, 1957"},
  "04-20": {"anno": "1808", "titulo": "Nace Napoleón III, biógrafo de César", "texto": "El emperador francés escribió una Historia de Julio César y mandó excavar Alesia, donde César venció a Vercingétorix.", "mas": "Napoleón III publicó los dos primeros volúmenes de su Histoire de Jules César en 1865-1866, con la ayuda de un equipo de eruditos. Para documentarla, financió excavaciones en Alise-Sainte-Reine, en Borgoña, que sacaron a la luz los fosos y fortificaciones descritos por César. Al mismo tiempo, mandó levantar allí una enorme estatua de Vercingétorix, con rasgos parecidos a los suyos.", "fuente": "Napoléon III, Histoire de Jules César, París, 1865-1866; César, Guerra de las Galias 7, 68-90"},
  "04-21": {"anno": "753 a. n. e.", "titulo": "Parilia: el cumpleaños de Roma", "texto": "En la fiesta de Pales, los romanos celebraban la fundación de la ciudad por Rómulo. El año 753 es el cálculo de Varrón.", "mas": "La Parilia era una fiesta de pastores: se purificaba el ganado y se saltaba tres veces sobre hogueras de paja. Ovidio cuenta que ese día Rómulo trazó el surco de las murallas y que Remo, burlándose, lo saltó y murió por ello. En el 248 n. e., el emperador Filipo el Árabe celebró con grandes juegos el milenario de la ciudad.", "fuente": "Ovidio, Fastos 4, 721-862; Plutarco, Rómulo 12; Aurelio Víctor, Sobre los Césares 28"},
  "04-22": {"anno": "1904", "titulo": "Nace María Zambrano", "texto": "La filósofa de Vélez-Málaga pensó la tragedia griega, a Antígona y el nacimiento de los dioses en El hombre y lo divino.", "mas": "Zambrano fue discípula de Ortega y Gasset y vivió más de cuarenta años en el exilio tras la guerra civil. En La tumba de Antígona (1967) imagina a la heroína de Sófocles viva dentro de su tumba, hablando con los suyos: una Antígona que no muere y que piensa. Fue la primera mujer que recibió el Premio Cervantes, en 1988.", "fuente": "M. Zambrano, El hombre y lo divino, 1955; La tumba de Antígona, 1967"},
  "04-23": {"anno": "calendario romano", "titulo": "Vinalia y Día del Libro", "texto": "Hoy los romanos ofrecían a Júpiter el primer vino del año anterior, y las prostitutas honraban a Venus Ericina. Hoy celebramos también el libro.", "mas": "Ovidio cuenta que la fiesta recordaba una promesa: en la guerra contra Mecencio, los latinos prometieron a Júpiter el vino de la cosecha si les daba la victoria. Ese día también era la fiesta de Venus del monte Érice, en Sicilia, cuyo templo junto a la puerta Colina frecuentaban las cortesanas. El Día del Libro recuerda a Cervantes y a Shakespeare, grandes lectores de Ovidio.", "fuente": "Ovidio, Fastos 4, 863-900; Varrón, Sobre la lengua latina 6, 16"},
  "04-24": {"anno": "387 n. e.", "titulo": "Ambrosio bautiza a Agustín en Milán", "texto": "En la noche de Pascua, el profesor de retórica Agustín de Tagaste recibe el bautismo junto a su hijo Adeodato.", "mas": "Agustín era un brillante profesor de retórica que había leído a Cicerón, a los platónicos y a los maniqueos antes de convertirse. En las Confesiones cuenta el momento decisivo, en un jardín de Milán, al oír a un niño cantar «toma y lee». El bautismo tuvo lugar en la vigilia pascual de ese año, la noche del 24 al 25 de abril.", "fuente": "Agustín, Confesiones 8, 12 y 9, 6; Paulino, Vida de Ambrosio"},
  "04-25": {"anno": "calendario romano", "titulo": "Robigalia: contra el tizón del trigo", "texto": "El flamen de Quirino sacrificaba un perro rojizo y una oveja a Robigo, el espíritu del moho que roía las espigas.", "mas": "Ovidio cuenta que se cruzó con la procesión volviendo de Nomento y que el sacerdote le explicó el rito: el color rojizo del perro imitaba el color del hongo que atacaba el trigo justo en esas semanas. La oración que el poeta pone en boca del flamen pide al tizón que ataque a las armas y no a los campos.", "fuente": "Ovidio, Fastos 4, 901-942; Columela 10, 342-343"},
  "04-26": {"anno": "121 n. e.", "titulo": "Nace Marco Aurelio", "texto": "El emperador filósofo, que escribió en griego unas notas para sí mismo que hoy llamamos Meditaciones.", "mas": "Marco Aurelio pasó buena parte de su reinado en la frontera del Danubio, y allí escribió muchas de sus notas, que empiezan con una lista de lo que aprendió de cada persona de su vida. Son ejercicios estoicos: recordarse que todo pasa, que el daño está en el juicio sobre las cosas, que hay que trabajar para los demás. Nunca pensó publicarlas.", "fuente": "Historia Augusta, Marco Antonino 1, 5; Marco Aurelio, Meditaciones 1"},
  "04-27": {"anno": "1737", "titulo": "Nace Edward Gibbon", "texto": "El historiador de la decadencia y caída del Imperio romano nació en Putney, según el viejo calendario inglés (el 8 de mayo en el nuestro).", "mas": "Inglaterra no adoptó el calendario gregoriano hasta 1752, así que Gibbon nació el 27 de abril del calendario juliano. Su gran obra, en seis volúmenes, va de los Antoninos a la caída de Constantinopla en 1453. Gibbon escribe con una ironía elegantísima y atribuye la caída en parte al cristianismo y a la barbarie, una tesis que hoy se discute mucho.", "fuente": "E. Gibbon, Memoirs of My Life; The History of the Decline and Fall of the Roman Empire, 1776-1789"},
  "04-28": {"anno": "calendario romano", "titulo": "Floralia, la fiesta más alegre", "texto": "Del 28 de abril al 3 de mayo, Roma celebraba a Flora con teatro, flores y espectáculos que los moralistas consideraban escandalosos.", "mas": "Las actrices de los mimos se desnudaban a petición del público. Valerio Máximo cuenta que Catón el Joven, al ver que su presencia cohibía a los espectadores, se marchó para no estropear la fiesta. Se soltaban liebres y cabras, animales de fertilidad, en lugar de fieras. Ese día, del 32 n. e., nació el emperador Otón.", "fuente": "Ovidio, Fastos 5, 183-378; Valerio Máximo 2, 10, 8; Suetonio, Otón 2"},
  "04-29": {"anno": "1863", "titulo": "Cavafis nace y muere el mismo día", "texto": "El poeta griego de Alejandría nació un 29 de abril de 1863 y murió un 29 de abril de 1933. Escribió «Ítaca» y «Esperando a los bárbaros».", "mas": "Cavafis trabajó treinta años como funcionario en Alejandría y publicó sus poemas en hojas sueltas para amigos. Muchos están ambientados en el mundo helenístico y en la Antigüedad tardía: reyes menores, poetas olvidados, ciudades en decadencia. En «Ítaca» aconseja desear que el camino sea largo, porque el viaje vale más que la llegada. Hoy es además el Día Internacional de la Danza.", "fuente": "C. P. Cavafis, Poemas; R. Liddell, Cavafy: A Biography, 1974"},
  "04-30": {"anno": "59 n. e.", "titulo": "Un eclipse sobre el asesinato de Agripina", "texto": "Plinio el Viejo anota un eclipse de sol visible en Campania la víspera de las calendas de mayo, poco después de que Nerón mandara matar a su madre.", "mas": "Plinio lo cuenta para demostrar cómo los eclipses se ven a distintas horas según el lugar: en Campania se vio entre la séptima y la octava hora, y en Armenia el general Corbulón lo observó entre la décima y la undécima. Tácito dice que los romanos interpretaron los prodigios de aquellos meses como aviso del matricidio. Los astrónomos confirman el eclipse del 30 de abril del 59.", "fuente": "Plinio el Viejo, Historia natural 2, 180; Tácito, Anales 14, 12"},
  "05-01": {"anno": "305 n. e.", "titulo": "Diocleciano se jubila", "texto": "En las calendas de mayo, ante sus tropas en Nicomedia, Diocleciano abdica. Es el único emperador romano que dejó el poder por voluntad propia.", "mas": "Lactancio, que lo odiaba, describe la ceremonia: el viejo emperador llorando, la púrpura pasada a Galerio y la sorpresa general por el nombre del nuevo César. Diocleciano se retiró a su palacio de Spalatum (Split, en Croacia). Años después, cuando le pidieron que volviera al poder, contestó, según el Epítome de los Césares, que si vieran las coles que cultivaba con sus manos no le harían esa propuesta.", "fuente": "Lactancio, Sobre la muerte de los perseguidores 19; Epítome de los Césares 39, 6"},
  "05-02": {"anno": "calendario romano", "titulo": "Por qué mayo se llama mayo", "texto": "Ovidio ofrece tres explicaciones: por Maya, madre de Mercurio; por la diosa Maiestas; o por los maiores, los ancianos, igual que junio por los iuniores.", "mas": "Ovidio deja que las propias Musas discutan el origen del nombre, y cada una defiende una versión distinta. Él no se decide. La explicación de los ancianos y los jóvenes es la que daban algunos anticuarios: Rómulo habría dedicado un mes a cada grupo de edad. Los lingüistas modernos se inclinan por la diosa Maia, relacionada con el crecimiento.", "fuente": "Ovidio, Fastos 5, 1-110; Macrobio, Saturnales 1, 12, 16-20"},
  "05-03": {"anno": "1469", "titulo": "Nace Maquiavelo, lector de Livio", "texto": "Además de El príncipe, Maquiavelo escribió unos Discursos sobre la primera década de Tito Livio, una reflexión sobre la república romana.", "mas": "En los Discursos, Maquiavelo sostiene una idea sorprendente: los conflictos entre patricios y plebeyos no debilitaron a Roma, sino que la hicieron libre y fuerte, porque obligaron a crear instituciones como los tribunos. Cuenta en una carta famosa que, por la noche, se quitaba la ropa del día, se vestía con ropas de corte y entraba a conversar con los antiguos, que le respondían con humanidad.", "fuente": "N. Machiavelli, Discorsi sopra la prima deca di Tito Livio 1, 4; carta a Francesco Vettori, 10 de diciembre de 1513"},
  "05-04": {"anno": "calendario romano", "titulo": "En mayo, mejor no casarse", "texto": "Ovidio recoge un dicho del pueblo: las que se casan en mayo, mala boda hacen. El mes de los lémures no era buen momento.", "mas": "El verso de Ovidio es casi un refrán: mense malas Maio nubere vulgus ait. Plutarco dedica una de sus Cuestiones romanas a explicarlo y propone varias razones: en mayo se hacían ritos por los muertos, y además era el mes en que se arrojaban los Argeos al Tíber. Los romanos preferían junio, sobre todo la segunda quincena.", "fuente": "Ovidio, Fastos 5, 487-490; Plutarco, Cuestiones romanas 86"},
  "05-05": {"anno": "1818", "titulo": "Nace Marx, que se doctoró con Demócrito y Epicuro", "texto": "Antes de escribir El capital, Karl Marx presentó en 1841 una tesis doctoral sobre la física de Demócrito y Epicuro.", "mas": "Marx comparaba los dos atomismos griegos y defendía a Epicuro, que introducía una pequeña desviación en la caída de los átomos, el clinamen, para dejar sitio a la libertad. Admiraba también a Prometeo, a quien llama en el prólogo «el más noble santo y mártir del calendario filosófico». La tesis se presentó en la Universidad de Jena.", "fuente": "K. Marx, Differenz der demokritischen und epikureischen Naturphilosophie, 1841; Lucrecio 2, 216-293"},
  "05-06": {"anno": "1856", "titulo": "Nace Freud, coleccionista de dioses", "texto": "Freud bautizó con un nombre griego su teoría más famosa, el complejo de Edipo, y llenó su despacho de estatuillas antiguas.", "mas": "En su consulta de Viena, y luego en Londres, Freud tenía más de dos mil antigüedades: egipcias, griegas, romanas y etruscas. Muchas estaban sobre su escritorio, mirándolo mientras escribía. Comparaba el psicoanálisis con la arqueología: excavar capas para llegar a lo enterrado. Leyó a Sófocles en griego en el instituto.", "fuente": "S. Freud, La interpretación de los sueños, 1900, cap. 5; Freud Museum London"},
  "05-07": {"anno": "1824", "titulo": "La Novena de Beethoven canta al Elíseo", "texto": "En el estreno vienés de la Novena sinfonía, el coro canta la Oda a la alegría de Schiller, que llama a la alegría «hija del Elíseo».", "mas": "El Elíseo era, para los griegos, la llanura donde vivían felices algunos héroes después de la muerte, descrita ya en la Odisea. Schiller, gran admirador de Grecia, llena su oda de imágenes antiguas. Beethoven, completamente sordo, tuvo que ser girado hacia el público para ver los aplausos. Hoy la melodía es el himno de la Unión Europea.", "fuente": "F. Schiller, An die Freude, 1785; Homero, Odisea 4, 561-569"},
  "05-08": {"anno": "1877", "titulo": "Aparece el Hermes de Praxíteles en Olimpia", "texto": "Los arqueólogos alemanes encuentran en el templo de Hera una estatua de Hermes con Dioniso niño. Pausanias la había visto allí en el siglo II.", "mas": "Pausanias escribió que en el Hereo de Olimpia había un Hermes de mármol con Dioniso niño, obra de Praxíteles. La estatua apareció caída delante de su pedestal, sepultada por un terremoto de finales del siglo III. Durante mucho tiempo se consideró el único original conservado de un gran escultor griego; hoy algunos lo creen una copia muy buena.", "fuente": "Pausanias 5, 17, 3; E. Curtius y F. Adler, Olympia, Berlín, 1890-1897"},
  "05-09": {"anno": "mito", "titulo": "Día de Europa: la princesa que dio nombre a un continente", "texto": "Zeus, convertido en toro blanco, raptó a Europa, princesa fenicia, y la llevó a Creta. Heródoto ya se preguntaba por qué el continente se llama así.", "mas": "Heródoto confiesa que no sabe quién puso nombre a Europa ni por qué, ya que la Europa del mito era asiática y nunca pisó lo que los griegos llamaban Europa. Hoy el rapto de Europa aparece en la moneda griega de dos euros. Ese día, en Roma, empezaba además la Lemuria, la fiesta para apaciguar a los fantasmas.", "fuente": "Heródoto 4, 45; Ovidio, Metamorfosis 2, 833-875; Mosco, Europa"},
  "05-10": {"anno": "calendario romano", "titulo": "El miedo romano a los números pares", "texto": "Hoy era un día par entre los tres días de la Lemuria (9, 11 y 13). Los romanos consideraban de mal agüero los números pares.", "mas": "Macrobio explica que Numa dio a casi todos los meses un número impar de días por esa superstición, y que solo febrero, el mes de los muertos, quedó con un número par. Por eso los ritos de la Lemuria caían en días impares y el padre de familia arrojaba habas negras de nueve en nueve. Es también la razón por la que el calendario anterior a César tenía 355 días.", "fuente": "Macrobio, Saturnales 1, 13, 5-7; Censorino, Sobre el día natal 20, 4; Ovidio, Fastos 5, 429-444"},
  "05-11": {"anno": "330 n. e.", "titulo": "Constantino inaugura Constantinopla", "texto": "La antigua Bizancio se convierte en la Nueva Roma. Será capital del Imperio durante más de mil años.", "mas": "Constantino eligió el lugar por su posición entre Europa y Asia, entre el Danubio y la frontera persa. Llenó la ciudad de estatuas traídas de todo el Imperio, entre ellas la columna de las serpientes de Delfos, que todavía está en el antiguo Hipódromo de Estambul. La fiesta de la fundación se celebró cada 11 de mayo hasta el final del Imperio bizantino.", "fuente": "Cronicón Pascual, año 330; Eusebio, Vida de Constantino 3, 48-54; Heródoto 9, 81"},
  "05-12": {"anno": "113 n. e.", "titulo": "Se inaugura la columna de Trajano", "texto": "La columna de 30 metros, con un friso de 200 metros que narra las guerras dacias, se dedica en el foro de Trajano.", "mas": "El friso en espiral muestra unas 2.500 figuras: soldados construyendo campamentos, cruzando el Danubio, combatiendo a los dacios. La inscripción de la base dice que la altura de la columna indica cuánto se excavó la colina para hacer el foro. En la base se depositaron las cenizas de Trajano. Las letras de esa inscripción han servido de modelo a muchos tipógrafos.", "fuente": "CIL VI 960; Fastos de Ostia, año 113; Dion Casio 68, 16, 3"},
  "05-13": {"anno": "calendario romano", "titulo": "Lemuria: echar habas a los fantasmas", "texto": "A medianoche, el padre de familia se levantaba descalzo, arrojaba habas negras por encima del hombro y repetía nueve veces: «con estas habas me rescato a mí y a los míos».", "mas": "Ovidio describe el rito con todo detalle: lavarse las manos, hacer sonar un objeto de bronce y pedir a los espíritus de los antepasados que salgan de casa. Los lémures eran los muertos inquietos que volvían. El nombre de los lémures de Madagascar viene de aquí: Linneo se lo puso por sus ojos grandes y sus costumbres nocturnas.", "fuente": "Ovidio, Fastos 5, 419-492"},
  "05-14": {"anno": "calendario romano", "titulo": "Los Argeos al agua", "texto": "A mediados de mayo, las vestales arrojaban al Tíber desde el puente Sublicio veintisiete muñecos de junco con forma humana.", "mas": "Ni los romanos sabían bien qué significaba. Ovidio y Dionisio de Halicarnaso recogen la idea de que sustituían a antiguos sacrificios humanos, pero la consideran indigna. Otros pensaban en los compañeros griegos de Hércules. La fecha exacta tampoco es segura: unos autores la ponen el 14 y otros en los idus, el 15.", "fuente": "Ovidio, Fastos 5, 621-662; Dionisio de Halicarnaso 1, 38; Varrón, Sobre la lengua latina 7, 44"},
  "05-15": {"anno": "495 a. n. e.", "titulo": "Mercuralia: los comerciantes lavan sus mentiras", "texto": "En los idus de mayo se celebraba el templo de Mercurio, dios del comercio. Los mercaderes se rociaban con agua de una fuente para limpiar los engaños del año.", "mas": "Ovidio pone en boca de un comerciante la oración: «Lava los perjurios de otros tiempos, lava las palabras falsas del pasado», y pide al dios ganancias para el futuro y el placer de engañar a los compradores. Mercurio, dios de los mercaderes y de los ladrones, sonreía desde el cielo. El templo, junto al Circo Máximo, se había dedicado en el 495 a. n. e.", "fuente": "Ovidio, Fastos 5, 663-692; Livio 2, 21, 7 y 2, 27, 5"},
  "05-16": {"anno": "218 n. e.", "titulo": "Un sacerdote de 14 años, emperador", "texto": "En Emesa, Siria, las legiones proclaman emperador a Heliogábalo, sumo sacerdote del dios Sol local. Su abuela lo había preparado todo.", "mas": "Julia Mesa, cuñada de Septimio Severo, hizo correr la voz de que su nieto era hijo de Caracalla y pagó a los soldados. El joven llegó a Roma con la piedra negra de su dios y quiso imponerlo por encima de Júpiter. Las fuentes antiguas, muy hostiles, le atribuyen todas las extravagancias imaginables. Lo mataron con dieciocho años.", "fuente": "Dion Casio 79, 31; Herodiano 5, 3-8; Historia Augusta, Heliogábalo"},
  "05-17": {"anno": "1902", "titulo": "Alguien se fija en el mecanismo de Anticitera", "texto": "El arqueólogo Valerios Stais ve una rueda dentada en un bloque de bronce corroído recuperado de un naufragio. Es el primer ordenador analógico conocido.", "mas": "Unos pescadores de esponjas habían encontrado en 1900 un barco hundido del siglo I a. n. e. lleno de estatuas. Entre los restos, el bronce del mecanismo pasó desapercibido hasta que se partió. Las tomografías han mostrado más de treinta engranajes que calculaban las posiciones del sol y la luna, los eclipses y hasta las fechas de los Juegos Olímpicos.", "fuente": "D. de Solla Price, Gears from the Greeks, 1974; T. Freeth y otros, Nature 444 (2006)"},
  "05-18": {"anno": "1471", "titulo": "Día de los Museos: el museo público más antiguo", "texto": "En 1471 el papa Sixto IV regaló al pueblo de Roma unos bronces antiguos, entre ellos la Loba. Así nacieron los Museos Capitolinos.", "mas": "La donación incluía la Loba Capitolina, el Espinario y la cabeza colosal de Constantino, y se instalaron en el Capitolio, la sede del gobierno municipal. Es considerado el museo público más antiguo del mundo. Hoy sabemos, por datación de radiocarbono, que la Loba es probablemente medieval, aunque esto sigue discutiéndose; los gemelos se añadieron en el Renacimiento.", "fuente": "Inscripción de la donación de Sixto IV, 1471; A. M. Carruba, La Lupa Capitolina, 2006"},
  "05-19": {"anno": "1912", "titulo": "Muere Menéndez Pelayo, historiador de Horacio en España", "texto": "El gran erudito santanderino estudió cómo se tradujeron e imitaron los clásicos en España en su Bibliografía hispano-latina clásica.", "mas": "Marcelino Menéndez Pelayo ganó la cátedra de Literatura de Madrid con 21 años. Entre sus muchas obras destaca Horacio en España, donde rastrea traducciones e imitaciones del poeta romano desde la Edad Media. Su biblioteca, con más de 40.000 volúmenes, sigue abierta en Santander.", "fuente": "M. Menéndez Pelayo, Horacio en España, 1877; Bibliografía hispano-latina clásica"},
  "05-20": {"anno": "325 n. e.", "titulo": "Se abre el concilio de Nicea", "texto": "Constantino reúne a unos trescientos obispos en Nicea para zanjar la disputa sobre la naturaleza de Cristo. Es el primer concilio de todo el Imperio.", "mas": "La fecha del 20 de mayo es la tradicional; algunos autores prefieren junio. Constantino presidió la sesión inaugural en el palacio imperial. El concilio condenó a Arrio, fijó el credo que lleva su nombre y estableció cómo calcular la fecha de la Pascua. Es un buen ejemplo de cómo un emperador romano usaba los métodos de gobierno de siempre, reunir a las élites y forzar un acuerdo, para un problema nuevo.", "fuente": "Eusebio, Vida de Constantino 3, 6-21; Teodoreto, Historia eclesiástica 1, 7"},
  "05-21": {"anno": "1688", "titulo": "Nace Alexander Pope, traductor de Homero", "texto": "El poeta inglés se hizo rico traduciendo la Ilíada y la Odisea en pareados rimados. Un sabio de su época le dijo que era un bonito poema, pero que no era Homero.", "mas": "Pope publicó su Ilíada entre 1715 y 1720 por suscripción y ganó lo suficiente para vivir de la escritura, algo raro entonces. El filólogo Richard Bentley, según la anécdota, le soltó: «Un bonito poema, señor Pope, pero no debe llamarlo Homero». Fue durante un siglo la versión inglesa más leída.", "fuente": "A. Pope, The Iliad of Homer, 1715-1720; S. Johnson, Lives of the Poets, «Pope»"},
  "05-22": {"anno": "337 n. e.", "titulo": "Muere Constantino, bautizado en su lecho", "texto": "El emperador muere cerca de Nicomedia, en Pentecostés, recién bautizado. Será enterrado en Constantinopla rodeado de doce cenotafios de los apóstoles.", "mas": "Constantino había apoyado al cristianismo durante veinticinco años, pero retrasó el bautismo hasta el final, una costumbre frecuente entonces para morir limpio de pecados. Lo bautizó el obispo Eusebio de Nicomedia. Su tumba en la iglesia de los Santos Apóstoles lo presentaba como un decimotercer apóstol.", "fuente": "Eusebio, Vida de Constantino 4, 60-64"},
  "05-23": {"anno": "calendario romano", "titulo": "Rosalia: rosas para los muertos", "texto": "Por estas semanas, en las fechas que cada lugar elegía, los romanos llevaban rosas a las tumbas. Muchas inscripciones dejan dinero para ello.", "mas": "La Rosalia no era una fiesta oficial de la ciudad, sino una costumbre funeraria muy extendida entre mayo y julio. En numerosos epitafios el difunto deja una suma a un colegio o a sus libertos para que cada año, en la Rosalia, adornen su tumba con rosas y celebren un banquete. Las legiones también la celebraban con sus estandartes, como muestra el calendario de Dura Europos.", "fuente": "Feriale Duranum; CIL V 2072 y otras inscripciones funerarias"},
  "05-24": {"anno": "1543", "titulo": "Muere Copérnico, que leyó a los griegos", "texto": "Copérnico recibió el primer ejemplar de su libro sobre el movimiento de la Tierra en su lecho de muerte. La idea ya la habían defendido algunos griegos.", "mas": "En el prólogo de De revolutionibus, dedicado al papa, Copérnico cita a Cicerón y a Plutarco para mostrar que Filolao, Heráclides o Ecfanto ya habían hecho moverse a la Tierra. Arquímedes, en El arenario, cuenta que Aristarco de Samos puso el Sol en el centro del universo dieciocho siglos antes. Copérnico conocía el dato, aunque tachó su nombre en el manuscrito.", "fuente": "N. Copernicus, De revolutionibus orbium coelestium, Núremberg, 1543; Arquímedes, El arenario 1, 4-5"},
  "05-25": {"anno": "s. II a. n. e.", "titulo": "Día de África: Terencio el Africano", "texto": "Publio Terencio Afro llegó a Roma como esclavo desde África y se convirtió en uno de los grandes autores de comedia latina.", "mas": "Según Suetonio, Terencio nació en Cartago y fue esclavo del senador Terencio Lucano, que lo educó y lo liberó. Sus seis comedias, adaptadas de Menandro, son más finas que las de Plauto. De él es la frase «Soy hombre y nada humano me es ajeno». África dio a la literatura latina otros grandes nombres: Apuleyo, Tertuliano o Agustín.", "fuente": "Suetonio, Vida de Terencio 1-5; Terencio, El atormentador de sí mismo 77"},
  "05-26": {"anno": "17 n. e.", "titulo": "El triunfo de Germánico", "texto": "Tácito da la fecha exacta: siete días antes de las calendas de junio, Germánico celebró su triunfo sobre los germanos.", "mas": "En el desfile iban cautivos, despojos, imágenes de montañas y ríos y Tusnelda, la mujer de Arminio, con su hijo pequeño. Germánico, en el carro, llevaba a sus cinco hijos, y la multitud se emocionó. Tácito añade una nota amarga: los romanos recordaron que los favoritos del pueblo solían morir jóvenes. Dos años después, Germánico moría en Siria.", "fuente": "Tácito, Anales 2, 41; Estrabón 7, 1, 4"},
  "05-27": {"anno": "por estas fechas", "titulo": "Las Targelias: el chivo expiatorio de Atenas", "texto": "Por estas fechas, en el mes de Targelión, Atenas expulsaba a dos personas como pharmakoi, para que se llevaran con ellas los males de la ciudad.", "mas": "Las Targelias honraban a Apolo con las primicias de la cosecha. El primer día, dos hombres, normalmente pobres o marginados, eran paseados y expulsados de la ciudad como «remedio» (pharmakós, de la misma familia que «fármaco»). Las fuentes discuten si en época antigua se les llegaba a matar. Es uno de los rituales que más han interesado a los antropólogos.", "fuente": "Harpocración, s. v. pharmakos; Hiponacte, fragmentos 5-10 West; J. Bremmer, HSCP 87 (1983)"},
  "05-28": {"anno": "585 a. n. e.", "titulo": "Un eclipse detiene una batalla", "texto": "Lidios y medos luchaban cuando el día se hizo noche, y firmaron la paz. Heródoto dice que Tales de Mileto lo había anunciado.", "mas": "Llevaban cinco años de guerra. Al ver el eclipse, los dos ejércitos dejaron de combatir y aceptaron la mediación de los reyes de Cilicia y de Babilonia; la paz se selló con una boda. Que Tales pudiera predecir el eclipse es discutido, pero Heródoto lo cuenta así. La fecha la da el cálculo astronómico.", "fuente": "Heródoto 1, 74"},
  "05-29": {"anno": "1453", "titulo": "Cae Constantinopla", "texto": "Las tropas de Mehmet II entran en la ciudad. Muere Constantino XI, el último emperador romano de Oriente.", "mas": "Los bizantinos se llamaban a sí mismos romanos (rhomaioi) y su Estado era, sin interrupción, el Imperio romano. Con la caída de la ciudad muchos sabios griegos se instalaron en Italia, donde ya enseñaban griego desde décadas antes, y ayudaron a difundir los textos antiguos en Occidente. El último emperador se llamaba como el fundador de la ciudad.", "fuente": "Jorge Esfrantzes, Crónica; Miguel Ducas, Historia turco-bizantina 39-40"},
  "05-30": {"anno": "1927", "titulo": "Stravinsky pone Edipo en latín", "texto": "En París se estrena Oedipus rex, ópera-oratorio de Stravinsky con texto de Cocteau traducido al latín. Quería una lengua «de piedra».", "mas": "Stravinsky explicó que eligió el latín porque era una lengua muerta, monumental, que no distraía con su significado cotidiano. El texto de Cocteau, basado en Sófocles, lo tradujo al latín el sacerdote Jean Daniélou. Un narrador explica la acción al público en la lengua del país, mientras los cantantes, casi inmóviles, cantan como estatuas.", "fuente": "I. Stravinsky, Oedipus rex, 1927; I. Stravinsky y R. Craft, Dialogues and a Diary"},
  "05-31": {"anno": "1873", "titulo": "Schliemann anuncia el «tesoro de Príamo»", "texto": "Según su diario, Schliemann encontró en Troya un gran depósito de oro y lo sacó a escondidas con ayuda de su esposa Sofía.", "mas": "La historia de que Sofía lo llevó envuelto en su chal es, casi con seguridad, un adorno: ella estaba en Atenas en esas fechas. El tesoro es real, pero mucho más antiguo que la guerra de Troya, de hacia el 2400 a. n. e. Pasó a Berlín, desapareció en 1945 y reapareció en Moscú en 1993, donde sigue.", "fuente": "H. Schliemann, Trojanische Alterthümer, 1874; D. Traill, Schliemann of Troy, 1995"},
  "06-01": {"anno": "344 a. n. e.", "titulo": "Juno Moneta, la diosa que dio nombre al dinero", "texto": "En las calendas de junio se dedicó el templo de Juno Moneta en el Capitolio. Junto a él se acuñaba la moneda, y de ahí viene la palabra.", "mas": "Moneta significaba probablemente «la que advierte» (de monere). Cicerón cuenta que, durante un terremoto, se oyó una voz salida del templo aconsejando un sacrificio. La ceca de Roma estaba junto al santuario, y por eso las piezas acuñadas se llamaron monetae. De ahí vienen «moneda» y el inglés money.", "fuente": "Livio 7, 28, 4-6; Cicerón, Sobre la adivinación 1, 101; Ovidio, Fastos 6, 183-190"},
  "06-02": {"anno": "455 n. e.", "titulo": "Los vándalos entran en Roma", "texto": "Genserico, rey de los vándalos de África, desembarca y saquea Roma durante catorce días. El papa León logra que no haya matanzas ni incendios.", "mas": "Fue un saqueo metódico: los vándalos cargaron sus barcos con el tesoro imperial, el bronce dorado del templo de Júpiter y miles de cautivos, entre ellos la emperatriz Eudoxia y sus hijas. Que «vandalismo» signifique destrucción gratuita es una invención del siglo XVIII: el abate Grégoire acuñó la palabra en 1794 para condenar los destrozos de la Revolución francesa.", "fuente": "Próspero de Aquitania, Crónica, año 455; Procopio, Guerra vándala 1, 5; H. Grégoire, Rapport sur le vandalisme, 1794"},
  "06-03": {"anno": "17 a. n. e.", "titulo": "Horacio estrena el Canto secular", "texto": "En los Juegos Seculares de Augusto, un coro de 27 chicos y 27 chicas canta en el Palatino y en el Capitolio un himno compuesto por Horacio.", "mas": "Los Juegos Seculares celebraban el paso de un saeculum, un ciclo de unos cien años. Se ha conservado la inscripción oficial con el programa de los juegos y una línea que dice: «Compuso el canto Quinto Horacio Flaco». Es raro tener un documento que confirme el día exacto en que se interpretó un poema antiguo.", "fuente": "Horacio, Canto secular; Actas de los Juegos Seculares (CIL VI 32323)"},
  "06-04": {"anno": "calendario romano", "titulo": "Por qué junio se llama junio", "texto": "Juno reclama el mes en los Fastos de Ovidio, pero la Juventud se lo disputa: iunius vendría de iuniores, los jóvenes.", "mas": "Ovidio monta una pequeña escena en la que Juno, Juventas y la Concordia se presentan ante él defendiendo cada una su derecho al nombre del mes. El poeta, prudente, no se pronuncia, recordando que el juicio de Paris acabó en una guerra. Hoy se acepta que viene de Juno.", "fuente": "Ovidio, Fastos 6, 1-100; Macrobio, Saturnales 1, 12, 30-31"},
  "06-05": {"anno": "466 a. n. e.", "titulo": "Dius Fidius, el dios de los juramentos", "texto": "En las nonas de junio se celebraba el templo de Semo Sanco Dius Fidius, que vigilaba la palabra dada. Juraban por él al aire libre.", "mas": "La expresión medius fidius, «así me ayude Dius Fidius», era tan común como nuestro «palabra de honor». Se decía que había que pronunciarla bajo el cielo abierto, y por eso el templo tenía un agujero en el techo. Ovidio duda de si el dios era Sanco, Fidio o Semo Padre, y acaba diciendo que da igual: los tres son el mismo.", "fuente": "Ovidio, Fastos 6, 213-218; Varrón, Sobre la lengua latina 5, 66; Dionisio de Halicarnaso 9, 60, 8"},
  "06-06": {"anno": "1599", "titulo": "Bautizan a Velázquez, pintor de mitos", "texto": "Velázquez pintó la Fragua de Vulcano, el Marte, el Mercurio y Argos y Las hilanderas, que esconde la fábula de Aracne.", "mas": "En Las hilanderas, el primer plano muestra un taller de tapices y, al fondo, la escena de Ovidio: Atenea, con casco, castiga a Aracne, que la ha desafiado tejiendo los amores de los dioses. El tapiz del fondo reproduce El rapto de Europa de Tiziano. En la Fragua, Apolo entra a contar a Vulcano que su esposa Venus le engaña con Marte.", "fuente": "Museo del Prado, P001173 y P001171; Ovidio, Metamorfosis 6, 1-145"},
  "06-07": {"anno": "calendario romano", "titulo": "Se abre el almacén de Vesta", "texto": "Del 7 al 15 de junio se abría el penus de Vesta, la parte secreta del templo. Las matronas entraban descalzas a llevar ofrendas.", "mas": "El templo circular de Vesta guardaba el fuego de la ciudad y unos objetos sagrados que solo veían las vestales, entre ellos, según la tradición, el Paladio traído de Troya por Eneas. Durante estos días el templo se abría a las mujeres, y el 9 se celebraban las Vestalia: los panaderos coronaban a los asnos que movían sus molinos. Ovidio cuenta que él mismo vio volver a una matrona descalza del templo.", "fuente": "Ovidio, Fastos 6, 249-468; Festo, s. v. Penus Vestae"},
  "06-08": {"anno": "1903", "titulo": "Nace Marguerite Yourcenar", "texto": "La escritora belga dedicó años a escribir las memorias imaginarias del emperador Adriano, que publicó en 1951.", "mas": "Memorias de Adriano es una larga carta del emperador, ya enfermo, al joven Marco Aurelio. Yourcenar la empezó en los años veinte, la abandonó y la retomó tras la guerra. En sus notas cuenta que se inspiró en una frase de Flaubert: los dioses ya no existían y Cristo aún no había llegado, y hubo un momento en que el hombre estuvo solo. Fue la primera mujer elegida para la Academia francesa, en 1980.", "fuente": "M. Yourcenar, Mémoires d'Hadrien, 1951; Carnets de notes de Mémoires d'Hadrien"},
  "06-09": {"anno": "68 n. e.", "titulo": "Muere Nerón: «¡Qué artista muere conmigo!»", "texto": "Abandonado por el Senado y los pretorianos, Nerón se refugia en la villa de un liberto y se da muerte con ayuda de su secretario.", "mas": "Suetonio cuenta los últimos momentos: Nerón repite entre lágrimas «qualis artifex pereo», «¡qué artista muere conmigo!», cita un verso de la Ilíada al oír los caballos que venían a buscarlo y se clava un puñal en la garganta. Tenía 30 años. Con él se extinguió la dinastía de Augusto. Ese mismo día era la fiesta de Vesta.", "fuente": "Suetonio, Nerón 47-49; Dion Casio 63, 27-29"},
  "06-10": {"anno": "1580", "titulo": "Muere Camões, el Virgilio de Portugal", "texto": "El poeta de Os Lusíadas, la epopeya del viaje de Vasco da Gama a la India escrita a imitación de la Eneida, muere en Lisboa.", "mas": "Camões empieza su poema con un eco claro de Virgilio («Armas y varones señalados») y llena el viaje de dioses olímpicos: Venus protege a los portugueses y Baco los persigue. Él mismo navegó hasta Macao y, según la tradición, salvó a nado el manuscrito en un naufragio. Hoy es el Día de Portugal.", "fuente": "L. de Camões, Os Lusíadas, 1572, canto 1; Virgilio, Eneida 1, 1"},
  "06-11": {"anno": "323 a. n. e.", "titulo": "Muere Alejandro Magno en Babilonia", "texto": "Tenía 32 años. La fecha exacta, entre el 10 y el 11 de junio, la conocemos por un diario astronómico babilonio.", "mas": "Los astrónomos de Babilonia anotaban cada noche el cielo y, de paso, lo que pasaba en la ciudad. Una tablilla registra: «el rey murió». Plutarco y Arriano cuentan que Alejandro enfermó tras un banquete y tuvo fiebres varios días. Las teorías sobre su muerte van del veneno a la malaria o la fiebre tifoidea. Ese día los romanos celebraban las Matralia, la fiesta de las madres.", "fuente": "Plutarco, Alejandro 75-77; Arriano, Anábasis 7, 25-26; diarios astronómicos babilonios (BM 45962)"},
  "06-12": {"anno": "por estas fechas", "titulo": "Las Esciras y la conspiración de las mujeres", "texto": "Por estas fechas, en el mes de Esciroforión, las atenienses celebraban las Esciras, una fiesta solo para ellas. Aristófanes imaginó que allí tramaron tomar el poder.", "mas": "En La asamblea de las mujeres, Praxágora y sus amigas aprovechan su reunión en las Esciras para planear el golpe: se disfrazarán de hombres, con barbas postizas, irán a la asamblea y votarán entregar el gobierno a las mujeres. La comedia, del 391 a. n. e., parodia de paso las ideas utópicas de propiedad común que circulaban en Atenas.", "fuente": "Aristófanes, La asamblea de las mujeres 18-59; Escolio a Aristófanes, Tesmoforias 834"},
  "06-13": {"anno": "40 n. e.", "titulo": "Nace Agrícola, el suegro de Tácito", "texto": "Tácito escribió la biografía de su suegro, el general que conquistó buena parte de Britania, y empezó dando la fecha exacta de su nacimiento: los idus de junio.", "mas": "El Agrícola es una obra breve y emocionante. Tácito pone en boca de un jefe caledonio, Cálgaco, una de las críticas más duras al imperialismo romano jamás escritas: «hacen un desierto y lo llaman paz». La frase la escribió un senador romano, imaginando lo que pensaría el enemigo. Agrícola murió en el 93, quizá, insinúa Tácito, envenenado por Domiciano.", "fuente": "Tácito, Agrícola 44, 1 y 30, 5; Tácito, Agrícola 43"},
  "06-14": {"anno": "311 a. n. e.", "titulo": "La huelga de los flautistas", "texto": "A mediados de junio, los flautistas recorrían Roma disfrazados y borrachos. Celebraban una huelga que habían ganado siglos atrás.", "mas": "Livio cuenta que los censores prohibieron a los flautistas comer en el templo de Júpiter, como era costumbre. Ofendidos, se marcharon todos a Tíbur, y en Roma no quedó nadie para tocar en los sacrificios. Los tiburtinos los emborracharon y los devolvieron dormidos en carros. Se les restituyó el privilegio y se les concedió una fiesta de tres días, las Quinquatrias menores.", "fuente": "Livio 9, 30, 5-10; Ovidio, Fastos 6, 651-710; Plutarco, Cuestiones romanas 55"},
  "06-15": {"anno": "calendario romano", "titulo": "Fuera la basura del templo de Vesta", "texto": "Hoy se barría el templo de Vesta y la suciedad se tiraba al Tíber. Hasta que no acababa la limpieza, el día era nefasto.", "mas": "En los calendarios aparece con unas siglas misteriosas: Q. St. D. F., quando stercus delatum fas, «cuando la basura ha sido retirada, el día es hábil». Ovidio aconseja a las jóvenes que no se casen hasta que el Tíber se haya llevado la basura de Vesta. Hasta ese momento, el flamen de Júpiter no podía peinarse ni cortarse las uñas.", "fuente": "Varrón, Sobre la lengua latina 6, 32; Ovidio, Fastos 6, 225-234 y 713-714; Festo, s. v. Quando stercus"},
  "06-16": {"anno": "por estas fechas", "titulo": "Las arréforas bajan de noche", "texto": "Por estas fechas, dos niñas que habían vivido un año en la Acrópolis bajaban de noche con unos objetos secretos que ni ellas sabían qué eran.", "mas": "Las arréforas eran niñas de entre siete y once años, de buenas familias atenienses, que ayudaban a tejer el peplo de Atenea. Pausanias describe el rito: la sacerdotisa les ponía en la cabeza unos cestos cerrados, ellas bajaban por un pasadizo subterráneo hasta un recinto en el jardín de Afrodita, dejaban lo que llevaban y subían otra cosa, también tapada. Nadie sabía qué contenían.", "fuente": "Pausanias 1, 27, 3; Aristófanes, Lisístrata 641"},
  "06-17": {"anno": "362 n. e.", "titulo": "Juliano prohíbe a los cristianos enseñar a los clásicos", "texto": "Una ley del emperador Juliano exige que los maestros sean aprobados por las ciudades. En la práctica, deja sin escuelas a los profesores cristianos.", "mas": "Juliano lo explicó en una carta: era hipócrita enseñar a Homero y Hesíodo sin creer en los dioses de los que hablaban; que los cristianos se fueran a las iglesias a explicar a Mateo y Lucas. La medida escandalizó incluso a Amiano Marcelino, pagano y admirador de Juliano, que la consideró dura y digna de olvido. Duró lo que su autor: un año.", "fuente": "Código Teodosiano 13, 3, 5; Juliano, Carta 61c; Amiano Marcelino 22, 10, 7"},
  "06-18": {"anno": "1933", "titulo": "Medea vuelve al teatro romano de Mérida", "texto": "Margarita Xirgu representa la Medea de Séneca, en versión de Unamuno, en el teatro de Mérida. Es la primera función profesional allí en siglos.", "mas": "Al estreno acudieron unas tres mil personas, entre ellas el presidente de la República, Manuel Azaña, y el propio Unamuno. La idea fue del arqueólogo José Ramón Mélida, que había excavado el teatro. Aquella función es el origen del Festival de Teatro Clásico de Mérida, que se celebra cada verano desde 1953.", "fuente": "Festival Internacional de Teatro Clásico de Mérida; diario El Sol, 20 de junio de 1933"},
  "06-19": {"anno": "415 a. n. e.", "titulo": "Las troyanas: la guerra contada por las vencidas", "texto": "En el Día contra la violencia sexual en los conflictos, una tragedia: Eurípides puso en escena a las mujeres de Troya repartidas como botín.", "mas": "Las troyanas se estrenó en las Dionisias del 415 a. n. e., pocos meses después de que Atenas arrasara la isla de Melos, matara a los hombres y esclavizara a mujeres y niños. Hécuba, Andrómaca y Casandra esperan saber a qué griego les ha tocado servir. Muchos lectores han visto en la obra una crítica a su propia ciudad, aunque es difícil saber cuánto quiso decir Eurípides.", "fuente": "Eurípides, Las troyanas; Tucídides 5, 84-116; Eliano, Historias variadas 2, 8"},
  "06-20": {"anno": "2009", "titulo": "Se inaugura el nuevo Museo de la Acrópolis", "texto": "Al pie de la Acrópolis abre un museo con una sala de cristal pensada para exponer el friso del Partenón. Los huecos de lo que está en Londres se señalan.", "mas": "La sala superior tiene la misma orientación y tamaño que el Partenón, que se ve a través de los ventanales. El friso se muestra en su orden original, combinando los originales que están en Atenas con copias en yeso de las piezas que se llevó Lord Elgin a comienzos del siglo XIX y que conserva el Museo Británico. Grecia reclama su devolución desde hace décadas.", "fuente": "Museo de la Acrópolis, Atenas; B. Tschumi, proyecto arquitectónico, 2009"},
  "06-21": {"anno": "217 a. n. e.", "titulo": "Trasimeno: la emboscada en la niebla", "texto": "Aníbal oculta su ejército en las colinas junto al lago Trasimeno y destroza al ejército del cónsul Flaminio, que avanza entre la niebla.", "mas": "Fue la mayor emboscada de la historia antigua: unos quince mil romanos murieron, muchos ahogados en el lago. La fecha es discutida: Ovidio dice que fue el décimo día antes del final de junio, lo que puede entenderse como el 21 o el 22, y el día es del calendario romano de entonces. Livio cuenta que, durante la batalla, hubo un terremoto que nadie notó.", "fuente": "Livio 22, 4-7; Polibio 3, 82-85; Ovidio, Fastos 6, 763-768"},
  "06-22": {"anno": "168 a. n. e.", "titulo": "Pidna: un eclipse antes de la batalla", "texto": "La noche antes, la luna se eclipsa. Al día siguiente, Emilio Paulo derrota al rey Perseo y acaba con el reino de Macedonia.", "mas": "Livio cuenta que un oficial romano, Galo, había anunciado el eclipse a los soldados para que no se asustaran, mientras que los macedonios lo tomaron como un mal presagio. El eclipse lunar del 21 de junio del 168 a. n. e. permite fijar la batalla en nuestro calendario. La falange macedonia, invencible en terreno llano, se desordenó en el terreno irregular y las legiones la destrozaron.", "fuente": "Livio 44, 37-42; Plutarco, Emilio Paulo 17-22"},
  "06-23": {"anno": "79 n. e.", "titulo": "Muere Vespasiano: «Me estoy convirtiendo en dios»", "texto": "El fundador de la dinastía Flavia muere en su tierra natal, cerca de Reate. Bromeó hasta el final.", "mas": "Vespasiano era famoso por su sentido del humor. Suetonio cuenta que, al sentirse morir, dijo «vae, puto deus fio», «ay, creo que me estoy convirtiendo en dios», burlándose de la divinización de los emperadores. Y que quiso morir de pie, porque un emperador debía morir así. Fue también el del célebre impuesto sobre la orina: «el dinero no huele».", "fuente": "Suetonio, Vespasiano 23-24"},
  "06-24": {"anno": "calendario romano", "titulo": "Fors Fortuna: todos al río", "texto": "Los romanos bajaban por el Tíber en barcas adornadas hasta el templo de la Fortuna, y volvían borrachos. Era la fiesta de los que no tenían nada.", "mas": "El templo lo había fundado, según la tradición, el rey Servio Tulio, hijo de una esclava, y por eso la fiesta era especialmente de la plebe y de los esclavos. Ovidio describe a los jóvenes coronados volviendo río arriba sin pudor por lo que habían bebido. Hoy, día de San Juan, se celebran fiestas de solsticio en muchos lugares.", "fuente": "Ovidio, Fastos 6, 773-786; Varrón, Sobre la lengua latina 6, 17"},
  "06-25": {"anno": "por estas fechas", "titulo": "Las Bufonias: el juicio al hacha", "texto": "Por estas fechas, en Atenas, se sacrificaba un buey a Zeus y luego se juzgaba a los culpables. Al final, condenaban al cuchillo y lo tiraban al mar.", "mas": "En las Dipolias, el buey que se comía el grano del altar era sacrificado. Los participantes se echaban la culpa unos a otros: las aguadoras culpaban a los que afilaron el hacha, estos al que la llevó, y así hasta el cuchillo, que, al no poder defenderse, era declarado culpable. Aristófanes ya se burla de la fiesta como algo pasado de moda.", "fuente": "Porfirio, Sobre la abstinencia 2, 29-30; Pausanias 1, 24, 4; Aristófanes, Nubes 984-985"},
  "06-26": {"anno": "363 n. e.", "titulo": "Muere Juliano en Persia", "texto": "Durante la retirada, una lanza alcanza al emperador. Muere esa noche en su tienda, conversando sobre el alma con dos filósofos.", "mas": "Amiano Marcelino, que estaba allí, describe la escena como una muerte filosófica a la manera antigua. La frase «¡Venciste, Galileo!» es una leyenda cristiana posterior, recogida por Teodoreto. No se sabe quién lanzó la lanza: los persas, un sarraceno aliado o, según los rumores, un soldado cristiano del propio ejército.", "fuente": "Amiano Marcelino 25, 3; Libanio, Discurso 18, 274; Teodoreto, Historia eclesiástica 3, 25"},
  "06-27": {"anno": "1787", "titulo": "Gibbon termina la Historia de la decadencia y caída", "texto": "Entre las once y las doce de la noche, en su jardín de Lausana, Gibbon escribe la última línea de su obra. Le habían costado veinte años.", "mas": "Gibbon cuenta el momento en sus memorias: dejó la pluma, paseó bajo las acacias y sintió primero alegría por haber recuperado la libertad, y después melancolía por haberse despedido de un viejo amigo. La idea, recuerda, le vino en Roma en 1764, oyendo a los frailes cantar vísperas entre las ruinas del Capitolio.", "fuente": "E. Gibbon, Memoirs of My Life"},
  "06-28": {"anno": "1712", "titulo": "Nace Rousseau, que de niño leía a Plutarco", "texto": "El filósofo de Ginebra cuenta que leía las Vidas paralelas de Plutarco con su padre hasta el amanecer, y que se creía griego o romano.", "mas": "En las Confesiones, Rousseau dice que de aquellas lecturas sacó un espíritu libre y republicano y un carácter indomable. Más tarde admiró a Esparta y a la Roma republicana por encima de la Atenas refinada. Su ideal de ciudadano virtuoso, sacado de Plutarco, influyó en los revolucionarios franceses, que se vestían y se ponían nombres de romanos.", "fuente": "J.-J. Rousseau, Les Confessions, libro 1; Discurso sobre las ciencias y las artes, 1750"},
  "06-29": {"anno": "1798", "titulo": "Nace Leopardi, poeta y filólogo", "texto": "El gran poeta italiano fue un niño prodigio de la filología: a los quince años escribía comentarios eruditos sobre autores griegos.", "mas": "Encerrado en la enorme biblioteca de su padre en Recanati, Leopardi aprendió solo griego, latín y hebreo. Tradujo a Homero, a Mosco y a Epicteto, y llegó a engañar a los eruditos con un falso himno griego compuesto por él. Su pesimismo poético dialoga continuamente con los antiguos. Hoy la Iglesia celebra a Pedro y Pablo, cuya fiesta ya aparece en el calendario de Roma del año 354.", "fuente": "G. Leopardi, Zibaldone; Inno a Nettuno, 1817; Cronógrafo de 354"},
  "06-30": {"anno": "c. 8 n. e.", "titulo": "Aquí se acaba el calendario de Ovidio", "texto": "Los Fastos de Ovidio terminan el 30 de junio. Los otros seis meses nunca se escribieron, o se perdieron: el destierro se cruzó en el camino.", "mas": "El último día de junio Ovidio celebra el templo de Hércules de las Musas, donde las diosas, tocando la lira, convencen a Hércules. El poema, en dísticos elegíacos, recorre día a día las fiestas romanas. Augusto desterró al poeta a Tomis en el 8 n. e. por «un poema y un error» que nunca explicó. Él dice en las Tristes que había escrito doce libros, pero solo conocemos seis.", "fuente": "Ovidio, Fastos 6, 797-812; Ovidio, Tristes 2, 207 y 2, 549-552"},
  "07-01": {"anno": "1952", "titulo": "Ventris anuncia que el lineal B es griego", "texto": "Un joven arquitecto inglés, Michael Ventris, explica en la radio de la BBC que la escritura de las tablillas micénicas esconde la lengua griega.", "mas": "Las tablillas en lineal B, halladas en Cnosos y en Pilos, llevaban medio siglo sin descifrarse. Ventris, que no era filólogo de profesión, construyó tablas de signos a partir del trabajo previo de Alice Kober y descubrió nombres de lugares cretenses. Con el filólogo John Chadwick lo demostró en 1953. La lengua de los palacios micénicos era un griego unos 500 años anterior a Homero.", "fuente": "M. Ventris y J. Chadwick, «Evidence for Greek Dialect in the Mycenaean Archives», JHS 73 (1953); J. Chadwick, The Decipherment of Linear B, 1958"},
  "07-02": {"anno": "1522", "titulo": "Muere Nebrija, el gramático orgulloso", "texto": "Antonio de Nebrija, autor de las Introductiones Latinae y de la primera gramática del castellano, muere en Alcalá de Henares.", "mas": "Nebrija estudió en Bolonia y volvió a España decidido a desterrar el mal latín de las escuelas, a los que llamaba «bárbaros». Sus Introductiones Latinae (1481) fueron el manual de latín en España durante siglos. Se llamaba a sí mismo Aelius Antonius Nebrissensis, latinizando el nombre de su Lebrija natal, y defendía con orgullo el oficio de gramático.", "fuente": "Biblioteca Nacional de España, Nebrija (c. 1444-1522). El orgullo de ser gramático, 2022"},
  "07-03": {"anno": "324 n. e.", "titulo": "Constantino vence a Licinio en Adrianópolis", "texto": "Empieza la última guerra civil entre los dos emperadores. En pocos meses Constantino quedará como único señor del Imperio.", "mas": "Constantino y Licinio se habían repartido el Imperio, Occidente y Oriente, tras el acuerdo de Milán. La batalla de Adrianópolis, en Tracia, fue seguida por la victoria naval de Crispo, hijo de Constantino, en el Helesponto, y por la definitiva de Crisópolis en septiembre. Al año siguiente Constantino convocó el concilio de Nicea y empezó a construir su nueva capital.", "fuente": "Origo Constantini 5, 24-27; Zósimo 2, 22-26"},
  "07-04": {"anno": "13 a. n. e.", "titulo": "El Senado decide levantar el Ara Pacis", "texto": "Augusto vuelve a Roma de Hispania y la Galia, y el Senado vota construir un altar a la Paz Augusta en el Campo de Marte.", "mas": "Augusto lo cuenta en sus Res gestae: el Senado decretó que en el altar los magistrados, los sacerdotes y las vestales hicieran cada año un sacrificio. El monumento se consagraría el 30 de enero del 9 a. n. e. Sus relieves con la familia imperial en procesión pueden compararse con el friso del Partenón, que su escultor seguramente conocía.", "fuente": "Augusto, Res gestae 12; Fastos de Amiterno"},
  "07-05": {"anno": "calendario romano", "titulo": "Poplifugia, la huida del pueblo", "texto": "Los romanos no sabían bien qué recordaba esta fiesta: o una huida ante un ataque enemigo o el día en que Rómulo desapareció.", "mas": "Varrón dice que conmemoraba la fuga del pueblo ante los vecinos de Ficulea y Fidenas. Plutarco, en cambio, la relaciona con la desaparición de Rómulo durante una tormenta, cuando la multitud huyó asustada. Es un buen ejemplo de fiestas muy antiguas cuyo sentido se había perdido ya en época republicana.", "fuente": "Varrón, Sobre la lengua latina 6, 18; Plutarco, Rómulo 27-29; Macrobio, Saturnales 3, 2, 14"},
  "07-06": {"anno": "212 a. n. e.", "titulo": "Empiezan los Juegos Apolinares", "texto": "Del 6 al 13 de julio, teatro y carreras en honor de Apolo. Se crearon en plena guerra contra Aníbal, por consejo de unos versos proféticos.", "mas": "Livio cuenta que un adivino llamado Marcio había dejado unos versos que aconsejaban instituir juegos a Apolo para expulsar al enemigo. Durante la primera celebración, un ataque obligó a la gente a dejar el teatro y correr a las murallas. Otro 6 de julio, del 83 a. n. e., ardió el templo de Júpiter en el Capitolio, y con él los libros sibilinos originales.", "fuente": "Livio 25, 12; Macrobio, Saturnales 1, 17, 25-30; Tácito, Historias 3, 72; Plutarco, Sila 27"},
  "07-07": {"anno": "calendario romano", "titulo": "Nonas Caprotinas: las esclavas salvan Roma", "texto": "Las esclavas celebraban hoy un banquete bajo una higuera silvestre. Recordaban cómo una de ellas engañó a un ejército enemigo.", "mas": "Plutarco y Macrobio cuentan la historia: tras el saqueo galo, los latinos exigieron a Roma que les entregara a sus mujeres libres. Una esclava, Filótide o Tutela, propuso ir ella con otras esclavas vestidas de matronas. Ya en el campamento enemigo, emborracharon a los soldados y desde una higuera hicieron señales con una antorcha a los romanos, que atacaron por sorpresa. El Senado las liberó y les concedió una fiesta.", "fuente": "Plutarco, Camilo 33; Plutarco, Rómulo 29; Macrobio, Saturnales 1, 11, 35-40; Varrón, Sobre la lengua latina 6, 18"},
  "07-08": {"anno": "1851", "titulo": "Nace Arthur Evans", "texto": "El excavador de Cnosos, que puso nombre a la civilización minoica, nació en Nash Mills, Inglaterra.", "mas": "Evans era hijo de un rico fabricante de papel y arqueólogo aficionado. Antes de Creta fue periodista en los Balcanes y director del Ashmolean Museum de Oxford. Se interesó por Creta al ver unos sellos de piedra con signos que nadie sabía leer. Fue él quien inventó las etiquetas «minoico» (por el rey Minos), «lineal A» y «lineal B».", "fuente": "Ashmolean Museum, Sir John Evans Centenary Project; J. Evans, Time and Chance, 1943"},
  "07-09": {"anno": "44 a. n. e.", "titulo": "Quintilis pasa a llamarse julio", "texto": "El año del asesinato de César, una ley de Marco Antonio rebautizó el mes en que había nacido: el quinto mes, Quintilis, pasó a ser Iulius.", "mas": "Los nombres de los meses de julio a diciembre eran números: quintilis, sextilis, september... porque el año empezaba en marzo. Poner a un mes el nombre de un hombre era un honor reservado a los dioses, y la medida escandalizó a algunos. Cicerón se queja en una carta de que, en los Juegos Apolinares, se anunciara la fecha como «nonas de julio».", "fuente": "Macrobio, Saturnales 1, 12, 34; Suetonio, César 76; Cicerón, Cartas a Ático 16, 1, 1 y 16, 4, 1"},
  "07-10": {"anno": "138 n. e.", "titulo": "Muere Adriano: «Almita vagabunda»", "texto": "El emperador muere en Bayas. Se le atribuye un poema de cinco versos dirigido a su propia alma.", "mas": "La Historia Augusta conserva el poema: animula vagula blandula, «almita vagabunda, cariñosa, huésped y compañera del cuerpo», que pregunta adónde irá ahora, pálida y desnuda, sin hacer las bromas de siempre. Marguerite Yourcenar lo puso al frente de sus Memorias de Adriano. El emperador había preparado su gran mausoleo junto al Tíber, hoy el Castillo de Sant'Angelo.", "fuente": "Historia Augusta, Adriano 25; Dion Casio 69, 22"},
  "07-11": {"anno": "1561", "titulo": "Nace Góngora, el que reescribió a Polifemo", "texto": "El poeta cordobés convirtió el cíclope de Ovidio en protagonista de la Fábula de Polifemo y Galatea, una de las cumbres del barroco.", "mas": "Góngora tomó el episodio de las Metamorfosis en que Polifemo, enamorado de la ninfa Galatea, aplasta con una roca a su rival Acis. Lo reescribió en octavas cargadas de latinismos, hipérbatos y mitología, hasta el punto de que sus contemporáneos discutieron si aquello era poesía o un acertijo. Los poetas de la generación del 27 lo reivindicaron en el tercer centenario de su muerte.", "fuente": "L. de Góngora, Fábula de Polifemo y Galatea, 1612-1613; Ovidio, Metamorfosis 13, 738-897"},
  "07-12": {"anno": "100 a. n. e.", "titulo": "Nace Julio César", "texto": "Nació en el barrio popular de la Subura, en una familia patricia que decía descender de Venus a través de Eneas.", "mas": "Su cumpleaños se celebraba el 12 de julio. Dion Casio explica que en realidad había nacido el 13, pero como ese día eran los Juegos Apolinares y un oráculo prohibía celebrar otra fiesta, se trasladó al 12. La familia Julia presumía de descender de Iulo, hijo de Eneas y nieto de Venus, y César construyó un templo a Venus Genetrix, «madre del linaje».", "fuente": "Macrobio, Saturnales 1, 12, 34; Dion Casio 47, 18, 6; Suetonio, César 6"},
  "07-13": {"anno": "169 a. n. e.", "titulo": "El último estreno de Ennio", "texto": "En los Juegos Apolinares de ese año se estrenó el Tiestes de Ennio. El padre de la poesía latina murió poco después.", "mas": "Cicerón lo cuenta en su historia de la oratoria: el año del consulado de Cepión y Filipo, Ennio estrenó su tragedia Tiestes en los Juegos Apolinares y murió. Había nacido en Rudias, en el sur de Italia, y decía tener tres corazones porque hablaba osco, griego y latín. Sus Anales, la historia de Roma en hexámetros, fueron el gran poema nacional hasta la Eneida.", "fuente": "Cicerón, Bruto 78; Aulo Gelio 17, 17, 1"},
  "07-14": {"anno": "1789", "titulo": "El gorro frigio: un símbolo romano de libertad", "texto": "Los revolucionarios franceses adoptaron un gorro rojo que recordaba el pileus, el gorro de fieltro que se ponían en Roma los esclavos liberados.", "mas": "En Roma, el esclavo recién manumitido se rapaba la cabeza y se ponía el pileus como signo de su nueva condición. Tras los idus de marzo, Bruto acuñó una moneda con un pileus entre dos puñales y la leyenda EID MAR. Los revolucionarios confundieron el pileus con el gorro frigio de los relieves antiguos, y así llegó a las Mariannes y a muchas banderas americanas.", "fuente": "Moneda de Bruto (RRC 508/3); Livio 45, 44, 19; Dion Casio 47, 25, 3"},
  "07-15": {"anno": "496 a. n. e.", "titulo": "Desfile de los caballeros en honor de los Dioscuros", "texto": "Los caballeros romanos desfilaban hoy coronados de olivo, recordando a Cástor y Pólux, que según la leyenda lucharon por Roma en el lago Regilo.", "mas": "Durante la batalla del lago Regilo contra los latinos, dos jinetes jóvenes a caballos blancos aparecieron junto a los romanos, y ese mismo día se les vio en el Foro abrevando sus caballos en la fuente de Yuturna para anunciar la victoria. Eran los Dioscuros. El censor Fabio instituyó en el 304 a. n. e. el desfile anual de los caballeros, la transvectio equitum, que en época de Augusto llegó a reunir a cinco mil jinetes.", "fuente": "Dionisio de Halicarnaso 6, 13; Livio 9, 46, 15; Cicerón, Sobre la naturaleza de los dioses 2, 6"},
  "07-16": {"anno": "1969", "titulo": "Despega el Apolo 11", "texto": "La misión que llevaría a los primeros humanos a la Luna se llamaba como el dios griego de la luz. Su sucesora, Artemisa, como su hermana gemela.", "mas": "El nombre lo propuso Abe Silverstein, de la NASA, en 1960, porque Apolo cruzaba el cielo con el carro del Sol. El módulo lunar se llamaba Eagle y el de mando Columbia. Cuando la NASA preparó el regreso a la Luna con astronautas mujeres, eligió el nombre de Artemisa, la hermana gemela de Apolo y diosa de la Luna para los griegos tardíos.", "fuente": "NASA History Office, «Project Apollo: The Name»; NASA, Artemis Program"},
  "07-17": {"anno": "180 n. e.", "titulo": "Los mártires de Escilio y el latín de África", "texto": "En Cartago, doce cristianos de una pequeña ciudad africana son decapitados. Las actas de su juicio son el texto cristiano en latín más antiguo que tenemos.", "mas": "El documento recoge, casi como un acta judicial, el diálogo con el procónsul Saturnino, que les ofrece treinta días para pensarlo. En una caja llevan «libros y cartas de Pablo, hombre justo». Es la primera mención de textos cristianos en latín. El latín de la Iglesia nació en buena parte en África, con Tertuliano, Cipriano y Agustín.", "fuente": "Actas de los mártires escilitanos"},
  "07-18": {"anno": "390 a. n. e.", "titulo": "El día del Alia, un día maldito", "texto": "Los galos aplastan al ejército romano junto al río Alia y saquean Roma. El 18 de julio quedó marcado para siempre como dies Alliensis.", "mas": "Livio cuenta que el desastre fue tal que los romanos huyeron casi sin luchar y que solo resistió el Capitolio, salvado según la leyenda por los gansos de Juno, que graznaron al oír a los galos trepar. Desde entonces el 18 de julio era un día nefasto: no se emprendía nada. Tácito reprocha a Vitelio que publicara un edicto precisamente ese día. La fecha de 390 es la tradicional; los griegos la daban como 387/386.", "fuente": "Livio 5, 37-49 y 6, 1, 11; Tácito, Historias 2, 91; Plutarco, Camilo 19"},
  "07-19": {"anno": "64 n. e.", "titulo": "Empieza el gran incendio de Roma", "texto": "Arde durante días. Tácito anota que empezó el mismo día en que los galos habían incendiado la ciudad siglos atrás.", "mas": "El fuego empezó en las tiendas junto al Circo Máximo y de los catorce barrios de Roma solo cuatro quedaron intactos. Tácito no afirma que Nerón lo provocara, pero recoge el rumor de que cantó la caída de Troya mientras la ciudad ardía. Nerón culpó a los cristianos, y Tácito los menciona por primera vez en la historia romana al describir los castigos.", "fuente": "Tácito, Anales 15, 38-44; Suetonio, Nerón 38"},
  "07-20": {"anno": "1304", "titulo": "Nace Petrarca, el que buscaba a Cicerón", "texto": "El poeta del Cancionero fue también el primer gran humanista: buscó por media Europa manuscritos de Cicerón y Livio.", "mas": "En 1345, en la biblioteca de la catedral de Verona, Petrarca encontró las cartas de Cicerón a Ático y descubrió, decepcionado, a un Cicerón ambicioso y quejica. Le escribió una carta al muerto reprochándoselo. Otro día, el 26 de abril de 1336, subió al monte Ventoux con un libro de san Agustín en el bolsillo y escribió el relato de la ascensión.", "fuente": "F. Petrarca, Familiares 24, 3 (carta a Cicerón) y 4, 1 (ascensión al Ventoux)"},
  "07-21": {"anno": "365 n. e.", "titulo": "Un tsunami arrasa el Mediterráneo oriental", "texto": "Amiano Marcelino describe cómo el mar se retiró dejando barcos en seco y luego volvió con olas que dejaron naves sobre los tejados de Alejandría.", "mas": "Es la descripción más detallada de un tsunami que nos ha dejado la Antigüedad. Amiano cuenta que la gente se acercó a recoger peces en el fondo marino descubierto y que la ola volvió de golpe. En Alejandría se recordó el aniversario como «día del horror» durante siglos. Los geólogos lo relacionan con un gran terremoto al oeste de Creta.", "fuente": "Amiano Marcelino 26, 10, 15-19; B. Shaw y otros, Nature Geoscience 1 (2008)"},
  "07-22": {"anno": "44 a. n. e.", "titulo": "Un cometa en los juegos de César", "texto": "Durante los juegos en honor de César, celebrados por Octaviano del 20 al 30 de julio, apareció un cometa. El pueblo creyó que era el alma de César subiendo al cielo.", "mas": "Plinio el Viejo cita las propias palabras de Augusto: el cometa se vio durante siete días, hacia la hora undécima, en la zona norte del cielo. Octaviano aprovechó el prodigio para difundir la idea de que César se había convertido en dios: el sidus Iulium aparece en monedas y, en las Metamorfosis de Ovidio, Venus se lleva el alma de César convertida en estrella.", "fuente": "Plinio el Viejo, Historia natural 2, 93-94; Suetonio, César 88; Ovidio, Metamorfosis 15, 843-851"},
  "07-23": {"anno": "calendario romano", "titulo": "Neptunalia, a la sombra", "texto": "En lo más caluroso del verano, los romanos honraban a Neptuno construyendo cabañas de ramas para protegerse del sol.", "mas": "Las cabañas, llamadas umbrae, se levantaban junto al Tíber y en el Campo de Marte, y allí se comía y se bebía. Horacio invita a una amiga en una oda a celebrar la fiesta con vino viejo y canciones. Neptuno, antes de identificarse con el Poseidón griego, era probablemente un dios de las aguas dulces, importante en un verano seco.", "fuente": "Varrón, Sobre la lengua latina 6, 19; Festo, s. v. Umbrae; Horacio, Odas 3, 28"},
  "07-24": {"anno": "1895", "titulo": "Nace Robert Graves, el autor de Yo, Claudio", "texto": "El poeta británico convirtió al emperador tartamudo en narrador de una novela que fue un éxito mundial y una serie de televisión.", "mas": "Graves, que había combatido y sido herido en la Primera Guerra Mundial, publicó Yo, Claudio en 1934 a partir de Suetonio y Tácito. En ella Claudio se hace el tonto para sobrevivir entre las intrigas de su familia, con Livia como gran manipuladora. Graves tradujo además a Suetonio, Lucano y Apuleyo, y escribió Los mitos griegos, un libro tan popular como discutido.", "fuente": "R. Graves, I, Claudius, 1934; The Greek Myths, 1955"},
  "07-25": {"anno": "306 n. e.", "titulo": "Constantino, proclamado emperador en York", "texto": "Muere en Eboracum (York) el emperador Constancio Cloro y sus soldados proclaman Augusto a su hijo Constantino.", "mas": "El sistema de la tetrarquía de Diocleciano preveía que los sucesores fueran elegidos, no heredados. Las tropas de Britania lo ignoraron y aclamaron al hijo del difunto. Hoy una estatua de Constantino sentado preside la entrada de la catedral de York, en la ciudad donde comenzó su reinado.", "fuente": "Lactancio, Sobre la muerte de los perseguidores 24; Eusebio, Vida de Constantino 1, 21-22"},
  "07-26": {"anno": "calendario romano", "titulo": "La canícula: el perro que trae el calor", "texto": "Por estas fechas, según el calendario agrícola de Columela, sale la Canícula, la estrella del Perro. De ahí vienen nuestros «días de canícula».", "mas": "La estrella es Sirio, la más brillante del cielo, en la constelación del Can Mayor. Cuando vuelve a verse al amanecer, a finales de julio, empiezan los días más calurosos. Los griegos ya relacionaban su brillo con la fiebre y la sequía: en la Ilíada, Aquiles corriendo con su armadura brilla como la estrella que trae fiebre a los mortales.", "fuente": "Columela 11, 2, 53; Homero, Ilíada 22, 25-31; Plinio el Viejo, Historia natural 2, 107"},
  "07-27": {"anno": "1835", "titulo": "Nace Carducci, el poeta de los metros antiguos", "texto": "El primer italiano con el premio Nobel de Literatura escribió las Odas bárbaras, en las que imita en italiano los metros de Horacio.", "mas": "Carducci llamó «bárbaras» a sus odas porque, decía, así habrían sonado a oídos de un griego o un romano: intentos de reproducir con acentos italianos los ritmos cuantitativos de la poesía antigua. Fue catedrático de literatura en Bolonia durante más de cuarenta años y recibió el Nobel en 1906.", "fuente": "G. Carducci, Odi barbare, 1877; Fundación Nobel, 1906"},
  "07-28": {"anno": "450 n. e.", "titulo": "Muere Teodosio II, el emperador del Código", "texto": "El emperador de Oriente muere al caerse del caballo. Bajo su nombre se reunieron las leyes del Imperio desde Constantino.", "mas": "Teodosio II reinó casi cincuenta años, aunque su hermana Pulqueria y sus ministros gobernaron mucho por él. Su gran legado es el Código Teodosiano, publicado en 438, que reunió las leyes imperiales desde Constantino y que es una fuente fundamental para la Antigüedad tardía. También mandó levantar las grandes murallas de Constantinopla.", "fuente": "Teófanes, Cronografía, año 5942; Código Teodosiano, Gesta senatus"},
  "07-29": {"anno": "por estas fechas", "titulo": "Sinecias: el día en que Atenas se hizo ciudad", "texto": "Por estas fechas, en el mes de Hecatombeón, los atenienses celebraban las Sinecias, la fiesta que recordaba la unión de las aldeas del Ática en una sola ciudad.", "mas": "Tucídides atribuye esa unificación política a Teseo, el héroe que también mató al Minotauro: reunió los consejos de cada aldea en uno solo, en Atenas. Fue un sinecismo político, no un traslado de población: la gente siguió viviendo en el campo. Unos días después llegaban las Panateneas, la gran fiesta de Atenea.", "fuente": "Tucídides 2, 15, 1-2; Plutarco, Teseo 24"},
  "07-30": {"anno": "44 a. n. e.", "titulo": "Día de la Amistad: Cicerón escribe sobre el amigo", "texto": "En el Día Internacional de la Amistad, el tratado de Cicerón Sobre la amistad, escrito en el año del asesinato de César.", "mas": "Cicerón pone el diálogo en boca de Lelio, que acaba de perder a su gran amigo Escipión. La amistad verdadera, dice, solo puede existir entre personas buenas y se basa en la virtud, no en la utilidad. Del tratado viene la idea de que el amigo es «otro yo», y la regla de no pedir al amigo nada vergonzoso ni hacerlo por él.", "fuente": "Cicerón, Lelio o sobre la amistad 20-22, 40 y 80"},
  "07-31": {"anno": "1919", "titulo": "Nace Primo Levi y el canto de Ulises", "texto": "En Si esto es un hombre, Levi cuenta cómo intentó recordar en Auschwitz el canto de Ulises de Dante para enseñárselo a un compañero.", "mas": "En el capítulo «El canto de Ulises», Levi y su compañero Jean caminan a por la sopa y él trata de reconstruir de memoria los versos de Dante en los que Ulises anima a sus hombres a cruzar las columnas de Hércules: «no fuisteis hechos para vivir como bestias». En el campo, recitar aquello era recordar que seguían siendo hombres. El Ulises de Dante viene de la Odisea, pero su último viaje es invención del poeta.", "fuente": "P. Levi, Se questo è un uomo, 1947, cap. 11; Dante, Infierno 26"},
  "08-01": {"anno": "30 a. n. e.", "titulo": "Octaviano entra en Alejandría y el mes cambia de nombre", "texto": "Antonio se da muerte y Egipto pasa a Roma. Por esta victoria, entre otras, el mes Sextilis se rebautizó «agosto».", "mas": "Macrobio cita el senadoconsulto del 8 a. n. e. que dio el nombre: en ese mes Augusto había sido cónsul por primera vez, había celebrado tres triunfos, había sometido Egipto y había puesto fin a las guerras civiles. Por eso el sexto mes pasó a llamarse Augustus. La idea de que se le quitó un día a febrero para que agosto tuviera tantos como julio es una invención medieval: agosto ya tenía 31 días con César.", "fuente": "Macrobio, Saturnales 1, 12, 35; Dion Casio 51, 10-15; Suetonio, Augusto 31, 2"},
  "08-02": {"anno": "216 a. n. e.", "titulo": "Cannas: la peor derrota de Roma", "texto": "Aníbal rodea y aniquila al mayor ejército que Roma había reunido. Aun así, Roma no se rinde.", "mas": "Aníbal colocó en el centro su infantería más débil, dejó que los romanos la empujaran y la envolvió con la caballería y los veteranos africanos. Murieron decenas de miles de romanos en una tarde. Los romanos marcaron el día como funesto, pero con el tiempo el 2 de agosto se volvió afortunado: César venció en Ilerda (49 a. n. e.) y en Zela (47 a. n. e.), la batalla del «llegué, vi, vencí», en el mismo aniversario.", "fuente": "Aulo Gelio 5, 17, 5; Livio 22, 44-49; Polibio 3, 113-117; Fastos de Amiterno"},
  "08-03": {"anno": "431 a. n. e.", "titulo": "Un eclipse en el primer verano de la guerra", "texto": "Tucídides anota un eclipse de sol al comienzo de la guerra del Peloponeso. Explica, como buen racionalista, que solo puede ocurrir con luna nueva.", "mas": "Tucídides dice que el sol se oscureció por la tarde hasta tomar forma de media luna y que se vieron algunas estrellas. El cálculo astronómico lo fecha el 3 de agosto del 431 a. n. e. Plutarco cuenta que Pericles, para calmar a un piloto asustado, le tapó los ojos con su manto y le preguntó si aquello le parecía terrible: un eclipse es lo mismo, pero con algo más grande que un manto.", "fuente": "Tucídides 2, 28; Plutarco, Pericles 35, 2"},
  "08-04": {"anno": "1897", "titulo": "Aparece la Dama de Elche", "texto": "Un muchacho que trabajaba en la finca de La Alcudia encuentra un busto de piedra con unos enormes rodetes a los lados de la cara.", "mas": "La Dama es ibérica, de hacia los siglos V-IV a. n. e., y muestra la influencia del arte griego que llegaba a la costa levantina a través del comercio. A los pocos días la compró el arqueólogo francés Pierre Paris para el Louvre. Volvió a España en 1941 y hoy está en el Museo Arqueológico Nacional. Tiene un hueco en la espalda, quizá para guardar cenizas.", "fuente": "P. Paris, «Buste espagnol de style gréco-asiatique», Monuments Piot 4 (1897); Museo Arqueológico Nacional"},
  "08-05": {"anno": "57 a. n. e.", "titulo": "El cumpleaños de Tulia", "texto": "Cicerón vuelve del destierro y desembarca en Brindisi en las nonas de agosto. Su hija Tulia le espera allí: es su cumpleaños.", "mas": "Lo cuenta él mismo a Ático, emocionado: llegó a Brindisi el mismo día en que se celebraba el aniversario de la colonia y del templo de la Salud, y el cumpleaños de su querida Tuliola, que lo recibió en el puerto. Tulia murió doce años después, tras dar a luz, y Cicerón quedó destrozado: llegó a planear un santuario en su honor.", "fuente": "Cicerón, Cartas a Ático 4, 1, 4 y 12, 36"},
  "08-06": {"anno": "por estas fechas", "titulo": "Las Panateneas: un vestido nuevo para Atenea", "texto": "Por estas fechas, a finales del mes de Hecatombeón, Atenas celebraba las Panateneas, con una procesión que llevaba a la Acrópolis un peplo tejido para la diosa.", "mas": "Cada cuatro años se celebraban las Grandes Panateneas, con concursos atléticos y musicales. Los vencedores recibían ánforas llenas de aceite de los olivos sagrados de Atenea, decoradas con la diosa armada; se conservan muchas en los museos. Muchos estudiosos creen que el friso del Partenón representa esta procesión, aunque otros proponen interpretaciones míticas.", "fuente": "Aristóteles, Constitución de los atenienses 60; Píndaro, Nemea 10, 33-36; J. Neils, The Parthenon Frieze, 2001"},
  "08-07": {"anno": "por estas fechas", "titulo": "Los Juegos Olímpicos y la tregua sagrada", "texto": "Los Juegos de Olimpia se celebraban en la segunda luna llena después del solsticio de verano, es decir, por estas fechas, cada cuatro años.", "mas": "Antes de los Juegos, unos heraldos recorrían Grecia anunciando la tregua, la ekecheiría, que garantizaba el paso seguro de atletas y espectadores. No paraba las guerras, pero quien la violaba podía ser multado y excluido. En el 420 a. n. e. se excluyó a los espartanos por haberla roto. Las mujeres casadas no podían asistir, pero sí las doncellas, y había juegos aparte en honor de Hera.", "fuente": "Tucídides 5, 49-50; Pausanias 5, 16, 2-4 y 6, 20, 9; Escolio a Píndaro, Olímpica 3, 35"},
  "08-08": {"anno": "117 n. e.", "titulo": "Muere Trajano lejos de Roma", "texto": "Hacia estas fechas, volviendo enfermo de la campaña contra los partos, Trajano muere en Selinunte, en Cilicia. Su sucesor se anuncia días después.", "mas": "Trajano había llevado el Imperio a su mayor extensión, hasta el golfo Pérsico. Murió de un derrame y la adopción de Adriano se anunció a título póstumo; Dion Casio sospecha que la emperatriz Plotina la arregló. Sus cenizas se llevaron a Roma y se depositaron en la base de su columna. Fue el único al que se enterró dentro del recinto sagrado de la ciudad.", "fuente": "Dion Casio 68, 33 y 69, 1; Historia Augusta, Adriano 4"},
  "08-09": {"anno": "48 a. n. e.", "titulo": "Farsalia: César contra Pompeyo", "texto": "César derrota a Pompeyo en Tesalia. Pompeyo huye a Egipto, donde lo asesinan al desembarcar.", "mas": "El ejército de Pompeyo era más del doble, pero César había preparado una cuarta línea oculta que desbarató la carga de caballería enemiga. Al ver el campo lleno de cadáveres, según Asinio Polión, que estaba allí, César dijo: «Ellos lo quisieron». Otro 9 de agosto, del 378, el emperador Valente moría en Adrianópolis ante los godos, una de las peores derrotas de Roma.", "fuente": "César, Guerra civil 3, 88-99; Suetonio, César 30, 4; Amiano Marcelino 31, 12-13"},
  "08-10": {"anno": "258 n. e.", "titulo": "Lorenzo, el diácono hispano de Roma", "texto": "El calendario romano del 354 recuerda hoy al diácono Lorenzo, ejecutado en la persecución de Valeriano. La tradición lo hace natural de Huesca.", "mas": "Ambrosio cuenta que, cuando le pidieron los tesoros de la Iglesia, Lorenzo presentó a los pobres. La leyenda de la parrilla, en la que habría bromeado con sus verdugos, la difundió Prudencio en un himno. Felipe II le dedicó el monasterio de El Escorial, cuya planta, según una tradición sin base, imita una parrilla. Las Perseidas de estos días se llaman en muchos lugares «lágrimas de san Lorenzo».", "fuente": "Cronógrafo de 354, Depositio martyrum; Ambrosio, Sobre los deberes 2, 140; Prudencio, Peristephanon 2"},
  "08-11": {"anno": "117 n. e.", "titulo": "Adriano, emperador", "texto": "En Antioquía llega la noticia de que Trajano ha muerto y lo ha adoptado. Adriano fija este día como el de su llegada al poder.", "mas": "La Historia Augusta dice que Adriano celebró el 11 de agosto como su dies imperii. Nada más llegar, renunció a las conquistas de Trajano al otro lado del Éufrates, que consideraba imposibles de defender. Su política fue fijar y fortificar fronteras: el muro que lleva su nombre en Britania es el mejor ejemplo.", "fuente": "Historia Augusta, Adriano 4, 6-7 y 11, 2; Dion Casio 69, 2"},
  "08-12": {"anno": "30 a. n. e.", "titulo": "Muere Cleopatra", "texto": "Hacia estas fechas, Cleopatra VII, la última reina de Egipto, se da muerte en Alejandría para no desfilar en el triunfo de Octaviano.", "mas": "La fecha exacta no se conoce; se sitúa entre el 10 y el 12 de agosto. Plutarco cuenta que se hizo llevar una cobra escondida en una cesta de higos, pero él mismo reconoce que nadie supo con certeza cómo murió: quizá veneno guardado en una aguja hueca. Cleopatra era griega, de la dinastía de los Ptolomeos, y según Plutarco la primera de su familia que aprendió egipcio.", "fuente": "Plutarco, Antonio 27 y 84-86; Dion Casio 51, 11-14"},
  "08-13": {"anno": "calendario romano", "titulo": "Idus de agosto: fiesta de los esclavos", "texto": "Hoy se celebraba el templo de Diana en el Aventino, fundado según la tradición por el rey Servio Tulio, hijo de una esclava. Los esclavos tenían el día libre.", "mas": "Festo dice que el día era fiesta de los siervos porque Servio había nacido esclavo. Las mujeres se lavaban el pelo en honor de Diana y acudían al templo con antorchas, y Plutarco dedica una de sus Cuestiones romanas a explicar por qué. El templo era federal: lo compartían Roma y las ciudades latinas.", "fuente": "Festo, s. v. Servorum dies; Plutarco, Cuestiones romanas 100; Livio 1, 45"},
  "08-14": {"anno": "29 a. n. e.", "titulo": "El triple triunfo de Octaviano", "texto": "Del 13 al 15 de agosto, Octaviano celebra tres triunfos seguidos: por Iliria, por Accio y por Egipto.", "mas": "El tercer día fue el más espectacular, con una efigie de Cleopatra con el áspid y los dos hijos de ella y Antonio, Alejandro Helio y Cleopatra Selene, desfilando. Octaviano repartió dinero a cada ciudadano y a los veteranos. Ese mismo año se cerró el templo de Jano, en señal de paz.", "fuente": "Augusto, Res gestae 4; Dion Casio 51, 21-22; Virgilio, Eneida 8, 714-728"},
  "08-15": {"anno": "310 a. n. e.", "titulo": "Agatocles navega hacia África bajo un eclipse", "texto": "El tirano de Siracusa rompe el bloqueo cartaginés y lleva la guerra a África. Al día siguiente de zarpar, un eclipse total de sol asusta a sus hombres.", "mas": "Diodoro cuenta que el día se volvió noche y se vieron las estrellas, y que Agatocles tuvo que convencer a sus soldados de que no era un mal presagio. Una vez en África, quemó sus propias naves para que nadie pensara en volver. Es uno de los eclipses antiguos mejor fechados gracias al cálculo astronómico.", "fuente": "Diodoro de Sicilia 20, 5-7; Justino 22, 6"},
  "08-16": {"anno": "1972", "titulo": "Aparecen los bronces de Riace", "texto": "Un buceador aficionado ve un brazo saliendo de la arena frente a Riace, en Calabria. Son dos guerreros griegos de bronce del siglo V a. n. e.", "mas": "Stefano Mariottini pensó al principio que era un cadáver. Los dos guerreros, de casi dos metros, son de los pocos grandes bronces griegos originales que conservamos, porque la mayoría se fundieron para reutilizar el metal. Tienen los ojos incrustados, labios y pezones de cobre y dientes de plata. Están en el Museo de Reggio Calabria y siguen sin saberse con certeza autor ni origen.", "fuente": "Museo Archeologico Nazionale di Reggio Calabria; C. O. Pavese, L'auriga di Mozia e i bronzi di Riace, 1996"},
  "08-17": {"anno": "calendario romano", "titulo": "Portunalia: el dios de las puertas y los puertos", "texto": "Hoy se honraba a Portuno, el dios de las puertas, que acabó siendo el de los puertos. Su templo, junto al Tíber, todavía está en pie.", "mas": "Portus en latín antiguo significaba «paso» y estaba emparentado con porta, «puerta». Portuno tenía una llave como atributo. Su templo del Foro Boario, que durante siglos se llamó erróneamente de la Fortuna Viril, es uno de los templos republicanos mejor conservados de Roma, porque se convirtió en iglesia.", "fuente": "Varrón, Sobre la lengua latina 6, 19; Festo, s. v. Portunus"},
  "08-18": {"anno": "29 a. n. e.", "titulo": "Se dedica el templo del Divino Julio", "texto": "En el Foro, en el lugar donde se quemó el cadáver de César, Octaviano consagra un templo a su padre adoptivo convertido en dios.", "mas": "Los restos del templo se conservan en el Foro Romano y en el altar todavía se dejan flores cada 15 de marzo. Dion Casio cuenta que en la dedicación se adornó con los espolones de los barcos de Antonio y Cleopatra capturados en Accio. Era la primera vez que un romano recibía en el Foro un templo como dios.", "fuente": "Dion Casio 51, 22, 1-3; Augusto, Res gestae 19 y 21; Fastos de Antium"},
  "08-19": {"anno": "14 n. e.", "titulo": "Muere Augusto en Nola", "texto": "Según Suetonio, pidió a sus amigos que lo aplaudieran si había representado bien la comedia de la vida.", "mas": "Augusto murió en la misma habitación que su padre, a punto de cumplir 76 años, besando a Livia. Suetonio recoge sus últimas palabras: «Livia, vive acordándote de nuestro matrimonio, y adiós». Murió el mes que llevaba su nombre. Había gobernado más de cuarenta años, y casi nadie en Roma recordaba otra cosa.", "fuente": "Suetonio, Augusto 99-100; Tácito, Anales 1, 5"},
  "08-20": {"anno": "2 n. e.", "titulo": "Muere Lucio César, nieto de Augusto", "texto": "El nieto y heredero de Augusto muere de repente en Massalia (Marsella), camino de Hispania. Tenía diecinueve años.", "mas": "Augusto había adoptado a sus dos nietos, Gayo y Lucio, para que le sucedieran. Lucio murió en Massalia y Gayo, año y medio después, en Licia. La ciudad de Pisa aprobó en su honor unos decretos que se han conservado grabados en piedra, con la fecha de la muerte. Tácito insinúa que Livia tuvo algo que ver, para despejar el camino a su hijo Tiberio.", "fuente": "Decretos de Pisa (CIL XI 1420); Tácito, Anales 1, 3; Suetonio, Augusto 65"},
  "08-21": {"anno": "calendario romano", "titulo": "Consualia: la fiesta del rapto de las sabinas", "texto": "Según la leyenda, Rómulo organizó la primera Consualia para atraer a los vecinos sabinos y raptar a sus hijas.", "mas": "Livio cuenta que Rómulo, necesitado de mujeres para su ciudad, invitó a los pueblos vecinos a unos juegos en honor de Conso, dios de los graneros, y a una señal los romanos raptaron a las jóvenes sabinas. Conso tenía un altar subterráneo en el Circo Máximo que solo se descubría en sus fiestas. Ese día descansaban los caballos y mulas, que se coronaban de flores.", "fuente": "Livio 1, 9; Plutarco, Rómulo 14; Dionisio de Halicarnaso 1, 33, 2"},
  "08-22": {"anno": "408 n. e.", "titulo": "Ejecutan a Estilicón", "texto": "El general medio vándalo que había defendido Occidente durante trece años es decapitado en Rávena por orden de Honorio.", "mas": "Estilicón había frenado varias veces a Alarico y a otros invasores, pero sus enemigos en la corte lo acusaron de querer poner a su hijo en el trono. Tras su muerte, los soldados romanos mataron a las familias de los federados bárbaros y miles de estos se pasaron a Alarico. Dos años después, los godos saquearon Roma.", "fuente": "Zósimo 5, 32-35; Olimpiodoro, fragmento 5; Claudiano, Sobre el consulado de Estilicón"},
  "08-23": {"anno": "calendario romano", "titulo": "Volcanalia: Plinio se pone a estudiar", "texto": "En la fiesta de Vulcano se arrojaban peces vivos al fuego. Plinio el Viejo empezaba ese día a estudiar a la luz de una lámpara, todavía de noche.", "mas": "Su sobrino Plinio el Joven cuenta, admirado, la disciplina de su tío: desde las Volcanalia empezaba a trabajar antes del amanecer, a la luz de la lámpara, para aprovechar el tiempo. Así pudo escribir los 37 libros de la Historia natural mientras desempeñaba cargos públicos. Al año del Vesubio, el 79, la erupción empezó al día siguiente de esta fiesta.", "fuente": "Plinio el Joven, Cartas 3, 5, 8-9; Varrón, Sobre la lengua latina 6, 20; Festo, s. v. Piscatorii ludi"},
  "08-24": {"anno": "79 n. e.", "titulo": "¿Erupción del Vesubio?", "texto": "Es la fecha que dan los manuscritos de Plinio el Joven. Una inscripción a carbón hallada en Pompeya en 2018 apunta más bien a octubre. El debate sigue abierto.", "mas": "Plinio el Joven escribió a Tácito dos cartas sobre la erupción y la muerte de su tío, que acudió con la flota de Miseno a rescatar a los vecinos. Los manuscritos dan «nueve días antes de las calendas de septiembre», pero las frutas de otoño halladas en Pompeya y una inscripción con fecha de mediados de octubre hacen pensar en un error de copia. Otro 24 de agosto, del 410, los godos de Alarico entraron en Roma.", "fuente": "Plinio el Joven, Cartas 6, 16 y 6, 20; M. Osanna, Pompei. Il tempo ritrovato, 2019"},
  "08-25": {"anno": "calendario romano", "titulo": "Opiconsivia: solo para las vestales", "texto": "La fiesta de Ops, diosa de la abundancia de las cosechas, se celebraba en un santuario de la Regia en el que solo podían entrar las vestales y un sacerdote.", "mas": "Ops era la esposa de Saturno y la abundancia personificada; de su nombre viene opulentus. Su santuario estaba en la Regia, el antiguo palacio de los reyes en el Foro, y era tan sagrado que el sacerdote debía entrar con la cabeza cubierta con un velo blanco. Ese mismo día, del 79, murió en la playa de Estabias Plinio el Viejo.", "fuente": "Varrón, Sobre la lengua latina 6, 21; Festo, s. v. Opima; Plinio el Joven, Cartas 6, 16, 20"},
  "08-26": {"anno": "55 a. n. e.", "titulo": "César desembarca en Britania", "texto": "Hacia estas fechas, César cruza el canal con dos legiones. El portador del águila de la décima salta el primero al agua.", "mas": "César cuenta que sus soldados dudaban en saltar al mar con la armadura hasta que el aquilífero de la legión décima se lanzó gritando que saltaran si no querían entregar el águila al enemigo. La fecha se ha calculado a partir de las mareas y la luna llena que menciona César: el 26 o el 27 de agosto. Fue una expedición corta y casi desastrosa, pero en Roma se celebró con veinte días de acción de gracias.", "fuente": "César, Guerra de las Galias 4, 20-36; Dion Casio 39, 51-53"},
  "08-27": {"anno": "413 a. n. e.", "titulo": "Un eclipse condena a los atenienses en Sicilia", "texto": "El ejército ateniense está a punto de retirarse de Siracusa cuando se produce un eclipse de luna. El general Nicias decide esperar.", "mas": "Tucídides cuenta que Nicias, muy dado a los adivinos, aceptó esperar «tres veces nueve días» como mandaban los intérpretes. Los siracusanos aprovecharon el retraso para cerrar el puerto, y la expedición acabó en desastre: los atenienses murieron o acabaron trabajando en las canteras. El eclipse lunar del 27 de agosto del 413 a. n. e. permite fijar la fecha.", "fuente": "Tucídides 7, 50, 4 y 7, 86-87; Plutarco, Nicias 23"},
  "08-28": {"anno": "1749", "titulo": "Nace Goethe, que encontró Italia", "texto": "El autor del Fausto viajó a Italia en 1786 y descubrió la Antigüedad en piedra. Volvió convertido en clasicista.", "mas": "En su Viaje a Italia Goethe cuenta su llegada a Roma: «solo ahora empiezo a vivir». Escribió una Ifigenia en Táuride a la manera de Eurípides y unas Elegías romanas imitando a Propercio. En la segunda parte del Fausto, el protagonista se casa con Helena de Troya. Otro 28 de agosto, del 430, moría Agustín de Hipona, con su ciudad sitiada por los vándalos.", "fuente": "J. W. Goethe, Italienische Reise, 1816-1817; Posidio, Vida de Agustín 28-31"},
  "08-29": {"anno": "1780", "titulo": "Nace Ingres, pintor de Homero", "texto": "El pintor francés llenó sus lienzos de Antigüedad: Edipo ante la Esfinge, Júpiter y Tetis y una Apoteosis de Homero para el techo del Louvre.", "mas": "En la Apoteosis de Homero, el poeta, coronado por la Victoria, recibe el homenaje de los grandes autores de todos los tiempos: Esquilo, Píndaro, Virgilio, Dante, Molière. A sus pies, dos figuras femeninas representan la Ilíada y la Odisea. En Júpiter y Tetis, la nereida suplica a Zeus por su hijo Aquiles, tal como en el canto primero de la Ilíada.", "fuente": "J.-A.-D. Ingres, Apothéose d'Homère, 1827 (Louvre); Jupiter et Thétis, 1811 (Aix-en-Provence); Homero, Ilíada 1, 495-530"},
  "08-30": {"anno": "70 n. e.", "titulo": "Arde el Templo de Jerusalén", "texto": "Hacia estas fechas, el día 10 del mes de Loos, las tropas de Tito incendian el Templo durante el asedio de Jerusalén.", "mas": "Flavio Josefo, testigo del asedio desde el lado romano, dice que Tito quería salvar el Templo, pero un soldado lanzó una antorcha; otros autores le atribuyen la decisión de destruirlo. Josefo subraya que ardió el mismo día en que los babilonios habían destruido el primero. El arco de Tito, en el Foro, muestra a los soldados llevándose el candelabro de siete brazos.", "fuente": "Flavio Josefo, Guerra de los judíos 6, 249-266; Sulpicio Severo, Crónica 2, 30; Arco de Tito, Roma"},
  "08-31": {"anno": "12 y 161 n. e.", "titulo": "Calígula y Cómodo, el mismo cumpleaños", "texto": "Dos de los emperadores con peor fama nacieron un 31 de agosto: Calígula en el 12 y Cómodo en el 161.", "mas": "Suetonio dedica un capítulo a demostrar que Calígula nació en Antium el día antes de las calendas de septiembre, desmontando otras versiones. La Historia Augusta da la misma fecha para Cómodo, hijo de Marco Aurelio. Los dos subieron al trono jóvenes, se creyeron dioses y murieron asesinados por gente de su entorno.", "fuente": "Suetonio, Calígula 8; Historia Augusta, Cómodo 1, 2"},
  "09-01": {"anno": "22 a. n. e.", "titulo": "Un templo por un rayo en Cantabria", "texto": "Augusto dedica en el Capitolio un templo a Júpiter Tonante. Lo había prometido tras escapar de un rayo durante la guerra contra los cántabros.", "mas": "Suetonio cuenta que, en una marcha nocturna por Cantabria, un rayo rozó la litera de Augusto y mató al esclavo que iba delante con una antorcha. En agradecimiento, el emperador levantó a Júpiter Tonante, «el que truena», un templo de mármol macizo que se hizo muy popular. Según una anécdota, Júpiter Capitolino se le apareció en sueños quejándose de que le robaba los fieles.", "fuente": "Suetonio, Augusto 29, 3 y 91, 2; Augusto, Res gestae 19; Dion Casio 54, 4"},
  "09-02": {"anno": "31 a. n. e.", "titulo": "Batalla de Accio", "texto": "La flota de Octaviano y Agripa vence a la de Antonio y Cleopatra frente a la costa de Grecia.", "mas": "En plena batalla, la escuadra de Cleopatra rompió la línea y huyó hacia Egipto, y Antonio la siguió abandonando a su ejército. Octaviano fundó en el lugar la ciudad de Nicópolis, «ciudad de la victoria», y Virgilio puso la batalla en el centro del escudo de Eneas. Otro 2 de septiembre, del 44 a. n. e., Cicerón había pronunciado la primera de sus Filípicas contra Antonio.", "fuente": "Dion Casio 50, 31-35 y 51, 1, 1; Plutarco, Antonio 65-68; Virgilio, Eneida 8, 675-713"},
  "09-03": {"anno": "36 a. n. e.", "titulo": "Nauloco: Agripa derrota a Sexto Pompeyo", "texto": "Frente a la costa de Sicilia, la flota de Agripa destruye a la del hijo de Pompeyo, que dominaba el mar y mataba de hambre a Roma.", "mas": "Sexto Pompeyo controlaba Sicilia y cortaba el suministro de trigo a la capital. Agripa, el gran general de Octaviano, construyó una flota nueva, entrenó a las tripulaciones en un puerto artificial en el lago Averno y usó un arpón lanzado por catapulta, el harpax, para enganchar las naves enemigas. Recibió por la victoria una corona naval de oro.", "fuente": "Apiano, Guerras civiles 5, 118-122; Dion Casio 49, 8-11; Fastos de Amiterno"},
  "09-04": {"anno": "476 n. e.", "titulo": "Odoacro depone a Rómulo Augústulo", "texto": "El jefe militar Odoacro envía a una villa de Campania al último emperador de Occidente, un niño de unos quince años. No nombra a otro.", "mas": "Rómulo Augústulo llevaba los nombres del fundador de Roma y del primer emperador. Odoacro le concedió una pensión y mandó las insignias imperiales a Constantinopla, reconociendo al emperador de Oriente. Para los contemporáneos fue un cambio de gobierno más; la idea de que ese día «cayó el Imperio romano» se impuso mucho después.", "fuente": "Anónimo Valesiano 2, 8, 38; Jordanes, Getica 242-243; Marcelino Comes, Crónica, año 476"},
  "09-05": {"anno": "1908", "titulo": "Nace Arnaldo Momigliano", "texto": "El historiador italiano estudió cómo los antiguos escribían la historia y cómo los modernos han leído a los antiguos.", "mas": "Momigliano perdió su cátedra en Turín por las leyes raciales fascistas de 1938 y se exilió en Inglaterra. Sus padres murieron en un campo de exterminio nazi. Desde Londres renovó los estudios sobre historiografía antigua: Heródoto, Tucídides, los anticuarios. Es famoso por sus ensayos breves y su erudición enorme. Hoy empezaban, además, los Juegos Romanos.", "fuente": "A. Momigliano, Contributi alla storia degli studi classici, 1955-1992; Livio 1, 35, 9"},
  "09-06": {"anno": "394 n. e.", "titulo": "El río Frígido y el viento que cambió la historia", "texto": "Teodosio vence al usurpador Eugenio cuando un viento violento, la bora, sopla contra el ejército enemigo y le devuelve sus propias flechas.", "mas": "Eugenio contaba con el apoyo de la aristocracia pagana de Roma y llevaba estatuas de Júpiter en sus estandartes. El viento que sopló el segundo día de batalla fue interpretado por los cristianos como un milagro. El poeta Claudiano, pagano, lo celebró con un verso famoso: el viento combatía por el emperador. Fue la última vez que una religión antigua se jugó el poder en el campo de batalla.", "fuente": "Orosio 7, 35; Rufino, Historia eclesiástica 2, 33; Claudiano, Sobre el tercer consulado de Honorio 96-98"},
  "09-07": {"anno": "1533", "titulo": "Nace Isabel I, reina y traductora", "texto": "La reina de Inglaterra tradujo a Boecio, Horacio y Plutarco. Según los registros, terminó la Consolación de la filosofía en menos de un mes.", "mas": "Isabel recibió una educación humanista excepcional con Roger Ascham, que presumía de que ella leía más griego en un día que muchos canónigos latín en una semana. Ya reina, en 1593, tradujo el Consuelo de la filosofía de Boecio, el libro que el senador romano escribió en la cárcel antes de ser ejecutado en el 524. Se conserva el manuscrito, en parte de su mano.", "fuente": "R. Ascham, The Scholemaster, 1570; Queen Elizabeth's Englishings of Boethius, Plutarch and Horace, ed. C. Pemberton, 1899"},
  "09-08": {"anno": "s. VIII a. n. e.", "titulo": "Día de la Alfabetización: las letras fenicias", "texto": "Heródoto cuenta que los griegos aprendieron el alfabeto de los fenicios que llegaron con Cadmo, y que por eso llamaban a las letras phoinikéia.", "mas": "Los griegos tomaron los signos fenicios, que solo escribían consonantes, y usaron algunos que no les servían para representar vocales. Así nació el primer alfabeto completo. De él derivan el etrusco, el latino y, mucho después, el cirílico. Las primeras inscripciones griegas, del siglo VIII a. n. e., son versos escritos en vasos de vino.", "fuente": "Heródoto 5, 58; Copa de Néstor de Pitecusas (c. 730 a. n. e.)"},
  "09-09": {"anno": "1850", "titulo": "Nace Jane Harrison", "texto": "La helenista británica revolucionó el estudio de la religión griega mirando los ritos antes que los mitos. Fue de las primeras mujeres profesoras en Cambridge.", "mas": "Harrison sostuvo que muchos mitos nacieron para explicar rituales y que, bajo los dioses olímpicos, había una religión más antigua de demonios, muertos y fertilidad. Su libro Themis (1912) influyó en antropólogos y en poetas como T. S. Eliot. Virginia Woolf la menciona en Una habitación propia. Hacia este día, del 9 n. e., empezó la emboscada de Teutoburgo.", "fuente": "J. E. Harrison, Prolegomena to the Study of Greek Religion, 1903; Themis, 1912"},
  "09-10": {"anno": "1898", "titulo": "Sisí y su palacio de Aquiles", "texto": "La emperatriz Isabel de Austria, asesinada este día en Ginebra, había construido en Corfú un palacio dedicado a Aquiles y aprendido griego antiguo y moderno.", "mas": "Isabel admiraba a Aquiles, al que consideraba el héroe que despreciaba a reyes y tradiciones. En su palacio de Corfú, el Aquileion, colocó una estatua de Aquiles moribundo intentando arrancarse la flecha del talón. Tenía un profesor de griego que la acompañaba en sus largos paseos. Tras su muerte, el palacio lo compró el káiser Guillermo II.", "fuente": "Aquileion, Corfú; B. Hamann, Elisabeth. Kaiserin wider Willen, 1981"},
  "09-11": {"anno": "calendario romano", "titulo": "Septiembre: el séptimo que es el noveno", "texto": "Septiembre significa «séptimo mes», aunque sea el noveno. Varios emperadores intentaron ponerle su nombre, sin éxito.", "mas": "Cuando el año empezaba en marzo, septiembre era el séptimo. Al pasar el comienzo a enero, los nombres numéricos quedaron desfasados. Calígula quiso llamarlo Germanicus en honor de su padre, y Domiciano llamó Germanicus a septiembre y Domitianus a octubre. Los nombres cayeron con sus promotores. Solo resistieron julio y agosto.", "fuente": "Suetonio, Calígula 15, 2; Suetonio, Domiciano 13, 3; Macrobio, Saturnales 1, 12, 36-37"},
  "09-12": {"anno": "490 a. n. e.", "titulo": "Maratón, fecha tradicional", "texto": "Los atenienses y los plateos derrotan a los persas en la llanura de Maratón. El 12 de septiembre es un cálculo del siglo XIX que muchos discuten.", "mas": "Heródoto cuenta que los espartanos no llegaron a tiempo porque esperaban la luna llena para ponerse en marcha. A partir de ahí, el erudito August Böckh calculó el 12 de septiembre, pero otros prefieren agosto, porque el calendario espartano no coincidía con el ateniense. Murieron 192 atenienses, enterrados en el túmulo que todavía se ve en la llanura. Esquilo, que combatió allí, solo quiso que su epitafio recordara Maratón.", "fuente": "Heródoto 6, 102-117; Pausanias 1, 32, 3; Vida de Esquilo 11"},
  "09-13": {"anno": "509 a. n. e.", "titulo": "Se dedica el templo de Júpiter en el Capitolio", "texto": "En los idus de septiembre, el primer año de la República. Livio cuenta que en ese templo y en esa fecha se clavaba un clavo para llevar la cuenta de los años.", "mas": "Era el templo más importante de Roma, dedicado a la tríada capitolina: Júpiter, Juno y Minerva. Livio cita una vieja ley que mandaba al magistrado supremo clavar cada año un clavo en la pared del santuario, en tiempos en que pocos sabían escribir. Ese día, en el 81 n. e., murió el emperador Tito.", "fuente": "Livio 7, 3, 5-8; Plutarco, Publícola 14; Suetonio, Tito 11"},
  "09-14": {"anno": "1580", "titulo": "Nace Quevedo, lector de Séneca", "texto": "El soneto de Quevedo «Miré los muros de la patria mía» bebe de una carta de Séneca sobre la vejez y la muerte.", "mas": "En la carta 12 a Lucilio, Séneca cuenta que, al visitar su finca, vio que el edificio estaba viejo, que los árboles se secaban y que el portero, al que no reconoció, era un compañero de juegos de su infancia: todo le recordaba su propia vejez. Quevedo convierte esa experiencia en el soneto «Miré los muros...». Quevedo fue además un traductor y defensor apasionado de Séneca, al que consideraba un estoico casi cristiano.", "fuente": "Séneca, Cartas a Lucilio 12; F. de Quevedo, Heráclito cristiano, salmo 17"},
  "09-15": {"anno": "calendario romano", "titulo": "Los Juegos Romanos, en el Circo Máximo", "texto": "A mediados de septiembre, los Juegos Romanos, los más antiguos de la ciudad, pasaban del teatro a las carreras de carros del Circo Máximo.", "mas": "Los Juegos Romanos duraban del 5 al 19 de septiembre. El Circo Máximo, entre el Palatino y el Aventino, podía acoger según Plinio a 250.000 espectadores, y en época tardía quizá más. Las cuatro facciones, blancos, rojos, verdes y azules, tenían seguidores tan apasionados como los de cualquier equipo de fútbol, y los aurigas famosos se hacían inmensamente ricos.", "fuente": "Livio 1, 35, 9; Plinio el Viejo, Historia natural 36, 102; Dionisio de Halicarnaso 3, 68; CIL VI 10048 (Diocles)"},
  "09-16": {"anno": "por estas fechas", "titulo": "Quinientas cabras por los persas de Maratón", "texto": "Por estas fechas, en el mes de Boedromión, Atenas sacrificaba cada año quinientas cabras a Ártemis Cazadora para cumplir una promesa hecha antes de Maratón.", "mas": "Antes de la batalla, los atenienses habían prometido a Ártemis una cabra por cada persa que mataran. Murieron tantos que no había cabras suficientes en el Ática, así que decidieron pagar quinientas cada año. Jenofonte cuenta que, ochenta años después, todavía seguían sacrificándolas. Es un buen ejemplo de cómo los griegos negociaban con sus dioses.", "fuente": "Jenofonte, Anábasis 3, 2, 12; Aristóteles, Constitución de los atenienses 58, 1"},
  "09-17": {"anno": "14 n. e.", "titulo": "Augusto se convierte en dios", "texto": "Un mes después de su muerte, el Senado declara a Augusto dios. Un senador jura haber visto su alma subir al cielo desde la pira.", "mas": "El senador Numerio Atico juró haber visto a Augusto ascender al cielo, y Livia, según Dion Casio, le pagó un millón de sestercios por el testimonio. El nuevo dios recibió templo, sacerdotes y una cofradía de culto. Livia se convirtió en su sacerdotisa. Con el tiempo, la divinización de los emperadores muertos se volvió casi rutina; Séneca se burló de ella en la Apocolocintosis de Claudio.", "fuente": "Dion Casio 56, 46; Suetonio, Augusto 100, 4; Tácito, Anales 1, 10; Fastos de Amiterno"},
  "09-18": {"anno": "96 n. e.", "titulo": "Asesinan a Domiciano, nace Trajano", "texto": "Un liberto apuñala a Domiciano en su dormitorio. Ese mismo día era el cumpleaños de Trajano, que había nacido en Itálica en el 53.", "mas": "Suetonio cuenta que un astrólogo había predicho a Domiciano la hora de su muerte y que el emperador, nervioso, preguntó la hora; le dijeron que ya había pasado y se relajó. Le habían mentido. El Senado celebró su muerte y decretó borrar su nombre de las inscripciones. Dos años después llegaría al trono Trajano, nacido justo un 18 de septiembre.", "fuente": "Suetonio, Domiciano 16-17; Plinio el Joven, Panegírico 92, 4"},
  "09-19": {"anno": "86 n. e.", "titulo": "Nace Antonino Pío: «Ecuanimidad»", "texto": "El emperador más pacífico de Roma nació en Lanuvio. Al morir, dio al tribuno de guardia la última contraseña: aequanimitas.", "mas": "Antonino gobernó veintitrés años sin salir de Italia y sin grandes guerras. La Historia Augusta cuenta que, ya agonizante, encomendó el Estado a Marco Aurelio y dio al tribuno la consigna de la guardia: «ecuanimidad». Recibió el apodo de Pío por su devoción a su padre adoptivo, Adriano, cuya divinización defendió ante un Senado que le odiaba.", "fuente": "Historia Augusta, Pío 1, 8; 2, 3-7 y 12, 6"},
  "09-20": {"anno": "331 a. n. e.", "titulo": "Un eclipse anuncia Gaugamela", "texto": "Once días antes de la batalla decisiva contra Darío, la luna se eclipsa sobre el ejército de Alejandro. Un diario babilonio lo registra.", "mas": "Arriano y Plutarco cuentan que el adivino Aristandro interpretó el eclipse como un buen presagio para los macedonios. Una tablilla babilonia registra el eclipse y el pánico en el campamento persa, y once días después la derrota de Darío. Gracias a esa tablilla, la batalla puede fecharse con una precisión excepcional.", "fuente": "Arriano, Anábasis 3, 7, 6; Plutarco, Alejandro 31; diario astronómico babilonio (BM 36761)"},
  "09-21": {"anno": "19 a. n. e.", "titulo": "Muere Virgilio en Brindisi", "texto": "Volvía enfermo de Grecia y había pedido que se quemara la Eneida, que no había terminado de pulir. Augusto lo impidió.", "mas": "Según la Vida de Donato, Virgilio había ido a Grecia a revisar el poema y se encontró con Augusto en Atenas. Enfermó al visitar Mégara y murió en Brindisi. Pidió a sus amigos Vario y Tuca que quemaran la Eneida, pero Augusto ordenó publicarla tal como estaba, con los versos incompletos. Su epitafio dice: «Mantua me engendró, Calabria me arrebató, ahora me guarda Parténope».", "fuente": "Donato, Vida de Virgilio 35-42"},
  "09-22": {"anno": "por estas fechas", "titulo": "Los misterios de Eleusis", "texto": "Por estas fechas, en el mes de Boedromión, miles de iniciados caminaban de Atenas a Eleusis para vivir los misterios de Deméter. Nadie contó nunca qué veían.", "mas": "Durante casi dos mil años, hombres y mujeres, libres y esclavos, se iniciaron en Eleusis. La procesión recorría la vía sagrada, de unos veinte kilómetros. Revelar los secretos estaba castigado con la muerte: Alcibíades fue acusado de parodiarlos en una fiesta privada. Cicerón, que se inició, escribió que de allí se salía con una razón para vivir con alegría y morir con esperanza.", "fuente": "Himno homérico a Deméter; Cicerón, Sobre las leyes 2, 36; Tucídides 6, 28; Plutarco, Alcibíades 19"},
  "09-23": {"anno": "63 a. n. e.", "titulo": "Nace Octaviano, el futuro Augusto", "texto": "Nació en Roma, en el año del consulado de Cicerón y de la conjuración de Catilina.", "mas": "Suetonio cuenta que nació en el barrio del Palatino, en un lugar llamado Cabezas de Buey, poco antes del amanecer. El senador Octavio, su padre, llegó tarde al Senado ese día por el parto, y en la sesión se debatía la conjuración. El astrólogo Nigidio Fígulo, al conocer la hora, anunció que había nacido el señor del mundo. Su cumpleaños se convirtió en fiesta pública.", "fuente": "Suetonio, Augusto 5 y 94, 5"},
  "09-24": {"anno": "15 n. e.", "titulo": "Nace Vitelio, el emperador glotón", "texto": "Vitelio, emperador durante ocho meses del 69, tenía fama de comer cuatro veces al día y de hacerse servir platos de lenguas de flamenco.", "mas": "Suetonio cuenta que Vitelio pasó su juventud en Capri entre los favoritos de Tiberio. Su plato más famoso se llamaba «escudo de Minerva» y mezclaba hígados de escaro, sesos de faisán y pavo real, lenguas de flamenco y lechazas de murena. Suetonio da dos fechas posibles de nacimiento: el 24 de septiembre o el 7 de septiembre.", "fuente": "Suetonio, Vitelio 3 y 13; Tácito, Historias 2, 62"},
  "09-25": {"anno": "calendario romano", "titulo": "El equinoccio de César", "texto": "Para el calendario de César, el equinoccio de otoño caía hacia el 24 o 25 de septiembre. Hoy cae hacia el 22: el error del calendario juliano.", "mas": "El año juliano tenía 365 días y cuarto, unos once minutos más que el año solar. En siglos, el desfase se acumuló, y el equinoccio fue retrocediendo en el calendario. En 1582 el papa Gregorio XIII eliminó diez días para devolverlo a su sitio y retocó la regla de los bisiestos: los años acabados en 00 solo son bisiestos si se dividen por 400.", "fuente": "Columela 11, 2, 66; Plinio el Viejo, Historia natural 18, 309-312; bula Inter gravissimas, 1582"},
  "09-26": {"anno": "1687", "titulo": "Una bomba veneciana hace saltar el Partenón", "texto": "Durante el asedio veneciano de Atenas, un proyectil cae en el Partenón, que los otomanos usaban como polvorín. Explota y lo parte en dos.", "mas": "El Partenón había sobrevivido más de dos mil años casi entero: había sido templo de Atenea, iglesia y mezquita. La explosión mató a unas trescientas personas y destruyó el techo, buena parte de los muros interiores y numerosas esculturas. El general Morosini intentó después llevarse las esculturas del frontón y se le cayeron al suelo.", "fuente": "Relato de Anna Åkerhielm, 1687; T. Bowie y D. Thimme, The Carrey Drawings of the Parthenon Sculptures, 1971"},
  "09-27": {"anno": "1822", "titulo": "Champollion descifra los jeroglíficos", "texto": "El joven Champollion lee en la Academia de París su «Carta al señor Dacier», donde explica cómo funcionan los jeroglíficos. La clave fue el griego.", "mas": "La piedra de Rosetta contenía el mismo decreto en jeroglíficos, demótico y griego. Champollion, que dominaba el griego y el copto, comparó los nombres de Ptolomeo y Cleopatra en los cartuchos y entendió que los jeroglíficos combinaban signos fonéticos e ideográficos. Cuenta la leyenda que, al darse cuenta, gritó «¡Lo tengo!» y se desmayó.", "fuente": "J.-F. Champollion, Lettre à M. Dacier relative à l'alphabet des hiéroglyphes phonétiques, París, 1822"},
  "09-28": {"anno": "48 a. n. e.", "titulo": "Asesinan a Pompeyo la víspera de su cumpleaños", "texto": "Pompeyo desembarca en Egipto buscando refugio y lo matan en la barca, ante los ojos de su mujer. Al día siguiente habría cumplido 58 años.", "mas": "Los consejeros del joven rey Ptolomeo XIII pensaron que matar al derrotado ganaría el favor de César. Cuando le presentaron la cabeza, César, según Plutarco, apartó la mirada y lloró. Veleyo Patérculo subraya la crueldad del destino: el hombre que había celebrado su triunfo en su cumpleaños murió la víspera de cumplir años.", "fuente": "Plutarco, Pompeyo 77-80; Veleyo Patérculo 2, 53, 3-4"},
  "09-29": {"anno": "61 a. n. e.", "titulo": "Pompeyo celebra su triunfo en su cumpleaños", "texto": "Pompeyo celebra un triunfo de dos días sobre Mitrídates y Oriente, coincidiendo con su 45 cumpleaños.", "mas": "Plinio y Plutarco describen el desfile: tablillas con las naciones vencidas, un retrato de Pompeyo hecho de perlas, el tablero de juego de Mitrídates de piedras preciosas y carros cargados de oro. Pompeyo se presentaba como un nuevo Alejandro. Había nacido el 29 de septiembre del 106 a. n. e., el mismo año que Cicerón.", "fuente": "Plinio el Viejo, Historia natural 37, 13-16; Plutarco, Pompeyo 45; Veleyo Patérculo 2, 53, 4"},
  "09-30": {"anno": "420 n. e.", "titulo": "Muere Jerónimo, el traductor de la Vulgata", "texto": "Jerónimo muere en Belén. Su traducción latina de la Biblia fue el texto de Occidente durante más de mil años.", "mas": "Jerónimo era un excelente latinista, discípulo del gramático Donato. Cuenta en una carta que soñó que lo juzgaban ante Dios y que lo acusaban de ser «ciceroniano, no cristiano», por lo mucho que le gustaban los clásicos. Para traducir el Antiguo Testamento aprendió hebreo. Hoy es el Día Internacional de la Traducción, en su honor.", "fuente": "Jerónimo, Carta 22, 30; Próspero de Aquitania, Crónica, año 420"},
  "10-01": {"anno": "331 a. n. e.", "titulo": "Batalla de Gaugamela", "texto": "Alejandro derrota a Darío III y se abre el camino hacia Babilonia. Un diario astronómico babilonio permite fecharla con precisión.", "mas": "Darío eligió una llanura amplia, cerca de la actual Mosul, e hizo allanar el terreno para sus carros falcados. Alejandro desplazó su ataque en diagonal, abrió un hueco en el centro persa y cargó directamente hacia el rey, que huyó. Darío fue asesinado al año siguiente por sus propios sátrapas. La tablilla babilonia cuenta la huida de los soldados del rey.", "fuente": "Arriano, Anábasis 3, 7-15; Plutarco, Alejandro 31-33; diarios astronómicos babilonios"},
  "10-02": {"anno": "calendario romano", "titulo": "Las horas romanas cambiaban de tamaño", "texto": "Los romanos dividían el día, de la salida a la puesta del sol, en doce horas. En invierno cada hora duraba unos 45 minutos y en verano, unos 75.", "mas": "Por eso una cita «a la hora tercera» no significaba lo mismo en diciembre que en junio. La hora sexta era siempre el mediodía, y de ahí viene «siesta». La noche se dividía en cuatro vigilias, a la manera militar. Marcial describe en un epigrama cómo se repartían las horas en Roma: las primeras para saludar a los patronos, la novena para el baño, la décima para la cena.", "fuente": "Marcial, Epigramas 4, 8; Plinio el Viejo, Historia natural 7, 212-215; Censorino, Sobre el día natal 23"},
  "10-03": {"anno": "263 a. n. e.", "titulo": "El reloj de sol que marcó mal durante 99 años", "texto": "El primer reloj de sol de Roma lo trajo de Sicilia un cónsul como botín de guerra. Estaba calculado para Catania y en Roma no marcaba bien la hora.", "mas": "Plinio cuenta que Valerio Mesala lo trajo de Catania en el 263 a. n. e. y lo puso junto a los Rostra. Durante 99 años los romanos se rigieron por un reloj que no correspondía a su latitud, hasta que el censor Marcio Filipo instaló uno calculado para Roma. Más tarde Escipión Nasica puso un reloj de agua, que funcionaba también de noche y con nubes.", "fuente": "Plinio el Viejo, Historia natural 7, 213-215"},
  "10-04": {"anno": "1720", "titulo": "Nace Piranesi, el arquitecto de las ruinas", "texto": "El grabador veneciano dibujó Roma como nadie: ruinas gigantescas, cárceles imaginarias y una defensa apasionada de la arquitectura romana frente a la griega.", "mas": "Las Vedute di Roma de Piranesi, más de cien grabados, se vendieron por toda Europa y formaron la imagen que los viajeros del Grand Tour tenían de Roma antes de llegar. Muchos se decepcionaban al ver las ruinas reales, más pequeñas que en sus estampas. Piranesi escribió además contra quienes decían que los romanos solo habían copiado a los griegos.", "fuente": "G. B. Piranesi, Vedute di Roma, 1748-1778; Della magnificenza ed architettura de' Romani, 1761"},
  "10-05": {"anno": "1762", "titulo": "Orfeo y Eurídice de Gluck", "texto": "En Viena se estrena la ópera que reformó el género: menos adornos y más drama, al servicio de un mito griego.", "mas": "Gluck quiso que la música sirviera a la poesía y no al lucimiento de los cantantes. Su Orfeo, que baja al inframundo para recuperar a Eurídice y la pierde al mirarla, tiene un final feliz añadido: el Amor la devuelve a la vida. El aria «Che farò senza Euridice» es una de las más famosas de la historia. El mito ya lo contaban Virgilio en las Geórgicas y Ovidio en las Metamorfosis.", "fuente": "C. W. Gluck, Orfeo ed Euridice, 1762; Virgilio, Geórgicas 4, 453-527; Ovidio, Metamorfosis 10, 1-85"},
  "10-06": {"anno": "105 y 69 a. n. e.", "titulo": "Un día negro que acabó en victoria", "texto": "El 6 de octubre del 105 a. n. e., los cimbrios aniquilan a dos ejércitos romanos en Arausio. El mismo día, 36 años después, Lúculo gana en Tigranocerta.", "mas": "Arausio (la actual Orange, en Francia) fue una catástrofe comparable a Cannas, provocada por la rivalidad entre dos generales que se negaron a colaborar. El día quedó marcado como nefasto. Plutarco cuenta que, cuando antes de la batalla de Tigranocerta advirtieron a Lúculo de que era un día de mala suerte, respondió que él lo convertiría en día de suerte para los romanos.", "fuente": "Plutarco, Lúculo 27, 7-8; Livio, Periochae 67; Orosio 5, 16"},
  "10-07": {"anno": "186 a. n. e.", "titulo": "El Senado persigue las bacanales", "texto": "En las nonas de octubre, el Senado aprueba un decreto que limita los cultos de Baco en toda Italia. Se ha conservado grabado en bronce.", "mas": "Livio lo cuenta como un gran escándalo de sexo, crímenes y conspiración. El texto original del senadoconsulto, hallado en Calabria en 1640, es más sobrio: no prohíbe el culto, pero impide reuniones de más de cinco personas, juramentos secretos y cajas comunes sin permiso del Senado. Es uno de los documentos más antiguos del latín.", "fuente": "Livio 39, 8-19; Senatus consultum de Bacchanalibus (CIL I² 581)"},
  "10-08": {"anno": "451 n. e.", "titulo": "Se abre el concilio de Calcedonia", "texto": "Unos quinientos obispos se reúnen junto al Bósforo para definir la naturaleza de Cristo. La decisión dividió a la Iglesia oriental para siempre.", "mas": "El concilio estableció que en Cristo hay dos naturalezas, divina y humana, en una sola persona. Las iglesias de Egipto, Siria y Armenia lo rechazaron y formaron sus propias comunidades, que todavía existen. Las discusiones se hacían en griego, con un vocabulario filosófico heredado de Aristóteles y de los neoplatónicos.", "fuente": "Actas del concilio de Calcedonia; Evagrio Escolástico, Historia eclesiástica 2, 4"},
  "10-09": {"anno": "28 a. n. e.", "titulo": "Augusto dedica el templo de Apolo en el Palatino", "texto": "Junto a su casa, Augusto inaugura un templo de mármol blanco a Apolo, el dios que, según él, le dio la victoria en Accio.", "mas": "El templo tenía puertas de marfil, una estatua de Apolo citaredo y unos pórticos con estatuas de las cincuenta Danaides. A su lado había dos bibliotecas, una griega y otra latina, donde se reunían los poetas. Propercio describe la inauguración en una de sus elegías. Augusto guardó allí los libros sibilinos.", "fuente": "Propercio 2, 31; Dion Casio 53, 1, 3; Suetonio, Augusto 29, 3 y 31, 1"},
  "10-10": {"anno": "1582", "titulo": "Un día que no existió", "texto": "En España, Italia y Portugal, el 10 de octubre de 1582 nunca llegó. Del jueves 4 se pasó al viernes 15 para corregir el calendario de César.", "mas": "El papa Gregorio XIII eliminó diez días para devolver el equinoccio de primavera al 21 de marzo, como en tiempos del concilio de Nicea. Teresa de Jesús murió en Alba de Tormes justo la noche de ese salto, y por eso se dice que murió el 4 y la enterraron el 15. Otros países tardaron siglos en adoptar el cambio: Grecia, en 1923.", "fuente": "Bula Inter gravissimas, 24 de febrero de 1582"},
  "10-11": {"anno": "calendario romano", "titulo": "Meditrinalia: probar el vino nuevo", "texto": "Al probar por primera vez el mosto de la vendimia, los romanos decían: «Bebo el vino nuevo y el viejo; curo la enfermedad nueva y la vieja».", "mas": "Varrón explica que el nombre venía de mederi, «curar», el mismo verbo de «medicina». La fórmula, que mezcla el vino con la salud, era una pequeña oración para empezar la temporada. Más tarde se inventó una diosa, Meditrina, para dar nombre a la fiesta.", "fuente": "Varrón, Sobre la lengua latina 6, 21; Festo, s. v. Meditrinalia"},
  "10-12": {"anno": "19 a. n. e.", "titulo": "Augusto vuelve y nace una fiesta: las Augustalia", "texto": "Augusto regresa de Oriente y el Senado consagra un altar a la Fortuna del Regreso. El día se convertirá en fiesta anual con su nombre.", "mas": "Augusto volvía con un gran éxito diplomático: había recuperado de los partos las enseñas perdidas por Craso en Carras, sin librar una batalla. El altar de Fortuna Redux se levantó junto a la puerta Capena, por donde entró. Las Augustalia, con juegos, fueron la primera fiesta pública dedicada a un hombre vivo en Roma.", "fuente": "Augusto, Res gestae 11-12; Dion Casio 54, 10"},
  "10-13": {"anno": "54 n. e.", "titulo": "Muere Claudio, ¿envenenado con setas?", "texto": "Muere el emperador Claudio. Casi todas las fuentes antiguas acusan a su esposa Agripina de haberle servido un plato de setas envenenadas.", "mas": "Tácito cuenta que la envenenadora Locusta preparó el veneno y que, como no hacía efecto, un médico le metió una pluma envenenada en la garganta con la excusa de hacerle vomitar. Nerón, el hijo de Agripina, fue proclamado emperador ese mismo día. Más tarde bromearía con que las setas eran «comida de dioses», porque Claudio se había convertido en dios después de comerlas. Ese día era la Fontinalia, fiesta de las fuentes.", "fuente": "Tácito, Anales 12, 66-69; Suetonio, Claudio 44-45; Dion Casio 60, 34-35"},
  "10-14": {"anno": "1536", "titulo": "Muere Garcilaso, el Virgilio castellano", "texto": "El poeta toledano muere en Niza tras ser herido asaltando una torre. Sus églogas trasladan al castellano el mundo pastoril de Virgilio.", "mas": "Garcilaso aprendió de Petrarca y de los clásicos y llevó a la poesía española el soneto y el endecasílabo italianos. En la Égloga primera, los pastores Salicio y Nemoroso lloran sus amores, como en las Bucólicas. En la tercera, unas ninfas del Tajo bordan en sus telas historias de Orfeo, Apolo y Dafne y Venus y Adonis, sacadas de Ovidio.", "fuente": "Garcilaso de la Vega, Égloga I y Égloga III; Virgilio, Bucólicas"},
  "10-15": {"anno": "70 a. n. e.", "titulo": "Nace Virgilio cerca de Mantua", "texto": "El poeta de la Eneida, las Geórgicas y las Bucólicas nació en los idus de octubre. Ese día se sacrificaba en Roma un caballo de carreras a Marte.", "mas": "Virgilio era hijo de un campesino acomodado de Andes, cerca de Mantua. Fue tan venerado que el poeta Silio Itálico celebraba su cumpleaños con más devoción que el suyo propio y compró su tumba en Nápoles. El mismo día de su nacimiento, en Roma, el caballo derecho de la pareja vencedora en una carrera en el Campo de Marte se sacrificaba a Marte: el «caballo de octubre».", "fuente": "Donato, Vida de Virgilio 2; Plinio el Joven, Cartas 3, 7, 8; Festo, s. v. October equus"},
  "10-16": {"anno": "s. I-IV n. e.", "titulo": "Día de la Alimentación: el recetario de Apicio", "texto": "El único libro de cocina romana que conservamos lleva el nombre de Apicio, un famoso glotón de época de Tiberio. Casi todas las recetas llevan garum.", "mas": "De re coquinaria es una recopilación tardía, de hacia el siglo IV, atribuida al famoso gastrónomo. Incluye recetas de flamenco, lirón relleno, salsas agridulces y patinas de verduras. El garum, una salsa de pescado fermentado, aparece en casi todo; Hispania era una gran productora, como muestran las factorías de Baelo Claudia. Séneca cuenta que Apicio se suicidó al ver que solo le quedaban diez millones de sestercios.", "fuente": "Apicio, De re coquinaria; Séneca, Consolación a Helvia 10, 8-10; Plinio el Viejo, Historia natural 31, 93-94"},
  "10-17": {"anno": "por estas fechas", "titulo": "Las Pianepsias: potaje de legumbres para Apolo", "texto": "Por estas fechas, en el mes de Pianepsión, los atenienses cocinaban un potaje de legumbres para Apolo y los niños iban por las casas con una rama de olivo cargada de regalos.", "mas": "Según la leyenda, Teseo, al volver de Creta, hizo con los compañeros que había salvado del Minotauro un guiso con las provisiones que les quedaban. La rama, llamada eiresióne, iba adornada con lana, higos, pasteles y frascos de miel y aceite, y se colgaba en la puerta de la casa todo el año. Los niños cantaban una canción pidiendo regalos.", "fuente": "Plutarco, Teseo 22; Vida homérica de Heródoto 33 (canción de la eiresióne)"},
  "10-18": {"anno": "31 n. e.", "titulo": "Sejano cae en una sola sesión del Senado", "texto": "El hombre más poderoso de Roma después de Tiberio acude al Senado esperando recibir poderes nuevos. Le leen una carta del emperador y sale de allí arrestado.", "mas": "Sejano, prefecto del pretorio, gobernaba de hecho mientras Tiberio vivía en Capri. La larga y ambigua carta del emperador empezaba hablando de otras cosas y acababa ordenando su detención. Esa misma noche fue estrangulado y su cuerpo arrojado por las escaleras Gemonias. Juvenal se burla de la escena: la multitud que lo adoraba arrastra ahora sus estatuas.", "fuente": "Dion Casio 58, 9-11; Juvenal, Sátiras 10, 56-89; Fastos de Ostia, año 31"},
  "10-19": {"anno": "calendario romano", "titulo": "Armilustrium: purificar las armas", "texto": "Al terminar la temporada de guerra, las armas se purificaban en el Aventino. Los salios bailaban por última vez en el año con sus escudos.", "mas": "En Roma la guerra tenía estación: se abría en marzo, el mes de Marte, y se cerraba en octubre. La ceremonia del Armilustrium devolvía a los soldados, simbólicamente, a la vida civil. Varrón deriva el nombre de las armas y del verbo lustrare, purificar dando vueltas en procesión.", "fuente": "Varrón, Sobre la lengua latina 6, 22; Festo, s. v. Armilustrium"},
  "10-20": {"anno": "por estas fechas", "titulo": "Apaturias: los niños entran en la familia", "texto": "Por estas fechas, en Atenas, las fratrías celebraban las Apaturias: los padres presentaban a sus hijos y juraban que eran legítimos.", "mas": "Las fratrías eran asociaciones de familias que controlaban quién era ateniense. Durante tres días se celebraban banquetes, se cortaba el pelo a los muchachos que llegaban a la adolescencia y se inscribía a los recién nacidos. Ser inscrito en una fratría era la prueba de ciudadanía. Heródoto dice que todos los jonios celebraban esta fiesta, menos dos ciudades.", "fuente": "Heródoto 1, 147; Jenofonte, Helénicas 1, 7, 8; Platón, Timeo 21b"},
  "10-21": {"anno": "1858", "titulo": "Orfeo en los infiernos se ríe de los dioses", "texto": "Offenbach estrena en París una parodia del mito de Orfeo en la que los dioses del Olimpo bailan el cancán.", "mas": "En la versión de Offenbach, Orfeo y Eurídice se detestan, Júpiter es un mujeriego y la Opinión Pública obliga a Orfeo a ir a rescatar a su esposa. La obra se burlaba de la solemnidad de las óperas mitológicas y, de paso, de la corte de Napoleón III. El galop infernal del final se convirtió en la música del cancán.", "fuente": "J. Offenbach, Orphée aux enfers, libreto de H. Crémieux y L. Halévy, 1858"},
  "10-22": {"anno": "362 n. e.", "titulo": "Arde el templo de Apolo en Dafne", "texto": "En plena visita de Juliano a Antioquía, se quema el gran templo de Apolo del suburbio de Dafne. El emperador culpa a los cristianos.", "mas": "Amiano da la fecha: once días antes de las calendas de noviembre. Juliano había mandado sacar del recinto los restos del mártir Bábilas, que los cristianos veneraban allí. Los paganos culparon a los cristianos y los cristianos dijeron que había sido un rayo divino. Juliano, en represalia, cerró la catedral de Antioquía. Antioquía y Juliano no se entendieron nunca.", "fuente": "Amiano Marcelino 22, 13, 1-3; Juliano, Misopogon 361b; Juan Crisóstomo, Sobre san Bábilas"},
  "10-23": {"anno": "42 a. n. e.", "titulo": "Filipos: muere Bruto", "texto": "Hacia estas fechas, en la segunda batalla de Filipos, Antonio y Octaviano derrotan a Bruto, que se da muerte. Es el final de los asesinos de César.", "mas": "Unas semanas antes, en la primera batalla, Casio, creyendo perdida la partida, se había suicidado sin saber que Bruto había vencido en su ala. Plutarco cuenta que a Bruto se le había aparecido un fantasma que le anunció: «Nos volveremos a ver en Filipos». Shakespeare tomó la escena de la traducción de Plutarco de Thomas North. La fecha exacta es una reconstrucción moderna.", "fuente": "Plutarco, Bruto 36 y 48-52; Apiano, Guerras civiles 4, 128-131; Dion Casio 47, 48-49"},
  "10-24": {"anno": "51 n. e.", "titulo": "Nace Domiciano", "texto": "El último de los Flavios cazaba moscas con un punzón, según Suetonio, y gobernó cada vez con más miedo y más dureza.", "mas": "Suetonio cuenta que, al principio de su reinado, Domiciano pasaba horas encerrado cazando moscas, y que un liberto, al preguntarle si había alguien con el emperador, respondió: «Ni siquiera una mosca». Fue un administrador eficaz y un mal aliado del Senado, que borró su memoria tras matarlo. Construyó el estadio que hoy es la plaza Navona.", "fuente": "Suetonio, Domiciano 1 y 3; Plinio el Joven, Panegírico 48-49"},
  "10-25": {"anno": "por estas fechas", "titulo": "Tesmoforias: tres días sin hombres", "texto": "Por estas fechas, en el mes de Pianepsión, las mujeres casadas de Atenas celebraban las Tesmoforias en honor de Deméter. Los hombres no podían acercarse.", "mas": "Durante tres días, las mujeres acampaban en el santuario, ayunaban y recuperaban de unos pozos restos de lechones podridos que se mezclaban con las semillas para favorecer la cosecha. Aristófanes imaginó en Las Tesmoforiantes que las mujeres aprovechaban la fiesta para juzgar a Eurípides por hablar mal de ellas, y que un pariente del poeta se colaba disfrazado de mujer.", "fuente": "Aristófanes, Las Tesmoforiantes; Escolio a Luciano, Diálogos de las cortesanas 2, 1"},
  "10-26": {"anno": "1957", "titulo": "Muere Kazantzakis, que continuó la Odisea", "texto": "El autor de Zorba el griego dedicó catorce años a escribir una continuación de la Odisea de 33.333 versos.", "mas": "En su Odisea, publicada en 1938, Kazantzakis hace que Ulises, aburrido en Ítaca, vuelva a partir: pasa por Esparta, Creta y Egipto y termina en el polo sur. En su tumba de Heraclión se lee un epitafio célebre: «No espero nada. No temo nada. Soy libre». La Iglesia ortodoxa le negó el entierro religioso por La última tentación de Cristo.", "fuente": "N. Kazantzakis, Odisea, 1938; tumba de Kazantzakis, Heraclión"},
  "10-27": {"anno": "c. 1466", "titulo": "Nace Erasmo, el humanista de los proverbios", "texto": "Erasmo de Rotterdam reunió más de cuatro mil proverbios latinos y griegos explicados en sus Adagia, el libro de citas más leído del Renacimiento.", "mas": "Muchas expresiones que usamos vienen de los Adagia: «estar entre la espada y la pared», «una golondrina no hace verano», «abrir la caja de Pandora» (en realidad, en Hesíodo era una tinaja). Erasmo editó también el Nuevo Testamento en griego, que usó Lutero. Su fecha de nacimiento se discute: el 27 o el 28 de octubre, de 1466 o de 1469.", "fuente": "Erasmo, Adagiorum chiliades, 1508; Hesíodo, Trabajos y días 94"},
  "10-28": {"anno": "312 n. e.", "titulo": "Batalla del Puente Milvio", "texto": "Constantino vence a Majencio a las puertas de Roma. Lactancio cuenta el sueño que tuvo la víspera.", "mas": "Según Lactancio, Constantino soñó que debía poner en los escudos un signo cristiano. Eusebio, años después, habla de una cruz de luz en el cielo con las palabras «con este signo vencerás». Majencio se ahogó en el Tíber al hundirse el puente provisional. El arco de Constantino, junto al Coliseo, conmemora la victoria con relieves reutilizados de monumentos de Trajano, Adriano y Marco Aurelio.", "fuente": "Lactancio, Sobre la muerte de los perseguidores 44; Eusebio, Vida de Constantino 1, 28-38; Cronógrafo de 354"},
  "10-29": {"anno": "1959", "titulo": "Nace Astérix", "texto": "Goscinny y Uderzo publican en el primer número de la revista Pilote las aventuras de una aldea gala que resiste a los romanos.", "mas": "El cómic está lleno de latín: los piratas citan a César, los nombres de los campamentos romanos (Babaorum, Aquarium, Laudanum, Petibonum) son juegos de palabras y los legionarios gritan «¡Ave, César!». Muchos lectores han aprendido sus primeras frases latinas con Astérix, y en la Guerra de las Galias se puede comprobar qué hay de verdad detrás de algunos chistes.", "fuente": "R. Goscinny y A. Uderzo, Pilote nº 1, 29 de octubre de 1959"},
  "10-30": {"anno": "130 n. e.", "titulo": "Muere Antínoo en el Nilo", "texto": "El joven favorito de Adriano se ahoga en el Nilo durante un viaje imperial. Adriano funda en su memoria una ciudad y lo convierte en dios.", "mas": "Las circunstancias son oscuras: Dion Casio recoge rumores de que se ofreció en sacrificio para alargar la vida del emperador. Adriano, desolado, fundó Antinoópolis en el lugar y promovió su culto por todo Oriente. Las estatuas de Antínoo, con su cabeza inclinada y sus rizos, están entre las más reconocibles del arte romano.", "fuente": "Dion Casio 69, 11; Historia Augusta, Adriano 14, 5-7; Pausanias 8, 9, 7"},
  "10-31": {"anno": "1795", "titulo": "Nace Keats, el poeta de la urna griega", "texto": "El poeta romántico inglés escribió la Oda a una urna griega, que termina con una frase célebre: «La belleza es verdad, la verdad belleza».", "mas": "Keats no sabía griego. Descubrió a Homero en la traducción de Chapman, una noche de 1816, y escribió un soneto contando que se sintió como un astrónomo que descubre un planeta nuevo. Visitó los mármoles del Partenón en el Museo Británico. La urna de su oda no existe: es una mezcla de varias piezas que vio en Londres y en grabados.", "fuente": "J. Keats, «On First Looking into Chapman's Homer», 1816; «Ode on a Grecian Urn», 1819"},
  "11-01": {"anno": "82 a. n. e.", "titulo": "La puerta Colina: Sila toma Roma", "texto": "En las calendas de noviembre, Sila derrota a los samnitas y a los partidarios de Mario a las puertas de Roma. Empieza su dictadura.", "mas": "Fue una batalla nocturna y desesperada; el ala que mandaba Sila llegó a retroceder, y la salvó el ala de Craso. Al día siguiente Sila reunió al Senado en el templo de Belona mientras, a poca distancia, se masacraba a miles de prisioneros: los senadores oían los gritos. Después llegaron las proscripciones, listas públicas de enemigos a los que cualquiera podía matar.", "fuente": "Veleyo Patérculo 2, 27; Plutarco, Sila 29-31; Apiano, Guerras civiles 1, 93"},
  "11-02": {"anno": "1911", "titulo": "Nace Odysseas Elytis", "texto": "El poeta griego, premio Nobel en 1979, llevaba el nombre de Odiseo. Su Axion Esti mezcla la liturgia bizantina con la luz del Egeo.", "mas": "Elytis nació en Heraclión, en Creta, con el apellido Alepudelis; Elytis fue un nombre literario que relaciona con Hélade, esperanza (elpída) y libertad (eleftería). Su gran poema, Axion Esti («Digno es»), recorre la historia griega desde la creación del mundo, con el mar y el sol como protagonistas. Mikis Theodorakis le puso música.", "fuente": "O. Elytis, To Axion Esti, 1959; Fundación Nobel, 1979"},
  "11-03": {"anno": "39 n. e.", "titulo": "Nace Lucano en Corduba", "texto": "El sobrino de Séneca escribió a los veinte años la Farsalia, un poema épico sobre la guerra civil entre César y Pompeyo, sin dioses.", "mas": "Lucano fue amigo y después rival poético de Nerón, que le prohibió publicar. En la Farsalia no intervienen los dioses: la guerra es un crimen y el héroe es Catón, el republicano que se suicida antes de rendirse. Su verso más famoso dice que la causa vencedora agradó a los dioses, pero la vencida a Catón. Murió a los 25 años, obligado a suicidarse tras la conjura de Pisón.", "fuente": "Vida de Lucano de Vacca; Lucano, Farsalia 1, 128; Tácito, Anales 15, 70"},
  "11-04": {"anno": "1863", "titulo": "Los troyanos llegan a Cartago, en París", "texto": "Se estrena la segunda parte de Los troyanos de Berlioz, una ópera gigantesca sobre la Eneida que el compositor nunca vio entera.", "mas": "Berlioz había leído a Virgilio en latín de niño, con su padre, y lloraba con la muerte de Dido. Escribió él mismo el libreto: la caída de Troya y los amores de Eneas y Dido en Cartago. Los teatros la consideraron demasiado larga y solo se representó la segunda parte, recortada. La ópera completa no se estrenó hasta 1890, tras su muerte. Hoy empezaban, además, los Juegos Plebeyos.", "fuente": "H. Berlioz, Les Troyens, 1856-1858; Mémoires, cap. 2; Virgilio, Eneida 2 y 4"},
  "11-05": {"anno": "por estas fechas", "titulo": "Oscoforias: una carrera con racimos", "texto": "Por estas fechas, en Atenas, se celebraba una carrera de jóvenes con racimos de uvas en la mano, desde el templo de Dioniso hasta el puerto de Falero.", "mas": "La fiesta recordaba el regreso de Teseo de Creta. Dos jóvenes vestidos de mujer encabezaban la procesión, porque, según la leyenda, Teseo había llevado entre las muchachas destinadas al Minotauro a dos muchachos disfrazados. El vencedor de la carrera bebía una copa con vino, miel, queso, harina y aceite.", "fuente": "Plutarco, Teseo 23; Ateneo 11, 495f-496a; Proclo en Focio, Biblioteca 322a"},
  "11-06": {"anno": "355 n. e.", "titulo": "Juliano, de estudiante a César", "texto": "El emperador Constancio II nombra César a su primo Juliano, un joven de 23 años que estudiaba filosofía en Atenas, y lo envía a la Galia.", "mas": "Amiano da la fecha exacta: ocho días antes de los idus de noviembre. Juliano había sobrevivido de niño a la matanza de su familia y se había criado entre libros. Nadie esperaba gran cosa de él como general, pero venció a los alamanes en Estrasburgo y ganó el cariño de sus tropas, que acabaron proclamándolo Augusto.", "fuente": "Amiano Marcelino 15, 8, 17; Juliano, Carta a los atenienses 274-277"},
  "11-07": {"anno": "1913", "titulo": "Nace Camus, el del Sísifo feliz", "texto": "Albert Camus convirtió en símbolo del absurdo al rey Sísifo, condenado a empujar una roca que siempre vuelve a caer. Y concluyó que hay que imaginarlo feliz.", "mas": "En El mito de Sísifo (1942), Camus se pregunta si la vida vale la pena cuando no tiene un sentido último. Sísifo, que engañó a la muerte y fue castigado en el Hades, le sirve de imagen: el héroe absurdo que asume su tarea sin esperanza y sin rendirse. El castigo de Sísifo ya aparece en la Odisea, cuando Odiseo visita el reino de los muertos.", "fuente": "A. Camus, Le mythe de Sisyphe, 1942; Homero, Odisea 11, 593-600"},
  "11-08": {"anno": "63 a. n. e.", "titulo": "«¿Hasta cuándo, Catilina?»", "texto": "Cicerón pronuncia ante el Senado la primera Catilinaria, con Catilina sentado en la sala. Es el discurso latino más famoso de todos los tiempos.", "mas": "Cicerón, cónsul, había reunido al Senado en el templo de Júpiter Estátor. Los senadores se apartaron de Catilina, que se quedó solo en su banco. El discurso empieza sin preámbulo: «¿Hasta cuándo, Catilina, abusarás de nuestra paciencia?». Esa noche Catilina salió de Roma para unirse a sus tropas en Etruria. Salustio contó la conjuración pocos años después en su monografía.", "fuente": "Cicerón, Catilinarias 1; Salustio, Conjuración de Catilina 31; Plutarco, Cicerón 16"},
  "11-09": {"anno": "por estas fechas", "titulo": "Calqueas: la fiesta de los herreros", "texto": "Por estas fechas, a finales del mes de Pianepsión, los artesanos atenienses celebraban las Calqueas en honor de Hefesto y Atenea.", "mas": "Era la fiesta del bronce (chalkós) y de los oficios. El mismo día, las sacerdotisas y las arréforas empezaban a tejer en el telar el nuevo peplo de Atenea que se le entregaría nueve meses después en las Panateneas. En Atenas, Hefesto y Atenea compartían templo junto al ágora: el Hefestion, el templo griego mejor conservado.", "fuente": "Harpocración y Suda, s. v. Chalkeia; Pausanias 1, 14, 6"},
  "11-10": {"anno": "1759", "titulo": "Nace Schiller, que lloró a los dioses de Grecia", "texto": "El poeta alemán escribió «Los dioses de Grecia», un lamento por un mundo en el que la naturaleza estaba llena de ninfas y dioses.", "mas": "En el poema, publicado en 1788, Schiller contrapone la Grecia antigua, donde cada árbol tenía su dríade, con un mundo moderno desencantado, en el que solo quedan leyes físicas. Los versos causaron escándalo por parecer anticristianos. Schiller y Goethe fueron las grandes figuras del clasicismo de Weimar.", "fuente": "F. Schiller, «Die Götter Griechenlandes», Der Teutsche Merkur, 1788"},
  "11-11": {"anno": "397 n. e.", "titulo": "Martín, el soldado romano que partió su capa", "texto": "Hoy se enterró en Tours al obispo Martín, antiguo soldado romano. Su biógrafo cuenta que, en Amiens, partió su capa militar para dársela a un pobre.", "mas": "Martín había nacido en Panonia, hijo de un oficial, y sirvió en la caballería romana. Su biografía, escrita por Sulpicio Severo cuando Martín aún vivía, se convirtió en un modelo de vida de santos. La capa (cappa) partida dio nombre, según la tradición, a la «capilla» donde se guardaba y a los «capellanes» que la custodiaban.", "fuente": "Sulpicio Severo, Vida de Martín 3; Gregorio de Tours, Historia de los francos 1, 48"},
  "11-12": {"anno": "1648 o 1651", "titulo": "Nace sor Juana Inés de la Cruz", "texto": "La poeta mexicana aprendió latín en veinte lecciones, según cuenta ella, y escribió un auto sacramental sobre Narciso y un largo poema filosófico, el Sueño.", "mas": "Sor Juana cuenta en su Respuesta a sor Filotea que se cortaba el pelo si no aprendía una lección a tiempo, porque no le parecía bien tener la cabeza adornada de cabellos y desnuda de noticias. En El divino Narciso transforma el mito de Ovidio en una alegoría de Cristo. Su Primero sueño está lleno de referencias a la mitología clásica.", "fuente": "Sor Juana Inés de la Cruz, Respuesta a sor Filotea de la Cruz, 1691; El divino Narciso, 1689"},
  "11-13": {"anno": "354 n. e.", "titulo": "Nace Agustín de Hipona", "texto": "El propio Agustín cuenta que nació en los idus de noviembre, en Tagaste, en el norte de África. Ese día se celebraba el banquete de Júpiter.", "mas": "Lo dice en el diálogo Sobre la vida feliz, que empieza celebrando su cumpleaños con amigos en una villa cerca de Milán. Agustín fue profesor de retórica y lector apasionado de Cicerón: el Hortensio, un diálogo hoy perdido, le despertó el amor por la filosofía. Ese día, en Roma, se celebraba el Epulum Iovis, en el que las estatuas de los dioses se sentaban a la mesa.", "fuente": "Agustín, Sobre la vida feliz 1, 6; Agustín, Confesiones 3, 4, 7"},
  "11-14": {"anno": "1831", "titulo": "Muere Hegel, lector de Antígona", "texto": "Para el filósofo alemán, Antígona era la obra de arte más excelsa: un choque entre dos leyes igualmente justas, la de la familia y la de la ciudad.", "mas": "Hegel leyó en la tragedia de Sófocles un conflicto trágico de verdad: Antígona tiene razón al enterrar a su hermano y Creonte tiene razón al defender la ley de la ciudad, y ambos son destruidos por defender solo una parte. Su interpretación marcó durante dos siglos las lecturas filosóficas de la tragedia griega.", "fuente": "G. W. F. Hegel, Fenomenología del espíritu, 1807, cap. 6; Lecciones sobre la estética"},
  "11-15": {"anno": "200 a. n. e.", "titulo": "Plauto estrena en los Juegos Plebeyos", "texto": "Durante los Juegos Plebeyos de noviembre se representaban comedias. Una nota antigua dice que el Estico de Plauto se estrenó en los del 200 a. n. e.", "mas": "Las didascalias son pequeñas notas que acompañan a algunas comedias en los manuscritos: dicen en qué juegos se estrenaron, quién compuso la música y con qué obra griega se correspondían. Por ellas sabemos que el Estico es una adaptación de Menandro. Los Juegos Plebeyos duraban del 4 al 17 de noviembre.", "fuente": "Didascalia del Estico de Plauto; Livio 31, 4, 7"},
  "11-16": {"anno": "42 a. n. e.", "titulo": "Nace Tiberio", "texto": "El segundo emperador de Roma, hijo de Livia, que heredó el poder de su padrastro Augusto.", "mas": "Tiberio tenía tres años cuando su madre se divorció de su padre para casarse con Octaviano. Fue un general excelente y un emperador reacio y desconfiado. Tácito lo retrata como un maestro de la ambigüedad: los senadores nunca sabían lo que de verdad quería. Ese mismo año, en otoño, se libraba en Filipos la batalla que acabó con los asesinos de César.", "fuente": "Suetonio, Tiberio 5; Tácito, Anales 1, 11-13"},
  "11-17": {"anno": "9 n. e.", "titulo": "Nace Vespasiano", "texto": "Nació en una aldea de la Sabina, en una familia de recaudadores de impuestos. Llegaría a fundar una dinastía de emperadores.", "mas": "Suetonio subraya su origen modesto: su abuelo había sido centurión y cobrador, y su padre, recaudador en Asia y banquero en Helvecia. Bajo Nerón cayó en desgracia por dormirse durante uno de sus recitales. Fue el primer emperador que no pertenecía a la vieja aristocracia, y en su reinado se empezó el Coliseo.", "fuente": "Suetonio, Vespasiano 1-4"},
  "11-18": {"anno": "1959", "titulo": "Se estrena Ben-Hur", "texto": "La película de William Wyler, con la carrera de cuadrigas más famosa del cine, se estrena en Nueva York. Ganará once Óscar.", "mas": "Está basada en la novela de Lew Wallace (1880), escrita por un general de la guerra civil estadounidense. La carrera de cuadrigas, rodada en Cinecittà en un circo construido para la ocasión, llevó meses de rodaje. Las carreras reales eran aún más peligrosas: los aurigas llevaban las riendas atadas a la cintura y un cuchillo para cortarlas si volcaban. Ese día empezaban en Roma los días de mercado tras los Juegos Plebeyos.", "fuente": "W. Wyler (dir.), Ben-Hur, MGM, 1959; L. Wallace, Ben-Hur: A Tale of the Christ, 1880"},
  "11-19": {"anno": "1819", "titulo": "Abre el Museo del Prado", "texto": "Abre sus puertas en Madrid el Museo Real de Pinturas. Entre sus tesoros hay esculturas antiguas como el grupo de San Ildefonso.", "mas": "Las esculturas clásicas del Prado proceden sobre todo de las colecciones reales, en particular de las que compró Felipe V a la reina Cristina de Suecia. El grupo de San Ildefonso, dos jóvenes junto a un altar, ha recibido interpretaciones muy distintas: Cástor y Pólux, Orestes y Pílades o Antínoo y Adriano. Muchos de los cuadros más famosos del museo cuentan mitos de Ovidio.", "fuente": "Museo Nacional del Prado, E000028 (Grupo de San Ildefonso)"},
  "11-20": {"anno": "284 n. e.", "titulo": "Diocleciano, emperador", "texto": "Junto a Nicomedia, el ejército proclama a un oficial de origen humilde, Diocles. Gobernará más de veinte años y reorganizará todo el Imperio.", "mas": "Diocleciano mató con su propia mano al prefecto Áper, al que acusó del asesinato del emperador anterior. Después dividió el poder entre cuatro emperadores, duplicó las provincias, reformó los impuestos y fijó precios máximos para más de mil productos en un edicto que se ha conservado en parte. Fue el último gran perseguidor de los cristianos y el único emperador que se jubiló.", "fuente": "Historia Augusta, Caro 13; Lactancio, Sobre la muerte de los perseguidores 7; Edicto de precios máximos (301)"},
  "11-21": {"anno": "1694", "titulo": "Nace Voltaire, que debutó con Edipo", "texto": "Antes de ser el gran filósofo de la Ilustración, Voltaire triunfó con una tragedia sobre Edipo, que escribió en parte en la Bastilla.", "mas": "Voltaire estrenó su Edipo en 1718, con 24 años, y fue un éxito enorme. Lo había empezado mientras estaba encerrado en la Bastilla por unos versos satíricos. En sus cartas critica con descaro algunas inverosimilitudes de Sófocles: ¿cómo es posible que Edipo, tras años de matrimonio, nunca hubiera preguntado cómo murió el rey anterior?", "fuente": "Voltaire, Œdipe, 1718; Lettres sur Œdipe, 1719"},
  "11-22": {"anno": "s. I n. e.", "titulo": "Santa Cecilia, música: la canción más antigua", "texto": "En el día de la patrona de la música, la canción completa más antigua que conservamos: el epitafio de Seikilos, grabado con su notación musical en una columna.", "mas": "En una estela funeraria de Tralles, en la actual Turquía, un tal Seikilos grabó una breve canción con los signos musicales griegos encima de las sílabas. El texto viene a decir: mientras vivas, brilla, no sufras por nada; la vida dura poco y el tiempo exige su tributo. Se ha podido reconstruir la melodía y hoy se interpreta en conciertos. La estela está en el Museo Nacional de Copenhague.", "fuente": "Epitafio de Seikilos (Museo Nacional de Dinamarca, inv. 14897); M. L. West, Ancient Greek Music, 1992"},
  "11-23": {"anno": "2025 n. e.", "titulo": "Nace Ecos de nuestros clásicos", "texto": "Primer vídeo del canal. Desde entonces, Grecia y Roma leídas despacio y con las fuentes delante.", "mas": "Un 23 de noviembre murió también, en Madrid, Beatriz Galindo, la Latina, la humanista salmantina que enseñó latín en la corte de Isabel la Católica y dio nombre a un barrio de Madrid (las fuentes dudan entre 1534 y 1535). Nos parece buena compañía para un cumpleaños.", "fuente": "Ecos de nuestros clásicos; C. Segura Graíño, Miscelánea Comillas 69 (2011)"},
  "11-24": {"anno": "62 n. e.", "titulo": "Muere Persio, el poeta que escribió poco", "texto": "El joven poeta satírico muere con 27 años dejando un solo libro de sátiras, que fue un éxito inmediato.", "mas": "Según la vida antigua conservada con sus poemas, Persio murió de una enfermedad del estómago ocho días antes de las calendas de diciembre. Era un estoico convencido, discípulo de Cornuto, y dejó sus libros y dinero al maestro. Lucano, al oírle recitar, dijo que aquello era poesía de verdad. Hoy empezaban además las Brumalia, la fiesta bizantina del solsticio de invierno.", "fuente": "Vida de Persio; Juan Lido, Sobre los meses 4, 158"},
  "11-25": {"anno": "c. 449 a. n. e.", "titulo": "Contra la violencia hacia las mujeres: Virginia", "texto": "En el día contra la violencia hacia las mujeres, una historia de Livio: un padre mata a su hija para salvarla de un magistrado, y Roma se rebela.", "mas": "Según Livio, el decenviro Apio Claudio quiso apoderarse de Virginia, una joven plebeya, y la declaró esclava mediante un falso pleito. Su padre, Virginio, la mató antes que entregarla. El escándalo provocó una revuelta y la caída de los decenviros. Como la de Lucrecia, es una historia en que el cuerpo de una mujer se usa para contar un cambio político; muchos lectores modernos la han leído con incomodidad.", "fuente": "Livio 3, 44-58; Dionisio de Halicarnaso 11, 28-37"},
  "11-26": {"anno": "117 n. e.", "titulo": "Nace Elio Arístides, el orador hipocondríaco", "texto": "Arístides, el orador griego más admirado de su siglo, pasó años enfermo y escribió un diario de los sueños en que Asclepio le recetaba remedios.", "mas": "En sus Discursos sagrados cuenta cómo el dios le ordenaba bañarse en ríos helados, correr descalzo en invierno o tomar purgantes, y cómo él obedecía. Es el primer diario íntimo de enfermedad que conservamos. Escribió también un famoso elogio de Roma. La fecha de su nacimiento se deduce del horóscopo que él mismo incluye en sus escritos.", "fuente": "Elio Arístides, Discursos sagrados 47-52; Discurso 26 (A Roma); C. A. Behr, Aelius Aristides and the Sacred Tales, 1968"},
  "11-27": {"anno": "43 a. n. e.", "titulo": "Nace el segundo triunvirato", "texto": "Una ley entrega el poder a Antonio, Octaviano y Lépido durante cinco años. Pocos días después se publican las proscripciones; Cicerón está en la lista.", "mas": "La lex Titia legalizó el acuerdo que los tres habían hecho en una isla cerca de Bolonia. Las proscripciones buscaban dinero y venganza: cientos de senadores y caballeros fueron asesinados. Otro 27 de noviembre, del 8 a. n. e., murió Horacio, que fue enterrado junto a su amigo Mecenas, fallecido semanas antes.", "fuente": "Fastos Colocianos; Apiano, Guerras civiles 4, 2-7; Suetonio, Vida de Horacio"},
  "11-28": {"anno": "67 n. e.", "titulo": "Nerón declara libre a Grecia", "texto": "En los Juegos Ístmicos de Corinto, Nerón anuncia que libera a Grecia del gobierno provincial y de los impuestos. Una inscripción conserva su discurso.", "mas": "En la inscripción de Acrefia, en Beocia, se lee el discurso de Nerón en griego, con su fecha. Nerón había viajado a Grecia para competir en todos los juegos y ganó, por supuesto, todos los premios, incluida una carrera de carros en la que se cayó. Ese mismo viaje inició las obras del canal de Corinto, que se abandonaron a su muerte. La libertad de Grecia duró hasta Vespasiano.", "fuente": "Inscripción de Acrefia (IG VII 2713); Suetonio, Nerón 19 y 24; Plutarco, Flaminino 12"},
  "11-29": {"anno": "1898", "titulo": "Nace C. S. Lewis, que reescribió el mito de Psique", "texto": "El autor de Narnia era profesor de literatura en Oxford y Cambridge. Su novela favorita fue Mientras no tengamos rostro, sobre Eros y Psique.", "mas": "El mito de Eros y Psique lo cuenta Apuleyo en El asno de oro: una joven tan bella que provoca los celos de Venus se casa con un esposo al que nunca puede ver. Lewis lo cuenta desde el punto de vista de Orual, la hermana fea de Psique, que la acusa ante los dioses. Narnia, por su parte, está llena de faunos, centauros y dríades.", "fuente": "C. S. Lewis, Till We Have Faces, 1956; Apuleyo, Metamorfosis 4, 28-6, 24"},
  "11-30": {"anno": "1817", "titulo": "Nace Mommsen, el primer historiador con Nobel", "texto": "Theodor Mommsen escribió una Historia de Roma que le valió el premio Nobel de Literatura en 1902. Organizó además el gran corpus de inscripciones latinas.", "mas": "Mommsen escribía con pasión política: su Julio César es casi un héroe moderno. Su trabajo más duradero es el Corpus Inscriptionum Latinarum, que reúne decenas de miles de inscripciones de todo el Imperio y que se sigue publicando. En 1880 un incendio en su casa destruyó parte de su biblioteca y varios manuscritos prestados, entre ellos uno de Jordanes.", "fuente": "Th. Mommsen, Römische Geschichte, 1854-1856; Corpus Inscriptionum Latinarum, desde 1863; Fundación Nobel, 1902"},
  "12-01": {"anno": "calendario romano", "titulo": "Diciembre: el décimo mes y el mes de la fiesta", "texto": "Diciembre significa «décimo mes». Para los romanos era, sobre todo, el mes de las Saturnales, y Horacio lo llama sin más «la libertad de diciembre».", "mas": "Igual que septiembre, octubre y noviembre, diciembre conserva el número de cuando el año empezaba en marzo. En una de sus sátiras, Horacio deja hablar a su esclavo Davo aprovechando la libertas Decembri, la libertad de palabra de las Saturnales. Séneca, en cambio, se queja en una carta de que en diciembre toda la ciudad parece haberse vuelto loca.", "fuente": "Horacio, Sátiras 2, 7, 4-5; Séneca, Cartas a Lucilio 18, 1; Macrobio, Saturnales 1, 12, 37"},
  "12-02": {"anno": "por estas fechas", "titulo": "Dionisias rurales: teatro en los pueblos del Ática", "texto": "Por estas fechas, en el mes de Posideón, los pueblos del Ática celebraban sus propias Dionisias, con procesiones, falos de madera y, en algunos, teatro.", "mas": "En Los acarnienses, Aristófanes muestra a un campesino que celebra su Dionisia privada con su hija llevando la cesta y un esclavo con el falo, cantando a Fales, compañero de Dioniso. Algunos demos, como el Pireo, Eleusis o Tórico, tenían teatros propios donde se reponían tragedias y comedias. El teatro de Tórico, de forma rectangular, todavía se conserva.", "fuente": "Aristófanes, Acarnienses 237-279; Platón, República 475d; Teofrasto, Caracteres 3, 5"},
  "12-03": {"anno": "62 a. n. e.", "titulo": "Un hombre disfrazado en la fiesta de la Buena Diosa", "texto": "La noche de la Bona Dea, solo para mujeres, se celebró en casa de César. Clodio se coló vestido de flautista y fue descubierto.", "mas": "El rito lo presidían la esposa del cónsul o del pretor y las vestales, y ningún hombre podía estar presente, ni siquiera en estatua. Clodio, se decía, quería ver a Pompeya, la mujer de César. El escándalo acabó en juicio por sacrilegio; Clodio fue absuelto sobornando a los jueces. César se divorció de Pompeya con una frase célebre: la mujer del César no solo debe ser honesta, sino parecerlo.", "fuente": "Plutarco, César 9-10; Cicerón, Cartas a Ático 1, 12, 3 y 1, 16; Suetonio, César 6, 2"},
  "12-04": {"anno": "34 n. e.", "titulo": "Nace Persio en Volterra", "texto": "El poeta satírico, estoico y muy joven, nació la víspera de las nonas de diciembre. Escribió poco, despacio y con un estilo difícil.", "mas": "La vida antigua que acompaña a sus sátiras dice que era de carácter dulce, de pudor virginal y muy apegado a su madre, su hermana y su tía. Sus seis sátiras critican a los malos poetas, la hipocresía religiosa y la pereza de los jóvenes ricos.", "fuente": "Vida de Persio; Persio, Sátiras 1 y 3"},
  "12-05": {"anno": "63 a. n. e.", "titulo": "«Han vivido»: el Senado ejecuta a los catilinarios", "texto": "Tras un debate en que César pide clemencia y Catón la pena de muerte, Cicerón hace estrangular esa misma noche a cinco conjurados en la cárcel.", "mas": "Salustio reproduce los dos discursos, los de César y Catón, el texto de mi trabajo de fin de grado: dos maneras de entender la ley y la seguridad del Estado. Al salir de la cárcel, Cicerón anunció la ejecución con una sola palabra: vixerunt, «han vivido». Ejecutar a ciudadanos sin juicio le costaría el destierro cuatro años después.", "fuente": "Salustio, Conjuración de Catilina 50-55; Cicerón, Catilinaria IV; Plutarco, Cicerón 22"},
  "12-06": {"anno": "s. IV n. e.", "titulo": "Nicolás de Mira, obispo de una provincia romana", "texto": "El santo del que viene Santa Claus fue obispo en Mira, en la provincia romana de Licia, en la actual Turquía, a comienzos del siglo IV.", "mas": "Casi todo lo que se cuenta de él es leyenda: la más famosa dice que dejó caer por la ventana tres bolsas de oro para que tres hermanas pobres pudieran tener dote. Sus restos se los llevaron a Bari unos marineros italianos en 1087. Mira era una gran ciudad licia con un teatro romano y unas tumbas excavadas en la roca que todavía pueden visitarse.", "fuente": "Miguel el Archimandrita, Vida de Nicolás (s. IX)"},
  "12-07": {"anno": "43 a. n. e.", "titulo": "Asesinan a Cicerón", "texto": "Los sicarios de Antonio lo alcanzan cerca de Formias. Su cabeza y sus manos se exponen en la tribuna del Foro.", "mas": "Plutarco cuenta que Cicerón asomó la cabeza de la litera y miró fijamente a sus asesinos. Las manos que habían escrito las Filípicas se clavaron en los Rostra, desde donde tantas veces había hablado. Livio, citado por Séneca el Viejo, escribió que soportó como hombre solo una desgracia: la muerte. Años después, Augusto llamó a Cicerón «hombre elocuente y amante de su patria».", "fuente": "Plutarco, Cicerón 47-49; Séneca el Viejo, Suasorias 6, 17 y 22; Plutarco, Cicerón 49, 5"},
  "12-08": {"anno": "65 a. n. e.", "titulo": "Nace Horacio en Venusia", "texto": "El poeta del carpe diem era hijo de un liberto y llegó a ser amigo de Mecenas y de Augusto.", "mas": "Su padre, un liberto que había ahorrado como cobrador en las subastas, lo llevó a estudiar a Roma con los mejores maestros y luego a Atenas. Horacio luchó en Filipos en el bando de Bruto y huyó, según él mismo cuenta, dejando atrás el escudo. Perdonado, entró en el círculo de Mecenas, que le regaló una finca en la Sabina. Él mismo da en una oda el año de su nacimiento.", "fuente": "Suetonio, Vida de Horacio; Horacio, Sátiras 1, 6, 71-88; Horacio, Odas 2, 7, 9-10 y 3, 21, 1"},
  "12-09": {"anno": "1717", "titulo": "Nace Winckelmann, el padre de la historia del arte", "texto": "El hijo de un zapatero alemán convirtió el arte griego en un ideal: «noble sencillez y serena grandeza».", "mas": "Johann Joachim Winckelmann llegó a Roma en 1755 y fue prefecto de las antigüedades del Vaticano. En su Historia del arte en la Antigüedad (1764) ordenó por primera vez las obras en una evolución histórica. Admiraba la blancura del mármol, sin saber que las estatuas griegas estaban pintadas. Murió asesinado en Trieste en 1768 por un ladrón al que había enseñado unas monedas.", "fuente": "J. J. Winckelmann, Gedanken über die Nachahmung der griechischen Werke, 1755; Geschichte der Kunst des Alterthums, 1764"},
  "12-10": {"anno": "1953", "titulo": "Maria Callas es Medea en La Scala", "texto": "Con Leonard Bernstein a la batuta, la Callas canta en Milán la Medea de Cherubini y convierte a la hechicera de Eurípides en un personaje inolvidable.", "mas": "La ópera de Cherubini (1797) estaba casi olvidada. Callas la recuperó y la cantó durante años, y en 1969 Pasolini la eligió para interpretar a Medea en su película, sin cantar una sola nota. La Medea de Eurípides, estrenada en el 431 a. n. e., quedó tercera en el concurso de aquel año. Hoy se celebra además a Eulalia de Mérida, la mártir de Emerita Augusta a la que Prudencio dedicó un himno.", "fuente": "L. Cherubini, Médée, 1797; Eurípides, Medea, argumento; Prudencio, Peristephanon 3"},
  "12-11": {"anno": "calendario romano", "titulo": "Septimontium: la fiesta de los siete montes", "texto": "Hoy celebraban su fiesta los habitantes de los montes primitivos de Roma, un recuerdo de cuando la ciudad era solo un puñado de aldeas.", "mas": "Los montes del Septimontium no son exactamente las siete colinas clásicas: las listas antiguas incluyen el Palatino, la Velia, el Fagutal, el Cermalo, el Celio, el Opio y el Cispio. Era una fiesta de vecinos, no de toda la ciudad. Suetonio cuenta que el emperador Domiciano repartía comida ese día a senadores y caballeros.", "fuente": "Varrón, Sobre la lengua latina 5, 41 y 6, 24; Festo, s. v. Septimontium; Suetonio, Domiciano 4, 5"},
  "12-12": {"anno": "1821", "titulo": "Nace Flaubert, que resucitó Cartago", "texto": "El autor de Madame Bovary escribió Salambó, una novela ambientada en Cartago tras la primera guerra púnica, con mercenarios, elefantes y sacrificios.", "mas": "Flaubert se documentó durante años y viajó a Túnez para ver el lugar. Su fuente principal fue Polibio, que cuenta la terrible guerra de los mercenarios contra Cartago, a los que la ciudad no había pagado. La novela fue un éxito y un escándalo, y el arqueólogo Froehner la criticó por inventar demasiado. Flaubert le respondió, punto por punto, citando sus fuentes.", "fuente": "G. Flaubert, Salammbô, 1862; Polibio 1, 65-88"},
  "12-13": {"anno": "1797", "titulo": "Nace Heine, que imaginó a los dioses en el exilio", "texto": "El poeta alemán escribió un ensayo sobre los dioses griegos que, tras el triunfo del cristianismo, sobrevivieron disfrazados de campesinos y demonios.", "mas": "En Los dioses en el exilio (1853), Heine imagina a Apolo trabajando como pastor en Austria, a Mercurio como comerciante holandés y a Júpiter en una isla del Ártico cazando conejos. Era una forma irónica de contar cómo la mitología antigua siguió viva en el folclore y en el arte europeo. Heine estudió además con el filólogo Friedrich August Wolf.", "fuente": "H. Heine, Die Götter im Exil, 1853"},
  "12-14": {"anno": "mito", "titulo": "Los días alciónicos: calma en pleno invierno", "texto": "Los antiguos creían que, alrededor del solsticio de invierno, el mar se calmaba durante catorce días para que el alción, el martín pescador, pusiera sus huevos.", "mas": "Aristóteles ya recoge la creencia. Ovidio cuenta el mito: Alcíone, desesperada por la muerte en un naufragio de su marido Ceix, se arrojó al mar y los dioses los convirtieron a ambos en aves; su padre Eolo, dios de los vientos, calma el mar los días en que ella anida. De ahí la expresión inglesa halcyon days, «días felices».", "fuente": "Aristóteles, Historia de los animales 5, 8, 542b; Ovidio, Metamorfosis 11, 410-748"},
  "12-15": {"anno": "37 n. e.", "titulo": "Nace Nerón en Antium", "texto": "Su padre, al recibir las felicitaciones, dijo que de él y de Agripina no podía nacer nada que no fuera detestable y funesto para el Estado.", "mas": "Suetonio cuenta la frase de Domicio Ahenobarbo y añade que el niño nació al amanecer, cuando los rayos del sol lo tocaron antes que la tierra. Nerón fue un emperador apasionado por el canto, la poesía y las carreras, y gobernó bien sus primeros años bajo la tutela de Séneca. Ese día se celebraba la segunda Consualia del año.", "fuente": "Suetonio, Nerón 6; Tácito, Anales 13, 2"},
  "12-16": {"anno": "533 n. e.", "titulo": "Justiniano publica el Digesto", "texto": "Cincuenta libros con extractos de los grandes juristas romanos, ordenados por temas en tres años. Entrará en vigor el 30 de diciembre.", "mas": "La comisión de Triboniano leyó unos 2.000 libros de juristas clásicos, sobre todo de los siglos II y III, y seleccionó una vigésima parte. El Digesto (o Pandectas) es la gran mina del pensamiento jurídico romano. Un único manuscrito completo del siglo VI, conservado en Florencia, transmitió el texto a la Edad Media.", "fuente": "Constitución Tanta (Código de Justiniano 1, 17, 2); Codex Florentinus, Biblioteca Medicea Laurenziana"},
  "12-17": {"anno": "calendario romano", "titulo": "Empiezan las Saturnales", "texto": "Días de banquetes, regalos y mundo al revés: los esclavos podían hablar con libertad y comer con sus amos.", "mas": "Se cambiaba la toga por una túnica cómoda y un gorro de liberto, se jugaba a los dados y se regalaban velas y figuritas de barro. Marcial dedica dos libros enteros de epigramas a las etiquetas de los regalos. Plinio el Joven cuenta que, en esos días, se refugiaba en una habitación aislada de su villa para no estorbar ni ser estorbado por la fiesta.", "fuente": "Macrobio, Saturnales 1, 7-10; Marcial, Epigramas 13-14; Plinio el Joven, Cartas 2, 17, 24"},
  "12-18": {"anno": "mito", "titulo": "Día del Migrante: Eneas, el refugiado de Troya", "texto": "En el día de las personas migrantes, el héroe fundador de Roma: un refugiado que huye de una ciudad en llamas con su padre a hombros y su hijo de la mano.", "mas": "La Eneida cuenta el viaje de los troyanos supervivientes por el Mediterráneo, rechazados en varios lugares, hasta llegar al Lacio, donde tienen que negociar y luchar por un sitio. Los romanos, que se consideraban descendientes de aquellos refugiados, contaban también que Rómulo había abierto un asilo en el Capitolio para acoger a cualquiera que llegara.", "fuente": "Virgilio, Eneida 2, 707-729; Livio 1, 8, 5-6"},
  "12-19": {"anno": "69 n. e.", "titulo": "Arde el Capitolio", "texto": "En plena guerra civil, los partidarios de Vitelio asaltan el Capitolio, donde se habían refugiado los de Vespasiano. El templo de Júpiter arde.", "mas": "Tácito lo llama el crimen más lamentable y vergonzoso desde la fundación de Roma: el templo que ni Porsena ni los galos habían podido profanar fue quemado por romanos. Entre los refugiados estaba el joven Domiciano, hijo de Vespasiano, que escapó disfrazado de sacerdote de Isis. Su tío Flavio Sabino fue capturado y asesinado.", "fuente": "Tácito, Historias 3, 71-74; Suetonio, Domiciano 1, 2"},
  "12-20": {"anno": "69 n. e.", "titulo": "Muere Vitelio arrastrado por el Foro", "texto": "Las tropas de Vespasiano entran en Roma. Vitelio, escondido en la portería de palacio, es descubierto y asesinado en las escaleras Gemonias.", "mas": "Tácito y Suetonio cuentan su final con crueldad: se escondió en la garita del portero tras atrancar la puerta con un colchón, lo sacaron con las manos atadas y una soga al cuello, y la multitud le arrojó estiércol. Sus últimas palabras, según Tácito, fueron que él había sido emperador de quien lo insultaba. Había gobernado ocho meses.", "fuente": "Tácito, Historias 3, 84-85; Suetonio, Vitelio 16-17"},
  "12-21": {"anno": "calendario romano", "titulo": "Angerona y el nombre secreto de Roma", "texto": "En el solsticio se honraba a Angerona, una diosa representada con el dedo sobre los labios. Algunos decían que guardaba el nombre secreto de Roma.", "mas": "Plinio y Macrobio cuentan que Roma tenía un nombre secreto que no podía pronunciarse, para que los enemigos no pudieran llamar a su dios protector con conjuros. Un tribuno, Valerio Sorano, lo reveló y fue ejecutado. La estatua de Angerona, con la boca vendada y el dedo en los labios, se ha relacionado con ese silencio. Otros la vinculaban con la angina o con la angustia del día más corto del año.", "fuente": "Plinio el Viejo, Historia natural 3, 65; Macrobio, Saturnales 1, 10, 7-9 y 3, 9, 3-5"},
  "12-22": {"anno": "1848", "titulo": "Nace Wilamowitz, el gran filólogo alemán", "texto": "Ulrich von Wilamowitz-Moellendorff dominó la filología griega durante medio siglo. De joven arremetió contra Nietzsche.", "mas": "Wilamowitz editó y comentó a Eurípides, Esquilo, Píndaro y Calímaco, y escribió una obra inmensa. Su ideal era la Altertumswissenschaft, una ciencia total de la Antigüedad que uniera textos, inscripciones, arqueología e historia. Su ataque juvenil a El nacimiento de la tragedia de Nietzsche es una de las polémicas más famosas de la historia de la filología.", "fuente": "U. von Wilamowitz-Moellendorff, Zukunftsphilologie!, 1872; Erinnerungen 1848-1914, 1928"},
  "12-23": {"anno": "1906", "titulo": "Nace Alice Kober, la que preparó el desciframiento del lineal B", "texto": "Una profesora de latín y griego de Brooklyn analizó a mano miles de signos en fichas recortadas de paquetes de tabaco y descubrió las reglas del lineal B.", "mas": "Kober demostró que la lengua de las tablillas tenía flexión, es decir, que las palabras cambiaban de terminación, y agrupó los signos que compartían consonante o vocal. Trabajaba de noche, después de dar clase, y por la escasez de papel en la posguerra cortaba sus fichas de cajas de cigarrillos. Murió en 1950. Dos años después, Ventris, que había usado su método, descifró la escritura.", "fuente": "A. Kober, «Inflection in Linear Class B», AJA 50 (1946); M. Fox, The Riddle of the Labyrinth, 2013"},
  "12-24": {"anno": "3 a. n. e.", "titulo": "Nace Galba", "texto": "El emperador que sucedió a Nerón nació en una villa cerca de Terracina. Era de una de las familias más antiguas y ricas de Roma.", "mas": "Suetonio cuenta que Augusto, al verlo de niño, le pellizcó la mejilla y le dijo en griego: «Tú también, niño, probarás nuestro poder». Galba era famoso por su avaricia y su severidad. Cuando, ya anciano, se rebeló contra Nerón en Hispania, donde era gobernador, se proclamó «legado del Senado y del pueblo romano», no emperador.", "fuente": "Suetonio, Galba 4 y 10; Tácito, Historias 1, 49"},
  "12-25": {"anno": "calendario de 354 n. e.", "titulo": "El nacimiento del Sol Invicto", "texto": "El calendario romano del año 354 marca este día como fiesta del Sol Invicto y es también uno de los primeros documentos que sitúan hoy la Navidad.", "mas": "El Cronógrafo del 354 recoge en el calendario civil el Natalis Invicti y, en la lista de mártires, el nacimiento de Cristo en Belén «el 8 antes de las calendas de enero». Aureliano había dedicado un gran templo al Sol en el 274. Si la fecha cristiana se eligió por la fiesta solar o por otros cálculos (contando nueve meses desde una fecha supuesta de la anunciación) es una discusión abierta entre los historiadores.", "fuente": "Cronógrafo de 354; T. J. Talley, The Origins of the Liturgical Year, 1986"},
  "12-26": {"anno": "1890", "titulo": "Muere Schliemann en Nápoles", "texto": "El excavador de Troya se desmaya en una plaza de Nápoles y muere al día siguiente. Su tumba en Atenas es un pequeño templo griego.", "mas": "Schliemann había viajado para visitar Pompeya tras una operación de oído. Lo enterraron en el Primer Cementerio de Atenas, en un mausoleo diseñado por Ernst Ziller con un friso que lo muestra excavando Troya rodeado de héroes homéricos. Su casa de Atenas, el Iliou Melathron («Palacio de Ilión»), es hoy el Museo Numismático.", "fuente": "D. Traill, Schliemann of Troy, 1995; Museo Numismático de Atenas"},
  "12-27": {"anno": "537 n. e.", "titulo": "Se consagra Santa Sofía", "texto": "Justiniano inaugura en Constantinopla la iglesia de la Sabiduría Divina, con una cúpula que parecía colgar del cielo. Se construyó en menos de seis años.", "mas": "La diseñaron dos matemáticos, Antemio de Tralles e Isidoro de Mileto. Procopio describe la luz que entraba por las ventanas de la base de la cúpula, que parecía flotar sobre un anillo de luz. Durante casi mil años fue la iglesia más grande del mundo. La frase de Justiniano «¡Salomón, te he superado!» aparece en un relato muy posterior.", "fuente": "Procopio, Sobre los edificios 1, 1, 21-78; Pablo Silenciario, Descripción de Santa Sofía"},
  "12-28": {"anno": "por estas fechas", "titulo": "Haloas: una fiesta solo de mujeres en Eleusis", "texto": "Por estas fechas, en el mes de Posideón, las mujeres celebraban en Eleusis las Haloas en honor de Deméter y Dioniso, con banquetes y bromas obscenas.", "mas": "Según un escolio a Luciano, las mujeres comían juntas, bebían vino y se intercambiaban pasteles con forma de genitales, mientras las sacerdotisas les susurraban al oído consejos de adulterio. Los hombres preparaban la comida y se marchaban. La fiesta celebraba la fertilidad de la tierra en pleno invierno.", "fuente": "Escolio a Luciano, Diálogos de las cortesanas 7, 4; Demóstenes 59, 116"},
  "12-29": {"anno": "1809", "titulo": "Nace Gladstone, primer ministro y homerista", "texto": "El cuatro veces primer ministro británico escribió miles de páginas sobre Homero. Se le atribuye haber observado que en la Ilíada no hay palabra para «azul».", "mas": "En sus Studies on Homer (1858), Gladstone notó que Homero llama al mar «del color del vino» y que usa poco y raro el vocabulario del color, y concluyó, equivocadamente, que los griegos veían los colores de otra manera. La pregunta de cómo nombran los colores las distintas lenguas sigue interesando hoy a lingüistas y neurocientíficos.", "fuente": "W. E. Gladstone, Studies on Homer and the Homeric Age, 1858, vol. 3; Homero, Ilíada 5, 771"},
  "12-30": {"anno": "39 n. e.", "titulo": "Nace Tito, «amor y delicia del género humano»", "texto": "El hijo de Vespasiano, que destruyó Jerusalén y terminó el Coliseo, tuvo la mejor fama de todos los emperadores. Gobernó solo dos años.", "mas": "Suetonio dice que, al darse cuenta una noche de que no había hecho ningún favor a nadie en todo el día, exclamó: «Amigos, he perdido el día». Su breve reinado vio la erupción del Vesubio, un gran incendio en Roma y una epidemia. Inauguró el Coliseo con cien días de juegos. Otro 30 de diciembre, del 533, entró en vigor el Digesto.", "fuente": "Suetonio, Tito 1, 8 y 11; Dion Casio 66, 25"},
  "12-31": {"anno": "192 n. e.", "titulo": "Estrangulan a Cómodo en el baño", "texto": "La víspera de presentarse como cónsul vestido de gladiador, un atleta llamado Narciso estrangula a Cómodo. La conjura la organizaron su amante y sus ayudantes.", "mas": "Cómodo se creía Hércules y combatía en la arena como gladiador. Su amante Marcia y el prefecto Leto intentaron primero envenenarlo; como vomitó el veneno, enviaron a su compañero de lucha, Narciso, a terminar el trabajo. Dion Casio, senador, cuenta que había tenido que masticar hojas de laurel en el Coliseo para disimular la risa ante el emperador. Otro 31 de diciembre, del 406, vándalos, alanos y suevos cruzaban el Rin.", "fuente": "Dion Casio 72, 21-22 y 73, 22; Herodiano 1, 16-17; Próspero de Aquitania, Crónica, año 406"}
};
